// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Bayes çıkarımı, tanı testleri (duyarlılık, özgüllük, temel oran yanılgısı), karar ağaçları ve beklenen değer hesapları (orta).
const ozStatistics15Orta = <(String, String, List<String>, String)>[
  ('On sekizinci yüzyılın sonlarında Bayes teoremini bağımsız biçimde genel matematiksel formuna kavuşturan ve gök mekaniği hesaplarında kullanan bilim insanı kimdir?', 'Pierre-Simon Laplace', ['Siméon Denis Poisson', 'Jakob Bernoulli', 'Adolphe Quetelet'], 'Laplace, ters olasılık ilkesini genel formülasyonuyla geliştirmiş ve Satürn ile Jüpiter yörünge tahminlerinde başarıyla uygulamıştır.'),
  ('İki rakip hipotez arasında verinin hangisini kaç kat daha güçlü desteklediğini ölçen P(V | H1) / P(V | H2) oranına ne ad verilir?', 'Bayes çarpanı', ['Varyans şişme çarpanı', 'Serbestlik derecesi oranı', 'Güven aralığı genişliği'], 'Önsel bahis oranını sonsal bahis oranına dönüştüren P(V|H1)/P(V|H2) kesri Bayes çarpanı veya olabilirlik oranı olarak bilinir.'),
  ('Klasik (frekansçı) istatistik ile Bayesçi istatistik arasındaki en temel felsefi ayrım aşağıdakilerden hangisinde doğru özetlenmiştir?', 'Bayesçi yaklaşımda bilinmeyen parametreler olasılık dağılımına sahip rastgele nicelikler gibi ele alınır', ['Frekansçı yaklaşımda deney verileri toplanmadan önce her parametreye öznel bir ağırlık verilir', 'Bayesçi yöntemler yalnızca kesikli verilerde çalışırken frekansçı yöntemler sürekli verilerde çalışır', 'Frekansçı yaklaşımda örneklem büyüdükçe parametre tahmini her zaman başlangıç inancına yakınsar'], 'Frekansçılar parametreyi sabit bir bilinmeyen kabul ederken Bayesçiler parametre hakkındaki belirsizliği olasılık dağılımıyla modeller.'),
  ('Bir tohum ıslah uzmanı yeni bir buğday türünün kuraklığa dayanıklı olma olasılığını başlangıçta %20 olarak tahmin ediyor. Yapılan ilk sera testini dayanıklı türlerin %90\'ı, dayanıksız türlerin ise %30\'u geçebiliyor. Sera testini geçen bu türün gerçekten dayanıklı olma olasılığı kaçtır?', '%42,86 (3/7)', ['%60,00 (3/5)', '%75,00 (3/4)', '%33,33 (1/3)'], 'Pay = 0,20×0,90 = 0,18; Payda = 0,18 + 0,80×0,30 = 0,18 + 0,24 = 0,42. Sonsal olasılık 0,18/0,42 = 3/7 ≈ %42,86 bulunur.'),
  ('Üç özdeş çekmeceli bir antika dolabın ilk çekmecesinde iki altın sikke, ikincisinde bir altın bir gümüş sikke, üçüncüsünde iki gümüş sikke vardır. Rastgele seçilen bir çekmeceden bakmadan alınan ilk sikke altın çıktığına göre, aynı çekmecedeki diğer sikkenin de altın olma olasılığı kaçtır?', '2/3', ['1/2', '1/3', '3/4'], 'Bertrand\'ın kutu paradoksunda altın sikke çekilmesi 3 eş olası altın yüzünden gelir; bunların 2\'si çift altınlı çekmecededir, cevap 2/3\'tür.'),
  ('Gözlemlenen örneklem hacmi sonsuza giderken (çok miktarda bağımsız veri toplandığında) sıfırdan farklı iki farklı önsel inanca sahip araştırmacının sonsal dağılımları nasıl davranır?', 'Önsel inançların etkisi silikleşir ve her iki araştırmacının sonsal dağılımı aynı gerçek değere yakınsar', ['Araştırmacılar arasındaki başlangıç farkı veri sayısıyla doğru orantılı olarak giderek açılır', 'Sonsal dağılımlar veriden bağımsızlaşarak her araştırmacının kendi önsel ortalamasına sabitlenir', 'Veri miktarı arttıkça normalleştirme paydası sıfıra yaklaşacağından sonsal olasılık tanımsızlaşır'], 'Bernstein-von Mises teoremi uyarınca veri biriktikçe olabilirlik fonksiyonu baskın hale gelir ve makul önsellerin etkisi ortadan kalkar.'),
  ('Mahkemede bir uzman tanık, \'Masum bir kişide bu DNA profilinin rastgele eşleşme olasılığı milyonda birdir; dolayısıyla sanığın masum olma olasılığı da milyonda birdir\' dediğinde P(Kanıt|Masum) ile P(Masum|Kanıt) değerlerini birbirine karıştırmış olur. Hukuk ve istatistik literatüründe bu hataya ne ad verilir?', 'Savcı yanılgısı', ['Berkson paradoksu', 'Simpson yanılgısı', 'Hayatta kalma yanlılığı'], 'Koşullu olasılığın yönünü ters çevirerek önsel suçluluk oranını yok sayma hatası literatürde savcı yanılgısı olarak adlandırılır.'),
  ('Bayes teoremindeki paydada yer alan P(Veri) teriminin (marjinal olabilirlik) temel matematiksel işlevi nedir?', 'Tüm olası hipotezler üzerinden sonsal olasılıkların toplamının tam 1\'e eşitlenmesini sağlamak', ['Önsel olasılığın sıfıra eşit olduğu hipotezleri yeniden pozitif değerlere yükseltmek', 'Örneklemdeki aykırı gözlemleri veri kümesinden otomatik olarak budamak', 'Hipotez uzayındaki bağımlı olayları birbirinden istatistiksel olarak bağımsız kılmak'], 'P(Veri) normalleştirme sabitidir; paydaki P(H_i)P(V|H_i) terimlerini bölerek geçerli bir olasılık dağılımı (toplamı 1) elde edilmesini sağlar.'),
  ('Bir kutuda dış görünüşü aynı olan iki madeni paradan biri hilesizdir (%50 yazı), diğeri ise her iki yüzü de yazı olan hileli paradır (%100 yazı). Rastgele seçilen bir para havaya atıldığında üst üste 3 kez yazı gelirse, seçilen paranın hileli para olma olasılığı kaçtır?', '8/9', ['3/4', '7/8', '4/5'], 'P(3Y|Hileli)=1, P(3Y|Hilesiz)=(1/2)^3=1/8. Eşit önselle (1/2): Sonsal = (1/2 × 1) / (1/2 × 1 + 1/2 × 1/8) = 1 / (9/8) = 8/9 bulunur.'),
  ('Yeni gözlemlenen bir kanıt E\'nin, H hipotezinin sonsal olasılığını önsel olasılığından hiçbir şekilde değiştirmemesi (yani P(H|E) = P(H) çıkması) için hangi koşul gerçekleşmelidir?', 'Kanıtın gerçekleşme olasılığının H doğruyken ve H yanlışken birbirine eşit olması', ['Hipotezin önsel olasılığının tam 0,50 değerine eşit seçilmiş olması', 'Kanıtın toplam gerçekleşme olasılığının 0,10 değerinin altında kalması', 'Hipotez ile kanıtın kesişim kümesinin boş küme olması'], 'P(E|H) = P(E|H\') olduğunda olabilirlik oranı 1 olur; kanıt hipotez hakkında hiçbir ayırt edici bilgi taşımadığı için olasılık değişmez.'),
  ('Bir dilbilimci yazarı belirsiz bir elyazmasının Yazar K\'ye ait olma olasılığını 0,60, Yazar M\'ye ait olma olasılığını 0,40 olarak değerlendiriyor. Metinde geçen nadir bir bağlacı K metinlerinin %10\'unda, M ise metinlerinin %30\'unda kullanmaktadır. Elyazmasında bu bağlaç bulunduğuna göre metnin Yazar M\'ye ait olma olasılığı kaçtır?', '2/3', ['3/5', '1/2', '3/4'], 'P(M|Bağlaç) = (0,40 × 0,30) / (0,60 × 0,10 + 0,40 × 0,30) = 0,12 / (0,06 + 0,12) = 0,12 / 0,18 = 2/3 olarak hesaplanır.'),
  ('Monty Hall probleminde üç kapıdan birinin arkasında otomobil, ikisinin arkasında keçi vardır. Yarışmacı 1. kapıyı seçtikten sonra kapıların yerini bilen sunucu keçi olan 3. kapıyı açar. Yarışmacı kararını 2. kapıyla değiştirirse otomobili kazanma sonsal olasılığı ne olur?', '1/3\'ten 2/3\'e yükselir', ['1/3\'ten 1/2\'ye yükselir', '1/3 düzeyinde sabit kalır', '1/2\'den 3/4\'e yükselir'], 'Sunucunun 1. kapıyı açamaması ve bilerek keçi kapısını seçmesi asimetrik kanıt üretir; 2. kapının sonsal olasılığı 2/3 olur.'),
  ('Bir gökbilimci keşfedilen sönük bir gök cisminin kuyruklu yıldız olma önsel olasılığını 0,25, asteroit olma olasılığını 0,75 olarak belirliyor. Spektral analizde buz buharı izi görülme olasılığı kuyruklu yıldızlarda 0,84, asteroitlerde 0,04\'tür. Buz buharı saptanan bu cismin kuyruklu yıldız olma olasılığı kaçtır?', '7/8', ['5/6', '4/5', '9/11'], 'Pay = 0,25 × 0,84 = 0,21. Payda = 0,21 + 0,75 × 0,04 = 0,21 + 0,03 = 0,24. Sonsal olasılık = 0,21 / 0,24 = 21/24 = 7/8\'dir.'),
  ('İki ayrık hipotez için önsel bahis oranı O(H1:H2) = 1:5 olarak verilmiştir. Gözlemlenen deneysel kanıt H1 hipotezinde H2 hipotezine kıyasla 15 kat daha olasıysa (Bayes çarpanı = 15), sonsal olasılık P(H1 | Kanıt) kaçtır?', '0,75', ['0,60', '0,80', '0,85'], 'Sonsal bahis oranı = Önsel bahis × Bayes çarpanı = (1/5) × 15 = 3:1 olur. Bahis oranı 3:1 ise olasılık 3 / (3 + 1) = 0,75\'tir.'),
  ('Bir veteriner kliniğine getirilen halsiz bir kedinin viral enfeksiyon taşıma önsel olasılığı 0,15\'tir. Ateş ölçümü viral enfeksiyonlu kedilerin %80\'inde, diğer halsizlik nedenlerinin ise %20\'sinde yüksek çıkar. Ateşi yüksek çıkan bu kedide viral enfeksiyon bulunma olasılığı kaçtır?', '12/29', ['6/17', '15/34', '8/19'], 'Pay = 0,15 × 0,80 = 0,12. Payda = 0,12 + 0,85 × 0,20 = 0,12 + 0,17 = 0,29. Sonsal olasılık = 12/29 olarak elde edilir.'),
  ('Bir botanik bahçesinde bulunan nadir orkide tohumlarının %40\'ı A tedarikçisinden, %60\'ı B tedarikçisinden alınmıştır. A\'nın tohumları %80, B\'nin tohumları %50 oranında beyaz çiçek açmaktadır. Rastgele ekilen bir tohum pembe (beyaz olmayan) çiçek açtığına göre A tedarikçisinden gelmiş olma olasılığı kaçtır?', '4/19', ['8/19', '2/9', '1/5'], 'Pembe açma olasılıkları: A için 0,20; B için 0,50. Sonsal = (0,40 × 0,20) / (0,40 × 0,20 + 0,60 × 0,50) = 0,08 / (0,08 + 0,30) = 8/38 = 4/19.'),
  ('Frekansçı güven aralığından farklı olarak, \'Bilinmeyen parametrenin bu aralıkta bulunma olasılığı veriler ışığında %95\'tir\' şeklinde doğrudan olasılıksal yorum yapılabilen Bayesçi aralığa ne ad verilir?', 'İnanılırlık aralığı', ['Tolerans sapma bandı', 'Kalıntı kareler aralığı', 'Asimptotik p-değeri dilimi'], 'Sonsal dağılımın altında %95 alan bırakan bölgeye Bayesçi inanılırlık aralığı (credible interval) denir ve doğrudan olasılıkla yorumlanır.'),
  ('Bir sanat galerisine getirilen tablonun orijinal Rönesans eseri olma önsel olasılığı %10\'dur. Karbon-14 ve pigment analizinden orijinal eserlerin %95\'i geçerken, ustaca yapılmış taklitlerin de %15\'i geçebilmektedir. Analizden başarıyla geçen bu tablonun gerçekten orijinal olma olasılığı kaçtır?', '19/46', ['19/22', '9/23', '11/28'], 'Pay = 0,10 × 0,95 = 0,095. Payda = 0,095 + 0,90 × 0,15 = 0,095 + 0,135 = 0,230. Sonsal olasılık = 95/230 = 19/46 bulunur.'),
  ('Bir sigorta şirketi sürücüleri dikkatli (%70) ve dikkatsiz (%30) olarak iki sınıfa ayırıyor. Bir yıl içinde kaza yapma olasılığı dikkatli sürücülerde 0,05 iken dikkatsiz sürücülerde 0,25\'tir. Poliçesinin ilk yılında hiç kaza yapmayan bir sürücünün dikkatli sınıfta yer alma olasılığı kaçtır?', '133/178', ['7/10', '19/25', '63/88'], 'Kaza yapmama olasılıkları: Dikkatli = 0,95; Dikkatsiz = 0,75. Pay = 0,70 × 0,95 = 0,665. Payda = 0,665 + 0,30 × 0,75 = 0,665 + 0,225 = 0,890. Oran = 665/890 = 133/178.'),
  ('Bir arıcılık işletmesinde kovanların %80\'i sağlıklı, %20\'si parazitlidir. Kış sonunda bal veriminin düşük çıkma olasılığı parazitli kovanlarda 0,75, sağlıklı kovanlarda 0,10\'dur. Bal verimi düşük çıkan bir kovanın parazitli olma olasılığı yüzde kaçtır?', '%65,22 (15/23)', ['%55,00 (11/20)', '%75,00 (3/4)', '%48,39 (15/31)'], 'Pay = 0,20 × 0,75 = 0,15. Payda = 0,15 + 0,80 × 0,10 = 0,15 + 0,08 = 0,23. Sonsal olasılık = 15/23 ≈ %65,22\'dir.'),
  ('Bir balıkçı teknesindeki sonar cihazı, altında uskumru sürüsü varken %90 olasılıkla, sürü yokken ise su altı akıntıları yüzünden %18 olasılıkla sinyal üretiyor. Bölgede sürü bulunma önsel olasılığı 1/6 ise, sonar sinyal verdiğinde aşağıda gerçekten uskumru sürüsü bulunma olasılığı kaçtır?', '0,50', ['0,60', '0,75', '0,45'], 'Önsel bahis = (1/6) / (5/6) = 1/5. Olabilirlik oranı = 0,90 / 0,18 = 5. Sonsal bahis = (1/5) × 5 = 1:1 olduğundan olasılık tam 0,50\'dir.'),
  ('Bir kahve tadım uzmanı önüne konan fincanın Kolombiya çekirdeği olma olasılığını %30, Etiyopya çekirdeği olma olasılığını %70 olarak biliyor. Fincanda narenciye aroması algılama olasılığı Etiyopya kahvelerinde %80, Kolombiya kahvelerinde %20\'dir. Uzman narenciye aroması almadığını söylediğine göre fincanın Kolombiya kahvesi olma olasılığı kaçtır?', '12/19', ['7/19', '6/13', '3/10'], 'Narenciye almama olasılıkları: Kolombiya = 0,80; Etiyopya = 0,20. Pay = 0,30 × 0,80 = 0,24. Payda = 0,24 + 0,70 × 0,20 = 0,24 + 0,14 = 0,38. Oran = 24/38 = 12/19.'),
  ('Sonsal dağılım üzerinden tek bir nokta tahmini raporlamak isteyen bir veri bilimci, sonsal yoğunluk fonksiyonunun en yüksek tepe noktasına karşılık gelen parametre değerini seçtiğinde hangi tahmin ediciyi kullanmış olur?', 'Maksimum sonsal (MAP) tahmin edicisi', ['En küçük mutlak sapma tahmin edicisi', 'Yansız örneklem varyansı tahmin edicisi', 'Momentler yöntemi kuantil tahmin edicisi'], 'Sonsal yoğunluğu P(θ|V) maksimize eden tepe noktası (mod), Maksimum A Posteriori (MAP) tahmini olarak adlandırılır.'),
  ('Bir kargo merkezine gelen paketlerin %50\'si kara yoluyla, %30\'u hava yoluyla, %20\'si deniz yoluyla taşınmaktadır. Paketlerin ıslanma olasılığı kara yolunda %2, hava yolunda %1, deniz yolunda %8\'dir. Teslimatta ıslak olduğu görülen bir paketin deniz yoluyla gelmiş olma olasılığı kaçtır?', '16/29', ['8/19', '10/29', '16/35'], 'Pay = 0,20 × 0,08 = 0,016. Payda = 0,50×0,02 + 0,30×0,01 + 0,20×0,08 = 0,010 + 0,003 + 0,016 = 0,029. Oran = 16/29 bulunur.'),
  ('P(A | B) ile P(B | A) koşullu olasılıklarının birbirine tam olarak eşit çıkabilmesi (sıfırdan farklı olaylar için) hangi koşulun sağlanmasına bağlıdır?', 'A ve B olaylarının başlangıçtaki koşulsuz olasılıklarının P(A) = P(B) eşitliğini sağlaması', ['A ve B olaylarının birleşim kümesinin örnek uzayın tamamını kaplaması', 'A olayının B olayının alt kümesi olarak tanımlanmış olması', 'A ve B olaylarının ayrık (kesişimlerinin boş küme) olması'], 'Bayes bağıntısından P(A|B) = P(B|A) × P(A)/P(B) yazılır; kesişim sıfırdan farklıyken iki koşullu olasılığın eşitliği P(A) = P(B) gerektirir.'),
  ('Bir kalp cerrahı nadir bir ameliyat tekniğinin başarı oranını tahmin ederken, kendi hastanesindeki 4 vakanın yanı sıra literatürdeki geçmiş 200 vakanın sonuçlarını önsel dağılım olarak modele dahil ediyor. Çok küçük örneklemlerde bilgilendirici önsel kullanmanın en önemli istatistiksel katkısı nedir?', 'Küçük örneklemin rastgele dalgalanmalarını dizginleyerek tahmin varyansını düşürmesi', ['Gözlemlenen 4 vakanın verisini denklemden tamamen silerek yalnız geçmiş veriyi bırakması', 'Örneklem büyüklüğünü yapay olarak sonsuza çıkarıp standart hatayı tam sıfırlaması', 'Yanlış kurulmuş bir olabilirlik modelini her koşulda yansız hale getirmesi'], 'Az verinin olduğu durumlarda geçmiş bilgiye dayalı bilgilendirici önsel (düzenlileştirme gibi) aşırı uç tahminleri önler ve kararlılığı artırır.'),
  ('Bir akvaryumda mavi ve sarı balıklar bulunmaktadır; başlangıçta akvaryumun \'çoğunlukla mavi (%80 mavi)\' veya \'çoğunlukla sarı (%80 sarı)\' olma önsel olasılıkları eşittir. Kepçeyle yakalanıp geri bırakılan iki bağımsız balık da mavi çıktığında akvaryumun \'çoğunlukla mavi\' olma sonsal olasılığı kaç olur?', '16/17', ['4/5', '8/9', '64/65'], 'İki mavi gelme olabilirliği: Çoğunluk mavi ise 0,80^2 = 0,64; Çoğunluk sarı ise 0,20^2 = 0,04. Eşit önselle: 0,64 / (0,64 + 0,04) = 64/68 = 16/17.'),
  ('Bir siber güvenlik analisti sunucudaki yavaşlamanın donanım arızasından (%70) veya ağ darboğazından (%30) kaynaklandığını düşünüyor. Paket kaybı oranının %5\'i aşması ağ darboğazında %90, donanım arızasında %10 olasılıkla görülüyor. Paket kaybı %8 ölçüldüğüne göre sorunun donanım arızası olma olasılığı kaçtır?', '7/34', ['27/34', '7/10', '3/17'], 'Donanım arızası sonsal olasılığı sorulmuştur: Pay = 0,70 × 0,10 = 0,07. Payda = 0,07 + 0,30 × 0,90 = 0,07 + 0,27 = 0,34. Oran = 7/34\'tür.'),
  ('Bir yazılımcı kodundaki hatanın bellek sızıntısından (%35) veya yarış durumundan (%65) kaynaklandığını düşünüyor. Hatanın yalnızca çok çekirdekli işlemcide ortaya çıkma olasılığı yarış durumunda 0,80, bellek sızıntısında 0,20\'dir. Hata yalnızca çok çekirdekli modda tetiklendiğine göre yarış durumu olma olasılığı kaçtır?', '52/59', ['13/20', '26/33', '45/59'], 'Pay = 0,65 × 0,80 = 0,52. Payda = 0,52 + 0,35 × 0,20 = 0,52 + 0,07 = 0,59. Sonsal olasılık = 52/59 olarak bulunur.'),
  ('Bayesçi hipotez testinde klasik p-değerinden farklı olarak sıfır hipotezinin (H0) gerçekten doğru olma olasılığı doğrudan hesaplanabilir. Bunun için araştırmacının ek olarak neyi tanımlaması zorunludur?', 'H0 ve alternatif hipotez (H1) için önsel olasılıklar ile H1 altındaki parametre dağılımını', ['Yalnızca örneklem aritmetik ortalamasının karekökünü', 'Deneyin tekrarlanacağı gelecekteki toplam laboratuvar sayısını', 'Serbestlik derecesinden bağımsız sabit bir alfa kesim noktasını'], 'P(H0|Veri) değerini hesaplayabilmek için hem hipotezlerin önsel ağırlıklarına hem de alternatif hipotez altındaki marjinal olabilirliğe ihtiyaç vardır.'),
  ('Bir jeolog bulduğu kristalin kuvars olma önsel olasılığını 0,80, topaz olma olasılığını 0,20 olarak değerlendiriyor. Sertlik testinde camı kolayca çizme olasılığı topazda 0,95, kuvarsta 0,85\'tir. Camı çizen bu kristalin topaz olma sonsal olasılığı neden önsel olasılığına (0,20) çok yakın kalmıştır?', 'Her iki mineral de camı yüksek olasılıkla çizdiğinden kanıtın ayırt ediciliği (Bayes çarpanı) 1\'e çok yakındır', ['Önsel olasılık 0,50\'nin altında olduğunda Bayes kuralı olasılığı hiçbir zaman artıramaz', 'Kuvars ve topaz ayrık olaylar olmadığından toplam olasılık paydası birden büyük çıkmıştır', 'Sertlik testi nitel bir gözlem olduğu için nicel olasılık hesabına dahil edilemez'], 'Olabilirlik oranı 0,95 / 0,85 ≈ 1,12 olup 1\'e çok yakındır (sonsal ≈ %21,8); her iki hipotez altında da beklenen bir sonuç güçlü kanıt oluşturmaz.'),
  ('Bir havaalanı bagaj taramasında yolcunun valizinde yasaklı lityum pil bulunma önsel olasılığı 0,01\'dir. Görsel X-ray yazılımı pil varken %90, pil yokken metal eşyalar yüzünden %9 olasılıkla uyarı veriyor. Yazılım uyarı verdiğinde valizde gerçekten yasaklı pil olma olasılığı kesir olarak kaçtır?', '10/109', ['1/10', '9/100', '10/99'], 'Pay = 0,01 × 0,90 = 0,0090. Payda = 0,0090 + 0,99 × 0,09 = 0,0090 + 0,0891 = 0,0981. Oran = 90/981 = 10/109\'dur.'),
  ('Bir kutuda 1\'den 4\'e kadar numaralandırılmış dört zar vardır; k numaralı zarın (k = 1, 2, 3, 4) k yüzü kırmızıya, kalan (6 - k) yüzü beyaza boyanmıştır. Kutudan rastgele bir zar seçilip atıldığında üst yüze kırmızı geldiğine göre, seçilen zarın 4 numaralı zar olma olasılığı kaçtır?', '2/5', ['1/4', '2/3', '3/10'], 'Önseller eşit (1/4). Kırmızı gelme olasılıkları: 1/6, 2/6, 3/6, 4/6. Sonsal P(Zar 4 | Kırmızı) = (4/6) / ((1+2+3+4)/6) = 4/10 = 2/5\'tir.'),
  ('Bir antika saatçiye gelen mekanik saatlerin durma nedeni %50 olasılıkla zemberek kırılması, %30 olasılıkla kirlenme, %20 olasılıkla balans mili eğrilmesidir. Saati sallayınca birkaç saniye çalışıp durma belirtisi zemberek kırılmasında %0, kirlenmede %40, balans eğrilmesinde %60 görülür. Sallanınca kısa süre çalışan bu saatin arızasının kirlenme olma olasılığı kaçtır?', '0,50', ['0,40', '0,60', '0,30'], 'Zemberek kırılmasında olabilirlik 0 olduğundan elenir! Pay = 0,30 × 0,40 = 0,12. Payda = 0 + 0,12 + 0,20 × 0,60 = 0,24. Oran = 0,12 / 0,24 = 0,50\'dir.'),
  ('Bir satranç kulübündeki üyelerin %20\'si usta, %50\'si orta düzey, %30\'u başlangıç düzeyindedir. Hızlı bir açılış tuzağını fark edip savuşturma olasılığı ustalarda %95, orta düzeyde %60, başlangıç düzeyinde %10\'dur. Tuzağı başarıyla savuşturan rastgele bir üyenin orta düzey gruptan olma olasılığı kaçtır?', '15/26', ['19/52', '3/5', '12/25'], 'Pay = 0,50 × 0,60 = 0,30. Payda = 0,20×0,95 + 0,30 + 0,30×0,10 = 0,19 + 0,30 + 0,03 = 0,52. Oran = 0,30 / 0,52 = 30/52 = 15/26.'),
  ('Bir dil sınavına giren adayların %30\'u yoğun hazırlık kursuna katılmış, %70\'i bireysel çalışmıştır. Kursa katılanların %80\'i, bireysel çalışanların %40\'ı sınavdan A düzeyi almıştır. Sınavdan A alamayan bir adayın hazırlık kursuna katılmış olma olasılığı kaçtır?', '1/8', ['3/16', '1/6', '3/14'], 'A alamama: Kurslu = 0,20; Bireysel = 0,60. Pay = 0,30 × 0,20 = 0,06. Payda = 0,06 + 0,70 × 0,60 = 0,06 + 0,42 = 0,48. Oran = 6/48 = 1/8\'dir.'),
  ('Bir araba kiralama şirketinin filosundaki araçların %45\'i benzinli, %35\'i dizel, %20\'si elektrikli modeldir. Kış sabahı ilk çalıştırmada sorun çıkarma olasılığı benzinlide %2, dizelde %6, elektriklide %1\'dir. Sabah çalıştırılamayan bir aracın dizel olma olasılığı kaçtır?', '21/32', ['9/32', '7/12', '15/28'], 'Pay = 0,35 × 0,06 = 0,021. Payda = 0,45×0,02 + 0,021 + 0,20×0,01 = 0,009 + 0,021 + 0,002 = 0,032. Oran = 21/32 bulunur.'),
  ('Bir maden suyunun doğal kaynağından lityum minerali çıkma önsel olasılığı 0,12\'dir. Hızlı şerit testinin lityum varken renk değiştirme olasılığı 0,75, lityum yokken başka iyonlarla renk değiştirme olasılığı 0,05\'tir. Şerit renk değiştirdiğinde kaynakta lityum bulunma olasılığı hangi kesirdir?', '45/67', ['9/16', '36/55', '15/29'], 'Pay = 0,12 × 0,75 = 0,090. Payda = 0,090 + 0,88 × 0,05 = 0,090 + 0,044 = 0,134. Oran = 90/134 = 45/67 bulunur.'),
  ('Aynı tanı kiti hiç değiştirilmeden önce hastalık sıklığının (prevalansın) %1 olduğu genel nüfusta, ardından hastalık sıklığının %30 olduğu yüksek riskli bir klinikte kullanılıyor. Bu geçişte testin karakteristikleri nasıl değişir?', 'Duyarlılık ve özgüllük sabit kalırken pozitif öngörü değeri (PPV) belirgin biçimde yükselir', ['Pozitif ve negatif öngörü değerleri sabit kalırken testin duyarlılığı otuz katına çıkar', 'Özgüllük oranı düşerken yanlış negatiflik olasılığı sıfıra doğru hızla geriler', 'Hem duyarlılık hem de negatif öngörü değeri aynı oranda artış gösterir'], 'Duyarlılık ve özgüllük testin biyolojik/teknik iç özelliğidir; prevalans yükseldiğinde PPV artar, NPV ise bir miktar azalır.'),
  ('Kan şekeri ölçümüne dayalı bir diyabet taramasında \'pozitif\' sayılma eşik değeri (cut-off) 126 mg/dL\'den 105 mg/dL\'ye çekilirse testin performansında hangi ödünleşim yaşanır?', 'Duyarlılık artarken özgüllük azalır ve yanlış pozitif sayısı yükselir', ['Hem duyarlılık hem de özgüllük aynı anda yükselerek hatalar sıfırlanır', 'Duyarlılık azalırken özgüllük artar ve yanlış negatif vakalar çoğalır', 'Yanlış pozitif oranı düşerken pozitif öngörü değeri kesin olarak artar'], 'Eşik düşürüldüğünde daha çok kişi pozitif sınıflanır; böylece gerçek hastalar kaçmaz (duyarlılık artar) ama sağlamlar da pozitif çıkar (özgüllük düşer).'),
  ('Kanıta dayalı tıpta kullanılan \'SnNOut\' (yüksek duyarlılıklı testte negatif sonuç hastalığı dışlar) kuralının matematiksel gerekçesi nedir?', 'Duyarlılık %100\'e çok yakın olduğunda yanlış negatiflerin neredeyse sıfırlanması ve negatif sonucun sağlamlığı güçlü biçimde kanıtlaması', ['Duyarlılığı yüksek testlerin sağlıklı bireylerde her zaman pozitif sonuç üreterek taramayı hızlandırması', 'Negatif çıkan her sonucun hastalık prevalansını toplumda otomatik olarak iki katına çıkarması', 'Yüksek duyarlılıklı testlerde özgüllüğün her zaman sıfıra eşit olmak zorunda kalması'], 'Duyarlılık → 1 iken P(- | Hasta) → 0 olur; hasta birinin negatif çıkması neredeyse imkânsız olduğundan negatif sonuç hastalığı güvenle dışlar (rule out).'),
  ('Klinik tanıda \'SpPIn\' kısaltmasıyla bilinen ilkeye göre bir hastalığın varlığını kesinleştirmek (rule in) için hangi özelliğe sahip testin pozitif çıkması en güçlü kanıtı sunar?', 'Özgüllüğü (spesifisitesi) %100\'e çok yakın olan bir doğrulama testinin', ['Yanlış pozitiflik oranı %40 civarında seyreden ucuz bir tarama testinin', 'Duyarlılığı yüksek fakat özgüllüğü %20 olan geniş kapsamlı anketin', 'Negatif olabilirlik oranı 1 değerine eşit olan nötr biyobelirtecin'], 'Özgüllük çok yüksekse sağlam birinin pozitif çıkması (yanlış pozitif) çok nadirdir; dolayısıyla pozitif sonuç hastalığı güçlü biçimde doğrular.'),
  ('Bir tanı testinin pozitif olabilirlik oranı (LR+) aşağıdaki formüllerden hangisiyle hesaplanır?', 'Duyarlılık / (1 - Özgüllük)', ['Özgüllük / (1 - Duyarlılık)', '(1 - Duyarlılık) / Özgüllük', 'Duyarlılık × Özgüllük'], 'LR+ = P(+ | Hasta) / P(+ | Sağlam) olduğundan payda doğru pozitif oranı (duyarlılık), paydada ise yanlış pozitif oranı (1 - özgüllük) yer alır.'),
  ('Negatif olabilirlik oranı (LR-) klinik açıdan iyi bir dışlama testi için hangi sayısal değere olabildiğince yakın olmalıdır?', '0 değerine yakın', ['1 değerine tam eşit', '10 veya daha büyük pozitif tam sayılara', 'Prevalansın karesinin tersine'], 'LR- = (1 - Duyarlılık) / Özgüllük oranıdır; bu değer 0\'a ne kadar yakınsa negatif sonuç hastalık bahis oranını o kadar keskin düşürür.'),
  ('Duyarlılığı %91 ve özgüllüğü %90 olan bir hızlı antijen testinin negatif olabilirlik oranı (LR-) ondalık olarak kaçtır?', '0,10', ['0,09', '1,01', '0,19'], 'LR- = (1 - Duyarlılık) / Özgüllük = (1 - 0,91) / 0,90 = 0,09 / 0,90 = 0,10 bulunur.'),
  ('İkinci Dünya Savaşı yıllarında radar operatörlerinin ekrandaki parazit ile düşman uçağını ayırt etme başarısını ölçmek için geliştirilen ROC (Alıcı İşletim Karakteristiği) eğrisinde yatay (X) ve dikey (Y) eksenlerde sırasıyla hangi büyüklükler yer alır?', 'Yatay eksende (1 - Özgüllük), dikey eksende Duyarlılık', ['Yatay eksende Prevalans, dikey eksende Pozitif Öngörü Değeri', 'Yatay eksende Duyarlılık, dikey eksende Negatif Öngörü Değeri', 'Yatay eksende Örneklem Hacmi, dikey eksende Standart Sapma'], 'ROC eğrisi tüm olası eşik değerleri boyunca X ekseninde yanlış pozitif oranına (1 - özgüllük) karşılık Y ekseninde doğru pozitif oranını (duyarlılık) çizer.'),
  ('Bir biyobelirteç için üç aday kesim noktası denenmiştir: K1 noktasında (duyarlılık 0,92; özgüllük 0,65), K2 noktasında (duyarlılık 0,84; özgüllük 0,81), K3 noktasında (duyarlılık 0,70; özgüllük 0,91). Youden indeksini en büyükleyen kesim noktası ve J değeri hangisidir?', 'K2 noktası ve J = 0,65', ['K1 noktası ve J = 0,57', 'K3 noktası ve J = 0,61', 'K2 noktası ve J = 0,825'], 'J(K1) = 0,92+0,65-1 = 0,57; J(K2) = 0,84+0,81-1 = 0,65; J(K3) = 0,70+0,91-1 = 0,61. En yüksek değer 0,65 ile K2 noktasındadır.'),
  ('Yenidoğan topuk kanı taramasında fenilketonüri gibi erken diyetle önlenebilir ancak atlanırsa kalıcı zekâ geriliği yapan metabolik hastalıklarda ilk basamak testinin eşiği nasıl ayarlanmalıdır?', 'Yanlış negatifleri sıfıra yaklaştıracak biçimde yüksek duyarlılığa ayarlanmalı, pozitif çıkanlar kesin testle doğrulanmalıdır', ['Aileleri hiç telaşlandırmamak adına duyarlılık %30\'a çekilip özgüllük %100 yapılmalıdır', 'Yalnızca aile öyküsünde kesin hastalık olan bebeklere uygulanacak dar bir eşik seçilmelidir', 'Pozitif ve negatif olabilirlik oranları birbirine eşitlenecek şekilde rastgele kesim noktası alınmalıdır'], 'Toplum taramalarında tedavi edilebilir ağır hastalıklarda hiçbir hasta bebek kaçırılmamalıdır; yüksek duyarlılık + ikinci basamak doğrulama altın kuraldır.'),
  ('Bir kalite kontrol kamerası banttan geçen 1000 cam şişeden çatlak olan 80 şişenin 72\'sini ayırmış, sağlam olan 920 şişenin ise 28\'ini hatalı biçimde çatlak sanarak ayırmıştır. Kameranın ayırmayıp sağlam diye paketlemeye gönderdiği şişeler için Negatif Öngörü Değeri (NPV) kesir olarak kaçtır?', '223/225', ['23/25', '9/10', '178/185'], 'Sağlam geçen doğru negatifler TN = 920 - 28 = 892; kaçırılan çatlaklar FN = 80 - 72 = 8. Toplam negatif = 892 + 8 = 900. NPV = 892 / 900 = 223/225\'tir.'),
  ('Makine öğrenmesi ve bilgi erişiminde \'Kesinlik\' (Precision) ve \'Duyarlılık/Geri Çağırma\' (Recall) olarak adlandırılan iki metrik, tıp istatistiğindeki hangi kavram çiftine bire bir karşılık gelir?', 'Precision = Pozitif Öngörü Değeri (PPV), Recall = Duyarlılık (Sensitivite)', ['Precision = Özgüllük (Spesifisite), Recall = Negatif Öngörü Değeri (NPV)', 'Precision = Prevalans, Recall = Pozitif Olabilirlik Oranı (LR+)', 'Precision = Doğruluk (Accuracy), Recall = Yanlış Pozitif Oranı'], 'Precision = TP/(TP+FP) yani PPV\'dir; Recall ise TP/(TP+FN) yani tıptaki duyarlılık (sensitivity) metriğinin bire bir aynısıdır.'),
  ('Dengesiz veri kümelerinde (örneğin %99 sağlam, %1 hasta içeren bir taramada) \'Genel Doğruluk\' (Accuracy = (TP+TN)/Toplam) ölçütü neden yanıltıcı bir başarı göstergesidir?', 'Herkese gözü kapalı \'sağlam\' diyen sıfır duyarlılıklı işlevsiz bir model bile %99 doğruluk skoru alabileceği için', ['Genel doğruluk formülü yalnızca hasta sayısının sağlam sayısından fazla olduğu durumlarda tanımlı olduğu için', 'Doğru negatiflerin sayısı arttıkça genel doğruluk oranı matematiksel olarak sıfıra yaklaştığı için', 'Genel doğruluk metriği yanlış pozitif hatalarını on kat ağırlıklandırarak cezalandırdığı için'], 'Nadir olaylarda çoğunluk sınıfını ezbere tahmin etmek çok yüksek Accuracy verir; bu doğruluk paradoksu yüzünden PPV, duyarlılık veya F1 skoru izlenmelidir.'),
  ('Bir kredi kartı sahtekârlık (fraud) algılama modelinin Precision (PPV) değeri 0,60 ve Recall (Duyarlılık) değeri 0,40 olarak ölçülmüştür. Bu modelin F1 skoru kaçtır?', '0,48', ['0,50', '0,49', '0,24'], 'F1 = 2 × (0,60 × 0,40) / (0,60 + 0,40) = 0,48 / 1,00 = 0,48 bulunur (aritmetik ortalama olan 0,50\'den küçüktür).'),
  ('Koşullu bağımsız çalışan iki tarama testinden T1\'in duyarlılığı 0,80, T2\'nin duyarlılığı 0,90\'dır. Hastaya iki test paralel uygulanıp \'en az biri pozitifse pozitif\' (VEYA kuralı) kararı verilirse bileşik duyarlılık kaç olur?', '0,98', ['0,72', '0,85', '0,95'], 'Hasta birinin her iki testten de yanlış negatif alma olasılığı (1 - 0,80)×(1 - 0,90) = 0,20×0,10 = 0,02\'dir. En az birinin yakalama olasılığı 1 - 0,02 = 0,98\'dir.'),
  ('ROC grafiğinde (1, 1) sağ üst köşe noktası tanı testinin hangi uç eşik ayarında ortaya çıkar?', 'İncelenen tüm bireylere istisnasız \'pozitif\' sonucunun verildiği en gevşek eşikte', ['İncelenen tüm bireylere istisnasız \'negatif\' sonucunun verildiği en katı eşikte', 'Hasta ve sağlıklı bireylerin kusursuz biçimde ayrıştırıldığı orta eşikte', 'Prevalansın sıfıra eşit olduğu hastalıksız kontrol grubunda'], 'Herkes pozitif ilan edildiğinde hastaların %100\'ü yakalanır (Duyarlılık=1) ama sağlamların da %100\'ü yanlış pozitif alır (1-Özgüllük=1), yani (1,1) noktası oluşur.'),
  ('Biyometrik parmak izi kilidi olan yüksek güvenlikli bir banka kasasında \'Yanlış Kabul Oranı\' (FAR - yetkisiz kişiyi içeri alma) ile \'Yanlış Reddetme Oranı\' (FRR - yetkili müdürü kapıda bırakma) arasındaki ilişki nasıldır?', 'Eşleşme eşiği yükseltildikçe FAR düşer ancak yetkili kişinin reddedilme oranı (FRR) artar', ['Eşleşme eşiği yükseltildikçe hem FAR hem de FRR aynı anda sıfıra iner', 'Eşleşme eşiği düşürüldükçe yetkisiz kişilerin kasayı açma olasılığı (FAR) azalır', 'FAR ve FRR değerlerinin toplamı her zaman 1,00 sayısına eşit olmak zorundadır'], 'Biyometride FAR yanlış pozitife, FRR yanlış negatife karşılık gelir; kasa güvenliği için eşik sıkılaştırılınca FAR sıfıra yaklaşırken FRR yükselir.'),
  ('Bir hastalığın toplumda görülme sıklığı (prevalansı) azaldıkça, aynı tanı testinin Negatif Öngörü Değeri (NPV) nasıl etkilenir?', 'NPV yükselerek %100\'e daha çok yaklaşır', ['NPV hızla düşerek %0\'a doğru geriler', 'Prevalanstan tamamen bağımsız olduğu için sabit kalır', 'Önce yarıya düşer, ardından testin özgüllüğüne eşitlenir'], 'Hastalık çok nadirse başvuran kişi zaten büyük olasılıkla sağlamdır; üstüne negatif test sonucu geldiğinde sağlam olma olasılığı (NPV) %100\'e çok yaklaşır.'),
  ('Bir su arıtma tesisinde arsenik kirliliğini ölçen sensörün duyarlılığı %96, özgüllüğü %92\'dir. Suda arsenik kirliliği bulunma önsel bahis oranı 1:12 ise, sensör alarm verdiğinde suda gerçekten arsenik bulunma sonsal bahis oranı kaç olur?', '1:1', ['2:1', '1:2', '3:4'], 'Sensörün pozitif olabilirlik oranı LR+ = 0,96 / (1 - 0,92) = 0,96 / 0,08 = 12\'dir. Sonsal bahis = Önsel bahis × LR+ = (1/12) × 12 = 1:1 olur!'),
  ('Bir endüstriyel röntgen cihazı uçak türbin kanatlarındaki mikro çatlakları taramaktadır. Gerçek çatlaklı kanatların %95\'ini yakalayan cihazın pozitif olabilirlik oranı (LR+) 19 olarak raporlanmıştır. Buna göre cihazın özgüllüğü yüzde kaçtır?', '%95', ['%90', '%98', '%81'], 'LR+ = Duyarlılık / (1 - Özgüllük) => 19 = 0,95 / (1 - Özgüllük) => 1 - Özgüllük = 0,95 / 19 = 0,05 => Özgüllük = 0,95 (%95) bulunur.'),
  ('Bir tanı testinin Negatif Olabilirlik Oranı (LR-) 0,20 ve özgüllüğü %75 olarak biliniyor. Bu testin duyarlılığı yüzde kaçtır?', '%85', ['%80', '%90', '%75'], 'LR- = (1 - Duyarlılık) / Özgüllük => 0,20 = (1 - Duyarlılık) / 0,75 => 1 - Duyarlılık = 0,15 => Duyarlılık = 0,85 (%85) olarak hesaplanır.'),
  ('Aynı hasta grubuna uygulanan X ve Y testlerinin ROC eğrileri çizildiğinde X testinin eğrisi tüm yatay eksen boyunca Y testinin eğrisinin tamamen üzerinde yer almaktadır. Bu grafikten çıkarılabilecek kesin sonuç nedir?', 'Seçilecek her yanlış pozitif oranında X testi Y testinden daha yüksek duyarlılık sunar ve AUC(X) > AUC(Y) olur', ['Y testinin özgüllüğü her kesim noktasında X testinin özgüllüğünden daha yüksektir', 'X testi yalnızca hastalık prevalansı %80\'i aştığında Y testinden üstün çalışır', 'Y testinin negatif öngörü değeri tüm klinik senaryolarda X testinden büyüktür'], 'Bir ROC eğrisi diğerini stokastik olarak tamamen domine ediyorsa (hiç kesişmeden üstteyse), her özgüllük düzeyinde daha yüksek duyarlılık sağlar.'),
  ('Bir tarama programında sağlıklı 1000 kişiye uygulanan test 940 negatif ve 60 pozitif sonuç vermiştir. Hasta kimsenin bulunmadığı bu kontrol grubundan testin hangi karakteristiği doğrudan elde edilir?', 'Özgüllüğü (%94)', ['Duyarlılığı (%94)', 'Pozitif öngörü değeri (%6)', 'Pozitif olabilirlik oranı (15,6)'], 'Grupta yalnızca sağlıklı bireyler bulunduğundan TN / (TN + FP) = 940 / 1000 = %94 doğrudan testin özgüllüğünü verir; hasta olmadığı için duyarlılık ve PPV hesaplanamaz.'),
  ('Bir sualtı boru hattı ultrasonik robotu kaynak dikişlerindeki korozyonu aramaktadır. Korozyonlu dikişlerin %90\'ında alarm veren robot, sağlam dikişlerin %5\'inde yanlış alarm üretiyor. İncelenen hattaki dikişlerin %20\'sinde korozyon varsa robotun alarm vermediği bir dikişin gerçekten sağlam olma olasılığı (NPV) kaçtır?', '38/39', ['19/20', '9/10', '36/37'], 'Alarm vermeme: Sağlam ve negatif = 0,80 × 0,95 = 0,76; Korozyonlu ve negatif = 0,20 × 0,10 = 0,02. NPV = 0,76 / (0,76 + 0,02) = 76/78 = 38/39.'),
  ('Sinyal algılama kuramında aynı d\' ayırt etme gücüne sahip iki radyologdan birinin mamografide şüpheli leke gördüğünde çok sık \'tümör var\' demesi, diğerinin ise yalnızca çok emin olduğunda \'tümör var\' demesi neyin farklı olmasından kaynaklanır?', 'Karar ölçütü / yanıt yanlılığı (response criterion β) eşiğinin farklı konumlandırılmasından', ['Göz retinasındaki optik çözünürlüğün ikinci radyologda sıfır olmasından', 'Hasta grubundaki gerçek tümör prevalansının radyologdan radyoloğa değişmesinden', 'ROC eğrisinin şans köşegeninin altına simetrik olarak katlanmasından'], 'İki uzman aynı ROC eğrisi (aynı d\') üzerinde çalışmakta fakat biri sol alt (tutucu eşik), diğeri sağ üst (gevşek eşik) noktayı seçmektedir.'),
  ('Bir gıda denetim kiti sütteki antibiyotik kalıntısını %95 duyarlılık ve %90 özgüllükle saptamaktadır. Bölgedeki süt tankerlerinin %10\'unda antibiyotik kalıntısı bulunduğu bilindiğine göre, rastgele seçilen bir tankerden alınan numunenin bu kitten \'pozitif\' sonuç alma toplam olasılığı yüzde kaçtır?', '%18,5', ['%10,0', '%9,5', '%19,5'], 'Toplam pozitif çıkma olasılığı P(+) = P(Kalıntılı)×Duyarlılık + P(Temiz)×(1-Özgüllük) = 0,10×0,95 + 0,90×0,10 = 0,095 + 0,090 = 0,185 (%18,5).'),
  ('Bir hastalığın tanı testinde Pozitif Öngörü Değeri (PPV) ile Negatif Öngörü Değerinin (NPV) toplamı hakkında aşağıdakilerden hangisi genel olarak doğrudur?', 'Farklı koşullu paydalara sahip olduklarından toplamları 1\'e eşit olmak zorunda değildir; iyi bir testte toplamları 1\'den oldukça büyüktür', ['Tümleyen iki olay oldukları için her prevalans değerinde toplamları tam 1,00 sayısına eşittir', 'Toplamları her zaman testin duyarlılığı ile özgüllüğünün çarpımına eşittir', 'Toplamları hiçbir zaman 0,50 değerini aşamaz'], 'PPV = P(H|+), NPV = P(H\'|-); koşullandıkları olaylar (+ ve -) farklı olduğu için toplamları 1 değildir (örneğin %90 PPV ve %98 NPV için toplam 1,88 olur).'),
  ('Bir klinikte kullanılan hızlı streptokok boğaz testinin özgüllüğü %98, duyarlılığı %70\'tir. Boğaz ağrısıyla gelen bir çocukta test sonucu POZİTİF çıktığında ve başka bir çocukta NEGATİF çıktığında hekim sonuçlara nasıl yaklaşmalıdır?', 'Pozitif sonuç yüksek özgüllük (SpPIn) sayesinde tanıyı güçlü biçimde doğrularken, negatif sonuç düşük duyarlılık yüzünden hastalığı tek başına dışlamaya yetmez', ['Negatif sonuç hastalığı %100 kesinlikle dışlarken, pozitif sonuç tamamen anlamsız kabul edilip yok sayılmalıdır', 'Duyarlılık %70 olduğu için pozitif çıkan hastaların %30\'u kesinlikle sağlıklıdır', 'Özgüllük %98 olduğu için negatif çıkan hastaların yalnızca %2\'sinde bakteri bulunabilir'], 'Gerçek boğaz kültürü kılavuzlarında da aynen böyledir: Hızlı antijen testi pozitifse tedavi başlanır (%98 özgüllük), negatifse %30 kaçırma payı yüzünden boğaz kültürüyle doğrulanır!'),
  ('Pulmoner emboli (akciğer pıhtısı) şüphesinde acil serviste bakılan D-dimer kan testinin duyarlılığı %97 civarındayken özgüllüğü %45 gibi düşüktür. Bu testin acil tıptaki temel kullanım amacı nedir?', 'Düşük-orta riskli hastada sonuç negatif çıkarsa emboliyi güvenle dışlayıp (SnNOut) gereksiz tomografi çekimini önlemek', ['Sonuç pozitif çıktığı anda başka hiçbir görüntüleme yapmadan doğrudan pıhtı eritici ağır ilaç başlamak', 'Yalnızca sağlıklı bireylerde tarama yaparak toplumun pıhtılaşma prevalansını sıfırlamak', 'Özgüllüğü yüksek olduğu için yanlış pozitif alarmları tamamen ortadan kaldırmak'], 'D-dimer klasik bir SnNOut testidir: Ameliyat, enfeksiyon, gebelik gibi pek çok durumda yükseldiğinden özgüllüğü düşüktür; ancak negatif çıkması pıhtıyı güçlü biçimde dışlar.'),
  ('İki sınıflı bir tanı probleminde Prevalans = p, Duyarlılık = Se ve Özgüllük = Sp ile gösterildiğinde, Pozitif Öngörü Değerinin (PPV) Bayes teoremiyle tam açık yazılışı aşağıdakilerden hangisidir?', '(p × Se) / [p × Se + (1 - p) × (1 - Sp)]', ['(p × Sp) / [p × Sp + (1 - p) × (1 - Se)]', '[(1 - p) × Sp] / [(1 - p) × Sp + p × (1 - Se)]', '(p × Se) / [p × Se + (1 - p) × Sp]'], 'Pay gerçek pozitiflerin toplamdaki payı p×Se, payda ise gerçek pozitifler p×Se ile yanlış pozitiflerin (1-p)×(1-Sp) toplamıdır.'),
  ('Prevalansın p, duyarlılığın Se ve özgüllüğün Sp olduğu bir taramada Negatif Öngörü Değerinin (NPV) tam cebirsel ifadesi hangisidir?', '[(1 - p) × Sp] / [(1 - p) × Sp + p × (1 - Se)]', ['(p × Se) / [p × Se + (1 - p) × (1 - Sp)]', '[(1 - p) × (1 - Sp)] / [(1 - p) × (1 - Sp) + p × Se]', '(p × Sp) / [p × Sp + (1 - p) × Se]'], 'NPV = P(Sağlam | -) olduğundan pay doğru negatifler (1-p)×Sp, payda ise doğru negatifler ile yanlış negatiflerin p×(1-Se) toplamıdır.'),
  ('Bir tanı testinde Yanlış Negatif Oranı %0 (yani Duyarlılık = %100) ve Özgüllük > 0 ise, Negatif Öngörü Değeri (NPV) hastalık prevalansı (%100 hariç) ne olursa olsun kaç çıkar?', 'Tam %100', ['Özgüllük yüzdesine eşit', '1 - Prevalans değerine eşit', '%50 ile özgüllük arasında değişken'], 'Duyarlılık %100 ise FN = 0 olur; hasta hiç kimse negatif çıkamayacağı için negatif sonuç alan herkes istisnasız sağlamdır (NPV = TN / (TN + 0) = 1).'),
  ('Bir doğrulama testinin Özgüllüğü tam %100 (yani Yanlış Pozitif Oranı = %0) ve Duyarlılığı > 0 ise, hastalık prevalansı sıfırdan büyük olduğu sürece Pozitif Öngörü Değeri (PPV) kaç olur?', 'Tam %100', ['Duyarlılık yüzdesine eşit', 'Prevalans ile duyarlılığın çarpımına eşit', '%95 güven düzeyine eşit'], 'Özgüllük %100 olduğunda sağlam hiçbir birey pozitif çıkamaz (FP = 0); dolayısıyla pozitif sonuç alan herkes kesinlikle hastadır (PPV = TP / (TP + 0) = 1).'),
  ('Bir fabrikada üretilen lityum bataryaların şişme riskini ölçen akustik testte yanlış negatifin maliyeti 5000 TL (geri çağırma/yangın), yanlış pozitifin maliyeti ise 50 TL (sağlam bataryayı hurdaya ayırma) olarak hesaplanmıştır. Rasyonel bir mühendis ROC eğrisi üzerinde kesim noktasını nereye yerleştirmelidir?', 'Duyarlılığın çok yüksek olduğu, bir miktar yanlış pozitife katlanılan sağ üst bölgeye yakın bir eşiğe', ['Özgüllüğün %99,9 olduğu ancak duyarlılığın %30\'a düştüğü sol alt köşedeki katı eşiğe', 'Maliyetlerden bağımsız olarak her zaman duyarlılık ve özgüllüğün eşitlendiği simetrik noktaya', 'Tüm bataryaları koşulsuz sağlam kabul eden (0, 0) başlangıç noktasına'], 'C_FN / C_FP = 5000 / 50 = 100 kat asimetri vardır; bir kusurlu bataryayı kaçırmamak için sağlam birkaç bataryanın elenmesine razı olan yüksek duyarlılıklı eşik optimaldir.'),
  ('Bir göz kliniğinde glokom (göz tansiyonu) taraması için göz içi basıncı sınırı 21 mmHg olarak kullanılıyor. Ancak gerçek glokom hastalarının yaklaşık üçte birinde göz içi basıncı 21 mmHg\'nin altında (\'normal basınçlı glokom\') seyrediyor. Bu durum tek başına basınç ölçümünün hangi kısıtını ortaya koyar?', '21 mmHg eşiğinde duyarlılığın en fazla %67 civarında kalacağını ve hastaların üçte birine yanlış negatif vereceğini', ['Özgüllüğün sıfıra düştüğünü ve sağlıklı herkesin glokom hastası ilan edileceğini', 'Pozitif öngörü değerinin her yaş grubunda kesin olarak %100 çıkacağını', 'Göz içi basıncı ile glokom arasında ters yönlü kusursuz bir korelasyon bulunduğunu'], 'Hastaların 1/3\'ü eşiğin altında kalıyorsa yanlış negatif oranı ~%33\'tür; bu nedenle glokom tanısında tek başına basınç yetmez, görme alanı ve optik sinir muayenesi eklenir.'),
  ('Bir işitme taraması cihazı iç kulak kaybı olan çocukların %92\'sini saptarken, dış kulak yolunda geçici kulak kiri bulunan normal işitmeli çocukların bir kısmında da uyarı vererek özgüllüğü %85\'e düşürüyor. Taramadan önce kulak kirinin temizlenmesi cihazın hangi metriğini doğrudan iyileştirir?', 'Sağlıklı çocuklardaki yanlış pozitifleri azaltarak özgüllüğü ve pozitif öngörü değerini yükseltir', ['Cihazın iç kulak hasarını yakalama duyarlılığını %92\'den %100\'e çıkarır', 'Toplumda doğuştan iç kulak kaybı görülme prevalansını yarıya indirir', 'Yanlış negatif sayısını artırarak negatif öngörü değerini düşürür'], 'Sağlıklı çocuklarda hatalı uyarıya yol açan dış etken (kulak kiri) giderildiğinde FP düşer; dolayısıyla hem özgüllük hem de PPV doğrudan yükselir.'),
  ('Bir tanı testinin duyarlılığı %75, özgüllüğü %85 ve uygulandığı popülasyondaki hastalık prevalansı %20\'dir. Bu popülasyonda testin \'Genel Doğruluk\' (Accuracy - doğru sınıflandırılan tüm bireylerin oranı) yüzdesi kaçtır?', '%83', ['%80', '%77', '%85'], 'Genel doğruluk prevalans ağırlıklı ortalamadır: Accuracy = p×Duyarlılık + (1-p)×Özgüllük = 0,20×0,75 + 0,80×0,85 = 0,15 + 0,68 = 0,83 (%83).'),
  ('Bir klinik çalışmada pozitif olabilirlik oranı LR+ = 10 ve negatif olabilirlik oranı LR- = 0,10 olan bir test kullanılıyor. Test öncesi hastalık olasılığı %50 (bahis oranı 1:1) olan bir hastada test pozitif çıkarsa ve başka bir benzer hastada negatif çıkarsa test sonrası hastalık olasılıkları sırasıyla kaç olur?', 'Pozitif çıkanda 10/11, negatif çıkanda 1/11', ['Pozitif çıkanda 9/10, negatif çıkanda 1/10', 'Pozitif çıkanda 5/6, negatif çıkanda 1/6', 'Pozitif çıkanda 10/10, negatif çıkanda 0/10'], 'Önsel bahis 1:1 iken pozitif sonuçta sonsal bahis 10:1 (olasılık 10/11), negatif sonuçta sonsal bahis 0,1:1 = 1:10 (olasılık 1/11) olur.'),
  ('Daniel Kahneman ve Amos Tversky\'nin ünlü \'Taksi Problemi\'nde şehirdeki taksilerin %85\'i yeşil, %15\'i mavidir. Gece kazaya karışıp kaçan taksiyi gören bir tanık taksinin mavi olduğunu söyler; mahkeme testlerinde tanığın karanlıkta renkleri %80 doğrulukla ayırt edebildiği (%20 yanıldığı) saptanır. Kazayı yapan taksinin gerçekten mavi olma olasılığı kaçtır?', '12/29 (yaklaşık %41,4)', ['4/5 (tam %80,0)', '15/32 (yaklaşık %46,9)', '3/4 (tam %75,0)'], 'Gerçek mavi ve mavi deme: 0,15×0,80 = 0,12. Yeşil olup hatalı mavi deme: 0,85×0,20 = 0,17. Sonsal olasılık = 0,12 / (0,12 + 0,17) = 12/29 ≈ %41,4 bulunur.'),
  ('David Eddy\'nin 1982 tarihli klasik tıp eğitimi araştırmasında, belirtisiz bir kadında meme tümörü önsel olasılığı %1, mamografinin duyarlılığı %80 ve yanlış pozitif oranı %10 olarak verildiğinde, ankete katılan hekimlerin büyük çoğunluğu pozitif sonuç sonrası tümör olasılığını %70-%80 civarında tahmin etmiştir. Oysa gerçek olasılık yaklaşık yüzde kaçtır?', '%7,5', ['%44,4', '%18,2', '%25,0'], '1000 kadından 10\'u hasta -> 8 pozitif; 990\'ı sağlam -> 99 yanlış pozitif. Toplam 107 pozitifin 8\'i gerçektir: 8 / 107 ≈ %7,48 (yaklaşık %7,5).'),
  ('On binde bir (1/10.000) görülen çok nadir bir genetik hastalık için geliştirilen testin duyarlılığı %100 ve özgüllüğü %99,9\'dur. Rastgele taranan bir bireyin testi pozitif çıktığında, temel oran yanılgısına düşmeyen bir uzman kişinin hasta olma olasılığını kaç olarak hesaplar?', '1/11 (yaklaşık %9,1)', ['999/1000 (%99,9)', '1/2 (%50,0)', '10/11 (yaklaşık %90,9)'], '10.000 kişide 1 gerçek hasta pozitif çıkar; 9.999 sağlamın binde biri ≈ 10 kişi yanlış pozitif çıkar. Yaklaşık (1) / (1 + 9,999) ≈ 1 / 11 (tam olarak 10/109,99 ≈ %9,09).'),
  ('Kahneman ve Tversky\'nin \'Mühendis mi Avukat mı?\' deneyinde katılımcılara grubun %70\'inin avukat, %30\'unun mühendis olduğu söylenir; ardından bulmaca seven, siyasete ilgisiz bir kişi betimlemesi verilir. Katılımcıların %70-%30 taban oranını tamamen unutarak betimlemeye göre \'kesin mühendistir\' demesi hangi zihinsel kısa yoldan kaynaklanır?', 'Temsililik (prototipe benzerlik) kısa yolu', ['Bulunabilirlik (hatırlama kolaylığı) kısa yolu', 'Batık maliyetten kaçınma eğilimi', 'Statüko koruma ve eylemsizlik yanlılığı'], 'Kişinin kalıp yargıya (prototipe) ne kadar benzediğini olasılıkla eş tutan temsililik sezgisi, grup büyüklüğü (temel oran) bilgisinin ezilmesine neden olur.'),
  ('Bir kentte 1.000.000 yetişkin yaşamaktadır ve kentte yalnızca 100 aranan siber suçlu bulunmaktadır. Kurulan otomatik yüz tanıma kamerası suçluların %99\'unu tanımakta, masum vatandaşların ise yalnızca binde birinde (%0,1) yanlış alarm vermektedir. Kamera sokakta bir kişiye alarm verdiğinde bu kişinin gerçekten aranan suçlu olma olasılığı yaklaşık kaçtır?', 'Yaklaşık %9 (99 / 1099)', ['Yaklaşık %99 (990 / 1000)', 'Yaklaşık %50 (99 / 199)', 'Yaklaşık %90 (900 / 999)'], '100 suçludan 99\'u yakalanır; 999.900 masumun binde biri ≈ 1000 kişide yanlış alarm çalar! Toplam ~1099 alarmın yalnız 99\'u gerçektir (~%9).'),
  ('İlk tarama testi pozitif çıkan bir hastadan yeni örnek almak yerine, aynı kan tüpündeki numuneye bire bir aynı antikor kitini ikinci kez uygulayıp yine pozitif sonuç almak neden yanlış pozitif olasılığını bağımsız iki testteki gibi düşürmez?', 'Numunedeki çapraz tepkime veren madde aynı kaldığı için iki ölçüm koşullu bağımsız değildir', ['Aynı tüpten yapılan ikinci ölçümde hastalık prevalansı kendiliğinden sıfıra düşmektedir', 'Bayes teoremi aynı gün içinde yapılan tekrarlı laboratuvar ölçümlerine uygulanamaz', 'İkinci ölçümün özgüllüğü her zaman birinci ölçümün duyarlılığının tersine eşitlenir'], 'Sağlam bir kişide ilk testi yanıltan antikor veya protein aynı tüpte durduğu sürece aynı kiti tekrarlamak yüksek olasılıkla yine yanlış pozitif verir; farklı mekanizmalı ikinci test gerekir.'),
  ('İkinci Dünya Savaşı\'nda Robert Dorfman\'ın askerlerde frengi taraması için geliştirdiği \'havuzlanmış (grup) test\' yönteminde k kişinin kan örneği tek tüpte karıştırılarak test edilir. Bu yöntemin bireysel taramaya göre test sayısından büyük tasarruf sağlaması hangi koşula bağlıdır?', 'Hastalık prevalansının düşük olması sayesinde birleştirilen tüplerin çoğunun tek testle negatif çıkmasına', ['Hastalık prevalansının %50\'nin üzerinde seyretmesi sayesinde tüm tüplerin pozitif çıkmasına', 'Karıştırılan örnek sayısı arttıkça laboratuvar reaktifinin duyarlılığının sonsuza gitmesine', 'Pozitif çıkan havuzlardaki bireylere ikinci aşamada hiçbir bireysel test yapılmamasına'], 'Prevalans düşük olduğunda k kişilik karışım büyük olasılıkla tamamen temiz çıkar ve tek bir kit ile k kişinin tamamı taranmış olur.'),
  ('Adli bilişimde tek bir şüpheliden alınan DNA\'nın olay yeriyle eşleşmesi durumu ile 500.000 kişilik ulusal DNA veritabanı taranarak bir eşleşme (\'soğuk vaka eşleşmesi\') bulunması durumu Bayesçi açıdan karşılaştırıldığında hangisi doğrudur?', 'Veritabanı taramasında binlerce masum denendiği için rastgele eşleşme bulma olasılığı çok daha yüksektir', ['Veritabanından bulunan eşleşmenin suçluluk sonsal olasılığı her zaman tek şüpheliden daha yüksektir', 'Her iki senaryoda da önsel suçluluk olasılığı tam 0,50 kabul edildiğinden sonuçlar aynıdır', 'Veritabanı büyüdükçe yanlış pozitif eşleşme bulma riski sıfıra doğru yaklaşır'], 'Milyonda bir rastgele eşleşme veren bir profil, 500.000 masumun bulunduğu veritabanında arandığında salt şans eseri bir masumla eşleşme olasılığı çok ciddi biçimde büyür.'),
  ('Bir onkoloji tarama kılavuzu, aynı mamografi cihazını 50-69 yaş grubunda rutin önerirken 25-30 yaş grubundaki belirtisiz sağlıklı kadınlarda rutin tarama olarak önermemektedir. Cihaz aynı olduğu halde genç yaş grubunda önerilmemesinin temel istatistiksel gerekçesi nedir?', '25-30 yaş grubunda hastalık temel oranı çok düşük olduğundan pozitif sonuçların büyük çoğunluğunun yanlış pozitif çıkması', ['Genç yaş grubunda negatif öngörü değerinin sıfıra düşerek tüm sonuçları geçersiz kılması', 'Temel oran düştükçe yanlış negatif oranının matematiksel olarak %100\'e yükselmesi', 'Gençlerde yapılan testlerin olabilirlik oranının her zaman negatif sayı çıkması'], 'Çok düşük prevalanslı yaş grubunda rutin tarama yapıldığında PPV dramatik biçimde düşer; binlerce sağlıklı genç gereksiz biyopsi ve kaygıya maruz kalır.'),
  ('Maliyeti 80 TL olan hızlı tarama testi T1 (duyarlılık %90, özgüllük %80) ile maliyeti 1.000 TL olan doğrulama testi T2 birlikte kullanılacaktır. Prevalansın %10 olduğu bir grupta \'Önce herkese T1 uygula, yalnızca T1 pozitif çıkanlara T2 uygula\' protokolünde kişi başına beklenen toplam test maliyeti kaç TL\'dir?', '350 TL', ['180 TL', '270 TL', '540 TL'], 'Herkese T1 yapılır (80 TL). T1\'in pozitif çıkma olasılığı P(T1+) = 0,10×0,90 + 0,90×0,20 = 0,09 + 0,18 = 0,27\'dir. Kişi başı beklenen maliyet = 80 + 0,27 × 1000 = 350 TL olur.'),
  ('İki aşamalı seri (\'her iki test de pozitifse pozitif\') tanı protokollerinde, koşullu bağımsız iki testten ucuz olanı birinci sıraya, çok pahalı olanı ise ikinci sıraya koymanın temel avantajı nedir?', 'Bileşik duyarlılık ve özgüllüğü değiştirmeden pahalı teste girecek kişi sayısını azaltması', ['Bileşik duyarlılığı her iki testin tekil duyarlılıklarının aritmetik toplamına çıkarması', 'Yanlış negatif vakaların ikinci aşamada kendiliğinden doğru pozitife dönmesini sağlaması', 'Toplumdaki hastalık prevalansını testlerin uygulanma sırasına göre yarı yarıya düşürmesi'], 'Koşullu bağımsızlık altında Se1×Se2 çarpımı sıradan bağımsızdır; ancak ucuz testi öne koymak sağlamların büyük kısmını ucuza eleyerek bütçeyi korur.'),
  ('Beklenen değerin doğrusallık özelliğine göre, iki rastgele değişken X ve Y için E[X + Y] = E[X] + E[Y] eşitliğinin geçerli olması hangi koşulu gerektirir?', 'Beklenen değerlerin sonlu olması dışında bağımsızlık dahil hiçbir ek koşul gerektirmez', ['X ve Y değişkenlerinin istatistiksel olarak birbirinden tamamen bağımsız olmasını', 'X ve Y değişkenlerinin ayrık olaylar olup kesişimlerinin boş küme olmasını', 'Her iki değişkenin de aynı standart sapmaya sahip normal dağılımlı olmasını'], 'Beklenen değerin toplamsallığı (doğrusallığı) X ve Y güçlü biçimde bağımlı olsa bile istisnasız geçerlidir; bağımsızlık E[XY] = E[X]E[Y] çarpımında gerekir.'),
  ('Bir vestiyerdeki görevli elektrik kesilince 8 misafirin paltosunu tamamen rastgele biçimde 8 misafire dağıtmıştır. Kendi paltosunu doğru alan misafir sayısının beklenen değeri kaçtır?', '1', ['0,5', '1,25', '2'], 'Her misafir i için kendi paltosunu alma gösterge değişkeni I_i olsun; E[I_i] = 1/8\'dir. Bağımlı olsalar bile doğrusallıktan toplam beklenen değer 8 × (1/8) = 1 olur!'),
  ('Bir oyuncunun önünde kapalı üç kutudan birinde 600 TL ödül vardır, diğer ikisi boştur. Oyuncu kutu açmak için her denemede 100 TL ödemekte ve ödülü bulduğu anda oyun durmaktadır (bulamazsa sıradaki kapalı kutuyu açmaya devam etmektedir). Oyuncunun bu oyundaki beklenen net kazancı kaç TL\'dir?', '400 TL', ['300 TL', '450 TL', '500 TL'], 'Ödül 3 kutudan birinde eş olasılıkla (1/3) bulunur; 1., 2. veya 3. denemede bulma olasılıkları 1/3, 1/3, 1/3\'tür! Beklenen deneme sayısı = (1+2+3)/3 = 2 (maliyet 200 TL). Net kazanç = 600 - 200 = 400 TL.'),
  ('Bir karnaval oyununda torbadaki 10 toptan 2\'si altın, 8\'i siyahtır. İade edilmeksizin 2 top çeken oyuncu çektiği her altın top başına 30 TL ödül almaktadır. Bu oyunun \'adil oyun\' olması için giriş ücreti kaç TL belirlenmelidir?', '12 TL', ['15 TL', '6 TL', '10 TL'], 'Çekilen 2 toptaki beklenen altın top sayısı doğrusallıktan 2 × (2/10) = 0,4 adettir. Top başına 30 TL verildiğinden beklenen ödül 0,4 × 30 = 12 TL olur.'),
  ('Bir kasko poliçesinde 5.000 TL \'sabit muafiyet\' (deductible) kuralı vardır: Hasar 5.000 TL\'nin altındaysa şirket ödeme yapmaz, üstündeyse hasarın yalnızca 5.000 TL\'yi aşan kısmını öder. Yıl içinde sürücünün %80 olasılıkla hasarsız kalacağı, %15 olasılıkla 4.000 TL (küçük çizik) ve %5 olasılıkla 35.000 TL hasar yaşayacağı biliniyorsa şirketin beklenen tazminat ödemesi kaç TL\'dir?', '1.500 TL', ['2.350 TL', '1.750 TL', '1.850 TL'], '4.000 TL\'lik küçük hasar 5.000 TL muafiyetin altında kaldığından şirket 0 TL öder! 35.000 TL hasarda ise 35.000 - 5.000 = 30.000 TL öder. Beklenen ödeme = 0,05 × 30.000 = 1.500 TL.'),
  ('Bir mesleki sorumluluk sigortasında yıllık hasar %95 olasılıkla 0 TL, %4 olasılıkla 50.000 TL ve %1 olasılıkla 400.000 TL\'dir. Poliçeye \'yıllık azami ödeme üst sınırı (teminat tavanı) 250.000 TL\'dir\' maddesi eklendiğinde şirketin beklenen hasar ödemesi sınırsız poliçeye göre kaç TL azalır?', '1.500 TL azalır', ['4.500 TL azalır', '2.500 TL azalır', '6.000 TL azalır'], 'Sınırsızda %1\'lik büyük hasarda 400.000 TL ödenirken tavanlı poliçede 250.000 TL ödenir; aradaki 150.000 TL fark %1 olasılıkla doğduğundan beklenen ödeme 0,01 × 150.000 = 1.500 TL düşer.'),
  ('Sigorta şirketlerinin poliçelere \'muafiyet\' (ilk kısmın müşteri tarafından ödenmesi) ve \'koasürans\' (hasara yüzdesel ortak olma) maddeleri koymasının temel davranışsal ve aktüeryal amacı aşağıdakilerden hangisidir?', 'Sigortalının özensiz davranma eğilimini (ahlaki tehlikeyi) ve küçük dosya işlem maliyetlerini azaltmak', ['Büyük Ölçekli Doğal Afetlerin gerçekleşme olasılığını istatistiksel olarak sıfıra indirmek', 'Düşük riskli müşterileri sistemden uzaklaştırıp yalnızca yüksek riskli müşterileri toplamak', 'Büyük Sayılar Yasasının sigorta havuzunda çalışmasını tamamen engellemek'], 'Zararın bir bölümüne ortak olan sigortalı aracını/evini daha dikkatli korur (moral hazard azalır); ayrıca çok sık küçük çizik dosyalarının idari masrafı elenir.'),
  ('Bir sigorta şirketi toplumdaki düşük riskli ve yüksek riskli bireyleri ayırt edemeyip herkese ortalama risk üzerinden tek bir prim fiyatı sunduğunda, düşük risklilerin poliçeyi pahalı bulup ayrılması ve havuzda yalnızca yüksek risklilerin kalarak şirketin beklenen hasarını artırması olgusuna ne denir?', 'Ters seçim (adverse selection)', ['Kayıptan kaçınma (loss aversion)', 'Ortalamaya gerileme (regression to mean)', 'Hayatta kalma yanlılığı (survivorship bias)'], 'Bilgi asimetrisi yüzünden yüksek riskli alıcıların sigorta havuzuna orantısız biçimde doluşması ters seçimdir ve beklenen hasarı öngörülen ortalamanın üzerine taşır.'),
  ('Aynı ilçedeki 5.000 konuta deprem sigortası yapan yerel bir şirketin, konut sigortasındaki risk havuzlama avantajını yangın sigortasındaki kadar rahat kullanamamasının temel istatistiksel nedeni nedir?', 'Aynı ilçedeki konutların deprem hasarlarının birbirinden bağımsız olmayıp yüksek pozitif korelasyon göstermesi', ['Deprem hasarlarının beklenen değerinin matematiksel olarak hesaplanamaması', 'Konut sahiplerinin depremi bilerek tetikleyen ahlaki tehlike davranışı sergilemesi', 'Deprem poliçelerinde muafiyet oranının yasal olarak kullanılamaması'], 'Yangınlar çoğunlukla bağımsızken tek bir deprem aynı ilçedeki binlerce evi aynı anda vurur (sistemik/ilişkili risk); bu yüzden şirketler coğrafi çeşitlendirme ve reasürans kullanır.'),
  ('Birim üretim maliyeti 500 TL olan bir mutfak robotu 1.200 TL\'ye satılmaktadır. Üretici \'1 yıl içinde bozulursa tamir etmeden ücretsiz 1 adet yeni ürün gönderme\' (gönderilen ikame ürün ek garanti kapsamı dışında) sözü veriyor. Ürünün 1 yıl içinde bozulma olasılığı %8 ise satılan bir üründen beklenen net kâr kaç TL\'dir?', '660 TL', ['604 TL', '700 TL', '644 TL'], 'İlk ürünün maliyeti 500 TL, satış geliri 1.200 TL\'dir. %8 olasılıkla şirkete 500 TL ek üretim maliyeti doğar (1.200 TL değil, maliyet!). Beklenen kâr = 1200 - 500 - 0,08×500 = 660 TL.'),
  ('Kapasitesi 100 koltuk olan bir bölgesel uçuş için havayolu 101 bilet satmayı değerlendiriyor. Bilet fiyatı iadesiz 2.000 TL\'dir (gelmeyen yolcunun ücreti şirkette kalır). Satılan 101 biletten 101 yolcunun tamamının uçağa gelme olasılığı %25\'tir; bu durumda 1 yolcu uçağa alınamaz ve kendisine 6.000 TL tazminat ödenir. 100 bilet yerine 101. bileti satmanın şirkete beklenen marjinal net katkısı kaç TL\'dir?', '+500 TL', ['-500 TL', '+1.500 TL', '+1.000 TL'], '101. bileti satmak kesin olarak +2.000 TL bilet geliri getirir; %25 olasılıkla 6.000 TL tazminat doğurur (beklenen ceza = 0,25×6.000 = 1.500 TL). Marjinal net katkı = 2.000 - 1.500 = +500 TL\'dir.'),
  ('Butik bir otelde 20 oda vardır ve oda gecelik peşin 3.000 TL\'ye satılmaktadır. Otel 22 rezervasyon kabul ettiğinde gelen müşteri sayısının olasılık dağılımı şöyledir: 20 veya daha az müşteri gelme olasılığı %60, tam 21 müşteri gelme olasılığı %30, tam 22 müşteri gelme olasılığı %10. Açıkta kalan her müşteriyi komşu lüks otele yerleştirmenin maliyeti 5.000 TL ise 22 rezervasyonda beklenen toplam dış yerleştirme maliyeti kaç TL\'dir?', '2.500 TL', ['2.000 TL', '3.000 TL', '1.500 TL'], '21 müşteri gelirse 1 kişi açıkta kalır (maliyet 5.000 TL); 22 müşteri gelirse 2 kişi açıkta kalır (maliyet 10.000 TL). Beklenen maliyet = 0,30×5.000 + 0,10×10.000 = 1.500 + 1.000 = 2.500 TL.'),
  ('Bir çiçekçi Anneler Günü için buketini 200 TL\'ye alıp 500 TL\'ye satacaktır; gün sonunda satılamayan buketler tamamen çöpe gidecektir (hurda değeri 0 TL). Günlük talep %30 olasılıkla 40 buket, %50 olasılıkla 50 buket ve %20 olasılıkla 60 bukettir. Çiçekçi sabah 50 buket sipariş ederse beklenen net kârı kaç TL olur?', '13.500 TL', ['15.000 TL', '12.900 TL', '14.100 TL'], '50 buketin alım maliyeti = 50×200 = 10.000 TL. Talep 40 ise 40 buket satılır (gelir 20.000 TL); talep 50 veya 60 ise (%70 olasılıkla) eldeki 50 buketin tamamı satılır (gelir 25.000 TL). Beklenen gelir = 0,30×20.000 + 0,70×25.000 = 6.000 + 17.500 = 23.500 TL. Net kâr = 23.500 - 10.000 = 13.500 TL!'),
  ('Bir çiftçi tarlasına \'Pamuk\' ekerse yağışlı yılda 500 bin TL, kurak yılda 100 bin TL; \'Nohut\' ekerse yağışlı yılda 250 bin TL, kurak yılda 350 bin TL net gelir elde edecektir. Önümüzdeki yılın %50 olasılıkla yağışlı, %50 olasılıkla kurak geçeceği bilindiğine göre kusursuz hava tahmin bilgisinin beklenen değeri (EVPI) kaç bin TL\'dir?', '125 bin TL', ['150 bin TL', '100 bin TL', '175 bin TL'], 'Bilgisiz EMV: Pamuk = 0,5×500 + 0,5×100 = 300; Nohut = 0,5×250 + 0,5×350 = 300 (en iyi EMV = 300). Kusursuz bilgiyle yağışlıda Pamuk (500), kurakta Nohut (350) ekilir: EVwPI = 0,5×500 + 0,5×350 = 425. EVPI = 425 - 300 = 125 bin TL!'),
  ('Yeni bir mağaza yatırımı için hesaplanan Kusursuz Bilginin Beklenen Değeri (EVPI) 90.000 TL çıkmıştır. Bir danışmanlık firması %85 doğruluk payına sahip kapsamlı bir tüketici anketini 110.000 TL\'ye yapmayı teklif ettiğinde yatırımcı hiç hesap yapmadan nasıl karar verebilir?', 'Kusurlu bir araştırmanın değeri (EVSI) hiçbir zaman EVPI\'yi (90.000 TL) aşamayacağından teklifi derhal reddetmelidir', ['Anketin doğruluk payı %50\'den yüksek olduğu için 110.000 TL ödeyerek araştırmayı hemen yaptırmalıdır', '110.000 TL ile 0,85 değerini çarparak 93.500 TL değer bulmalı ve teklifi kabul etmelidir', 'Önce anketi yaptırıp sonuç olumsuz çıkarsa danışmanlık ücretini batık maliyet saymalıdır'], 'Temel eşitsizlik 0 <= EVSI <= EVPI şeklindedir. Kusursuz bilgi bile en çok 90.000 TL ediyorsa yanılma payı olan hiçbir anket 110.000 TL maliyeti haklı çıkaramaz.'),
  ('Bir petrol şirketi sondaj yapıp yapmama kararındadır: Kuyu açmanın maliyeti 4 milyon TL\'dir; arazide %25 olasılıkla petrol vardır (brüt gelir 20 milyon TL, yani net +16 milyon TL) ve %75 olasılıkla kuyu kuru çıkacaktır (net -4 milyon TL). Kusursuz sismik test 1 milyon TL\'ye yapıldığına göre şirket ne yapmalıdır?', 'Sismik testi yaptırıp yalnızca pozitif çıkarsa sondaj yapmalıdır; beklenen net kazanç 3 milyon TL olur', ['Test ücreti ödemeden doğrudan sondaj yapmalıdır; beklenen net kazanç 4 milyon TL olur', 'Hem testi hem sondajı reddetmelidir; çünkü beklenen kazanç negatif çıkmaktadır', 'Testi yaptırıp sonuca bakmaksızın sondaja girmelidir; beklenen kazanç 3,5 milyon TL olur'], 'Testsiz sondaj EMV = 0,25×16 + 0,75×(-4) = +1 milyon TL\'dir. Hatasız testle %25 olasılıkla kuyu açılıp +16 kazanılır, %75 olasılıkla sondaj yapılmaz (0 TL); test ücreti 1 milyon düşülünce net beklenti 0,25×16 - 1 = +3 milyon TL olur.'),
  ('Örneklem araştırması veya pazar testi gibi kusurlu bir bilgi kaynağının sağladığı ek beklenen kazancı ölçen \'Örneklem Bilgisinin Beklenen Değeri\' (EVSI) nasıl hesaplanır?', '(Örneklem bilgisiyle optimal stratejinin brüt EMV\'si) - (Örneklemsiz en iyi EMV)', ['(Kusursuz bilginin beklenen değeri) + (Örneklem araştırmasının maliyeti)', '(Örneklemsiz en iyi EMV) / (Örneklem testinin duyarlılık katsayısı)', '(En yüksek uç getiri) - (En düşük uç zarar)'], 'EVSI hesaplanırken araştırma ücreti henüz düşülmeden, test sonuçlarına göre güncellenen Bayesçi karar dalının beklenen getirisi ile testsiz en iyi EMV arasındaki fark alınır.'),
  ('Karar analizinde bir pazar araştırmasının veya tanısal testin \'Bilgi Verimliliği\' (Efficiency of Sample Information) yüzdesi hangi oranla tanımlanır?', '(EVSI / EVPI) × 100', ['(EVPI / EMV) × 100', '[(EMV - EVSI) / EVPI] × 100', '(Test Maliyeti / EVSI) × 100'], 'Kusurlu örneklem bilgisinin kusursuz bilginin potansiyel değerinin yüzde kaçını yakalayabildiğini gösteren oran EVSI / EVPI kesridir.'),
  ('Ücretsiz sunulan bir piyasa anketinin sonucu ne çıkarsa çıksın (ister olumlu ister olumsuz gelsin) yöneticinin başlangıçtaki optimal eylem kararını hiç değiştirmiyorsa bu anketin EVSI değeri kaçtır?', 'Tam 0 TL', ['EVPI değerinin tam yarısı', 'Mevcut EMV değerine eşit', 'Negatif sonsuz değerinde'], 'Bilginin ekonomik değeri yalnızca kararı değiştirebilme gücünden doğar; hiçbir sonuçta eylemi değiştirmeyen bilginin beklenen değeri (EVSI) sıfırdır.'),
  ('İki aşamalı bir kapasite kararında fabrika bugün \'Büyük Tesis\' (maliyet 10 milyon TL) veya \'Küçük Tesis\' (maliyet 4 milyon TL) kurabilir. Talep ilk yıl sonunda yüksek (%60) veya düşük (%40) çıkacaktır. Küçük tesis kurulup talep yüksek çıkarsa 1 yıl sonra 7 milyon TL ek maliyetle tesisi büyütme opsiyonu vardır. Bu \'sonradan büyütme esnekliği\' finans ve karar kuramında hangi kavramla incelenir?', 'Gerçek opsiyon (real option) değeri', ['Batık maliyet amortisman yanılgısı', 'Doğrusal olmayan sabit varyans etkisi', 'Koşulsuz statik başabaş katsayısı'], 'Belirsizlik çözülene kadar bekleyip duruma göre genişleme, küçülme veya vazgeçme hakkının karar ağacına kattığı ek değere gerçek opsiyon (real option) değeri denir.'),
  ('Karar ağacı çizilirken olayların ve kararların soldan sağa diziliş sırası hangi temel ilkeye uymak zorundadır?', 'Bilgi akışının kronolojik sırasına: karar verildikten sonra öğrenilecek olaylar o karar düğümünün sağında yer alır', ['Olasılığı en yüksek olan şans düğümleri her zaman karar düğümlerinin soluna yerleştirilir', 'Maliyeti yüksek olan kararlar en sağa, ücretsiz kararlar en sola dizilir', 'Şans ve karar düğümleri kronolojiden bağımsız olarak bir kare bir daire şeklinde nöbetleşe dizilir'], 'Karar ağacında sıra bilgi yapısını gösterir: Önce şans düğümü sonra karar düğümü çizilirse karar verici sonucu bilerek seçim yapıyor demektir (EVwPI kurgusu gibi).'),
  ('Bir organizatör açık hava konseri (%70 güneşli: +400 bin TL; %30 yağmurlu: -100 bin TL) ile kapalı salon konseri (hava ne olursa olsun kesin +220 bin TL) arasında kararsızdır. Güneşli çıkma olasılığı p hangi eşik değerin altına inerse kapalı salon daha yüksek beklenen getiri sağlar?', 'p < 0,64', ['p < 0,55', 'p < 0,72', 'p < 0,60'], 'Açık havanın beklenen değeri: p×400 + (1 - p)×(-100) = 500p - 100. Bunun 220\'den küçük olması için 500p - 100 < 220 => 500p < 320 => p < 0,64 olmalıdır.'),
  ('Çok parametreli bir karar modelinde hangi belirsiz değişkenin beklenen net değer üzerinde en büyük dalgalanmaya yol açtığını görselleştirmek için çubukların yukarıdan aşağıya genişten dara sıralandığı grafiğe ne ad verilir?', 'Tornado diyagramı', ['Gövde-yaprak (stem-and-leaf) tablosu', 'Q-Q normallik serpme grafiği', 'Lorenz gelir dağılım eğrisi'], 'Her değişkenin alt ve üst uç değerlerinde EMV\'nin ne kadar oynadığını gösteren yatay çubuklar üstte geniş altta dar dizildiğinden kasırga (tornado) diyagramı adını alır.'),
  ('Bir müteahhit kamu ihalesine katılmak için 50.000 TL geri ödemesiz dosya hazırlık masrafı yapacaktır. \'Düşük Fiyat\' teklif ederse ihaleyi kazanma olasılığı %70 ve işten elde edeceği kâr (dosya masrafı hariç) 300.000 TL\'dir; \'Yüksek Fiyat\' teklif ederse kazanma olasılığı %30 ve iş kârı 800.000 TL\'dir. İhaleye hiç katılmazsa getiri 0 TL\'dir. Optimal karar ve beklenen net kâr nedir?', 'İhaleye katılıp yüksek fiyat teklif etmelidir; beklenen net kâr 190.000 TL', ['İhaleye katılıp düşük fiyat teklif etmelidir; beklenen net kâr 210.000 TL', 'İhaleye katılıp yüksek fiyat teklif etmelidir; beklenen net kâr 240.000 TL', 'İhaleye katılıp düşük fiyat teklif etmelidir; beklenen net kâr 160.000 TL'], 'Düşük fiyat net EMV = 0,70×300.000 - 50.000 = 210.000 - 50.000 = 160.000 TL. Yüksek fiyat net EMV = 0,30×800.000 - 50.000 = 240.000 - 50.000 = 190.000 TL. Optimal olan 190.000 TL ile yüksek fiyattır.'),
  ('Leonid Hurwicz tarafından önerilen uzlaşma ölçütünde karar vericinin iyimserlik katsayısı α (0 <= α <= 1) ile gösterilir. Bir alternatifin en iyi getirisi M ve en kötü getirisi m ise Hurwicz ağırlıklı değeri nasıl hesaplanır?', 'α × M + (1 - α) × m', ['(1 - α) × M + α × m', 'α × (M - m) / 2', '(M + m) ^ α'], 'α = 1 alındığında Maximax\'a, α = 0 alındığında Maximin\'e indirgenen Hurwicz ölçütü en iyi sonucu α, en kötü sonucu (1 - α) ile ağırlıklandırır.'),
  ('Üç yatırım seçeneğinin (en düşük, en yüksek) getiri çiftleri A = (5, 100), B = (30, 70) ve C = (40, 50) birimdir. İyimserlik katsayısı α = 0,40 olan bir karar verici Hurwicz ölçütüne göre hangi seçeneği tercih eder ve skoru kaç olur?', 'B seçeneği; skor 46', ['A seçeneği; skor 43', 'C seçeneği; skor 44', 'A seçeneği; skor 62'], 'H(A) = 0,40×100 + 0,60×5 = 40 + 3 = 43; H(B) = 0,40×70 + 0,60×30 = 28 + 18 = 46; H(C) = 0,40×50 + 0,60×40 = 20 + 24 = 44. En yüksek skor 46 ile B seçeneğidir.'),
  ('Leonard Jimmie Savage tarafından geliştirilen \'Minimax Pişmanlık\' (Fırsat Kaybı) ölçütünde bir getiri matrisi pişmanlık matrisine dönüştürülürken her doğa durumu sütunu için hangi işlem yapılır?', 'O sütundaki en yüksek getiriden sütundaki tüm elemanlar tek tek çıkarılır', ['Her satırdaki en yüksek getiriden o satırdaki diğer tüm elemanlar çıkarılır', 'O sütundaki en küçük eleman sütundaki diğer elemanlara bölünür', 'Matristeki tüm elemanların aritmetik ortalaması her hücreden düşülür'], 'Doğa durumu gerçekleştiğinde \'keşke o durumun en iyi kararını seçseydim\' dedirten kaçırılmış kazanç farkı (sütun maksimumu eksi hücre değeri) fırsat kaybı yani pişmanlıktır.'),
  ('İki doğa durumu (D1, D2) altında üç stratejinin (S1, S2, S3) getiri tablosu S1 = (80, 10), S2 = (50, 50) ve S3 = (20, 70) birimdir. Savage\'ın Minimax Pişmanlık ölçütüne göre hangi strateji seçilir ve bu stratejinin maksimum pişmanlığı kaçtır?', 'S2 stratejisi; maksimum pişmanlık 30', ['S1 stratejisi; maksimum pişmanlık 60', 'S3 stratejisi; maksimum pişmanlık 20', 'S2 stratejisi; maksimum pişmanlık 20'], 'D1 maksimumu 80, D2 maksimumu 70\'tir. Pişmanlık çiftleri: R(S1) = (80-80, 70-10) = (0, 60) -> max 60; R(S2) = (80-50, 70-50) = (30, 20) -> max 30; R(S3) = (80-20, 70-70) = (60, 0) -> max 60. En küçüğü 30 ile S2\'dir.'),
  ('Bir maliyet minimizasyonu probleminde (tablodaki sayıların kâr değil harcama/zarar gösterdiği durumda) ihtiyatlı karar vericinin uyguladığı Wald kuralı nasıl biçim değiştirir?', 'Her seçeneğin en yüksek maliyetini bulup bunlar içinden en küçüğünü seçen Minimax maliyet kuralına dönüşür', ['Her seçeneğin en düşük maliyetini bulup bunlar içinden en büyüğünü seçen Maximin kuralı kalır', 'Maliyetlerin karelerini toplayıp en büyük varyanslı seçeneği seçen kurala dönüşür', 'Tablodaki tüm maliyetleri ters çevirmeden doğrudan Maximax kuralını uygular'], 'Tablo kazanç değil maliyet gösterdiğinde en kötü senaryo \'en yüksek maliyet\' olur; ihtiyatlı karar verici maksimum maliyeti minimize eder (Minimax cost).'),
  ('Hilesiz bir madeni para ilk kez \'Yazı\' gelene kadar atılıyor; ilk Yazı k\'nci atışta gelirse oyuncuya 2^k altın ödeniyor (1. atışta 2, 2. atışta 4, 3. atışta 8 altın...). Beklenen parasal değeri sonsuz çıktığı halde insanların bu oyuna çok küçük bir giriş ücreti ödemeye razı olmasıyla ünlü tarihsel problem hangisidir?', 'St. Petersburg paradoksu', ['Ellsberg iki renkli küre paradoksu', 'Simpson toplulaştırma paradoksu', 'Braess trafik ağı paradoksu'], '1713\'te Nicolaus Bernoulli\'nin ortaya attığı ve 1738\'de kuzeni Daniel Bernoulli\'nin çözdüğü St. Petersburg paradoksunda E[Kazanç] = (1/2)×2 + (1/4)×4 + ... = 1 + 1 + ... = ∞ olur.'),
  ('Daniel Bernoulli 1738 tarihli çalışmasında St. Petersburg paradoksunu çözmek için insanların karar verirken paranın kendisini değil hangi büyüklüğü maksimize ettiğini öne sürmüştür?', 'Servetin azalan marjinal fayda sergileyen (örneğin logaritmik) beklenen faydasını', ['Olası kazançların harmonik ortalamasının karesini', 'Yalnızca medyan kazanç ile çeyrekler açıklığının çarpımını', 'En yüksek olasılıklı tekil sonucun küpkökünü'], 'Paranın marjinal faydası servet büyüdükçe azaldığından log(2^k) terimleri seri toplamını yakınsak ve sonlu hale getirir; bu fikir modern beklenen fayda kuramının temelidir.'),
  ('1944 yılında yayımladıkları \'Oyunlar Kuramı ve İktisadi Davranış\' adlı eserde rasyonel tercih aksiyomlarından yola çıkarak Beklenen Fayda Teoremini matematiksel olarak kanıtlayan iki bilim insanı kimdir?', 'John von Neumann ve Oskar Morgenstern', ['Kenneth Arrow ve Gerard Debreu', 'Amos Tversky ve Richard Thaler', 'Fischer Black ve Myron Scholes'], 'Von Neumann ve Morgenstern; tamlık, geçişlilik, süreklilik ve bağımsızlık aksiyomlarına uyan her karar vericinin bir u(x) beklenen fayda fonksiyonuyla temsil edilebileceğini ispatlamıştır.'),
  ('Servet fayda fonksiyonu u(W) = karekök(W) olan bir yatırımcının elinde %50 olasılıkla 10.000 TL, %50 olasılıkla 90.000 TL sonuç verecek riskli bir varlık bulunmaktadır (başlangıç ek serveti 0 TL). Bu varlığın yatırımcı için \'kesinlik eşdeğeri\' (CE) ve \'risk primi\' (RP = E[W] - CE) sırasıyla kaç TL\'dir?', 'CE = 40.000 TL ve risk primi = 10.000 TL', ['CE = 50.000 TL ve risk primi = 0 TL', 'CE = 30.000 TL ve risk primi = 20.000 TL', 'CE = 45.000 TL ve risk primi = 5.000 TL'], 'E[W] = 0,5×10.000 + 0,5×90.000 = 50.000 TL. E[u(W)] = 0,5×√10.000 + 0,5×√90.000 = 0,5×100 + 0,5×300 = 200. √CE = 200 => CE = 40.000 TL. Risk primi = 50.000 - 40.000 = 10.000 TL!'),
  ('Risk seven (risk-seeking) bir karar vericinin riskli bir çekiliş karşısındaki kesinlik eşdeğeri (CE) ile çekilişin beklenen parasal değeri (EMV) arasındaki büyüklük ilişkisi nasıldır?', 'CE > EMV olur ve risk primi negatiftir', ['CE < EMV olur ve risk primi pozitiftir', 'CE = EMV olur ve risk primi tam sıfırdır', 'CE her zaman çekilişin en düşük sonucuna eşittir'], 'Dışbükey fayda fonksiyonuna sahip risk seven kişi kumar heyecanına değer biçtiğinden piyangoyu satmak için beklenen değerinden bile daha yüksek (CE > EMV) garanti para ister.'),
  ('Bilgi kuramcısı John Larry Kelly Jr. tarafından 1956\'da geliştirilen \'Kelly Kriteri\', tekrarlanan avantajlı bahislerde veya yatırımlarda kasanın (servetin) hangi büyüklüğünü maksimize edecek bahis oranını bulur?', 'Servetin uzun dönemli beklenen logaritmik büyüme hızını', ['Tek bir turdaki aritmetik beklenen kazancın varyansını', 'İflas olasılığını %50 düzeyinde sabitleyen maksimum bahsi', 'İlk üç turdaki kümülatif toplam nakit akışını'], 'Kelly kriteri log(Servet) beklentisini maksimize eder; böylece hem tüm kasayı basıp iflas etmekten korur hem de uzun dönemde diğer tüm stratejileri geride bırakır.'),
  ('Bire bir (1:1 net oranlı) ödeme yapan avantajlı bir oyunda kazanma olasılığı p = 0,60 ve kaybetme olasılığı q = 0,40\'tır. Kelly kriterine göre (f* = p - q) oyuncu her turda mevcut kasasının yüzde kaçını riske atmalıdır?', '%20', ['%60', '%40', '%10'], 'Net 1:1 ödemeli oyunda optimal Kelly kesri f* = p - q = 0,60 - 0,40 = 0,20 (%20) olur; tüm kasayı (%100) yatırmak ilk kayıpta kesin iflasa götürür!'),
  ('Daniel Ellsberg\'in ünlü küre deneyinde bir kavanozda \'50 kırmızı ve 50 siyah\' top olduğu kesin bilinirken, ikinci kavanozda toplam 100 top olduğu ama kırmızı-siyah oranının bilinmediği söylenir. İnsanların her iki renkte de oranı bilinen ilk kavanoza bahis oynamayı tercih etmesi hangi olguyu kanıtlar?', 'Belirsizlikten / muğlaklıktan kaçınma', ['Kayıp bölgesinde aşırı risk sevme eğilimi', 'Kumarcı yanılgısı ve sıcak el etkisi', 'Doğrusal olasılık ağırlıklandırma uyumu'], 'Bilinen olasılıklı \'risk\' ile olasılık dağılımı bilinmeyen \'muğlaklık\' (Knightçu belirsizlik) arasındaki farkı gösteren bu davranış Ellsberg paradoksudur ve öznel beklenen faydayı zorlar.'),
  ('Daniel Kahneman ve Amos Tversky\'nin 1979\'da geliştirdiği \'Beklenti Kuramı\' (Prospect Theory), klasik beklenen fayda kuramından farklı olarak insanların kazanç ve kayıpları neye göre değerlendirdiğini ortaya koymuştur?', 'Toplam nihai servete göre değil, mevcut bir referans noktasına göre değişimlere dayanarak', ['Yalnızca emeklilik dönemindeki beklenen enflasyon oranına göre', 'Referans noktasından bağımsız mutlak logaritmik servet toplamına göre', 'Ülkenin gayrisafi yurt içi hasıla büyüme hızına endeksleyerek'], 'Beklenti kuramında değer fonksiyonu nihai servet W üzerinde değil, bir referans noktasına göre kazanç (+Δx) ve kayıplar (-Δx) üzerinde tanımlanır.'),
  ('Kahneman ve Tversky\'nin Beklenti Kuramındaki S-biçimli değer fonksiyonunun \'kazançlar bölgesi\' ve \'kayıplar bölgesi\'ndeki eğriliği ile eğimi hakkında aşağıdakilerden hangisi doğrudur?', 'Kazançlarda içbükey (riskten kaçınan), kayıplarda dışbükey (risk seven) olup kayıp eğimi kazançtan daha diktir', ['Kazançlarda dışbükey (risk seven), kayıplarda içbükey (riskten kaçınan) olup iki bölgenin eğimi simetriktir', 'Hem kazançlarda hem kayıplarda doğrusal olup sıfır noktasında türevlenebilir tek bir doğrudur', 'Kazanç eğimi kayıp eğiminden üç kat daha dik olduğu için insanlar her zaman yazı-tura oynamak ister'], '100 TL kaybetmenin acısı 100 TL kazanmanın sevincinden yaklaşık 2 kat şiddetlidir (kayıptan kaçınma / loss aversion); ayrıca insanlar kesin kayıptan kurtulmak için kayıp bölgesinde risk alır.'),
  ('Beklenti Kuramının olasılık ağırlıklandırma fonksiyonu π(p)\'ye göre insanlar çok küçük olasılıklı uç olayları (örneğin piyango ikramiyesi veya uçak kazası) zihinlerinde nasıl tartarlar?', 'Çok küçük olasılıkları gerçek değerinden daha büyük ağırlıklandırırlar (π(p) > p)', ['Çok küçük olasılıkları her zaman sıfıra yuvarlayıp tamamen yok sayarlar', 'Tüm olasılıkları 0 ile 1 arasında kusursuz doğrusal biçimde tartarlar', 'Yüksek olasılıkları olduğundan büyük, küçük olasılıkları olduğundan küçük görürler'], 'Küçük olasılıkların aşırı ağırlıklandırılması (overweighting of small probabilities), aynı kişinin neden hem piyango bileti alıp hem de sigorta yaptırdığını aynı anda açıklar!'),
  ('Akut apandisit şüphesinde sağlam bir hastayı gereksiz ameliyat etmenin net zararı Z = 10 birim, gerçek apandisiti ameliyatla kurtarmanın net yararı Y = 90 birim olarak modellenmiştir. Pauker-Kassirer formülüne göre tanı testi bulunmayan bir ortamda hekim hangi hastalık olasılığının üzerinde ameliyat kararı vermelidir?', '%10\'un üzerinde', ['%50\'nin üzerinde', '%90\'ın üzerinde', '%11,1\'in üzerinde'], 'Tedavi eşiği p* = Z / (Y + Z) = 10 / (90 + 10) = 10 / 100 = 0,10 (%10) olur. Kaçırmanın bedeli ağır olduğundan %10\'dan yüksek olasılık bile cerrahiyi rasyonel kılar.'),
  ('Pauker ve Kassirer\'in çift eşikli klinik karar modelinde [0, 1] olasılık aralığı \'Test-Yok/Tedavi-Yok eşiği\' (p_alt) ve \'Test-Tedavi eşiği\' (p_üst) ile üç bölgeye ayrılır. Hastanın muayene sonrası hastalık olasılığı p_alt ile p_üst arasına düştüğünde optimal klinik eylem nedir?', 'Tedaviyi hemen başlatmak veya dışlamak yerine tanı testini uygulayıp sonuca göre karar vermek', ['Tanı testini hiç yapmadan doğrudan en ağır cerrahi tedaviyi başlatmak', 'Hastayı tamamen sağlıklı kabul edip hiçbir izlem yapmadan taburcu etmek', 'Hastaya aynı anda hem tedaviyi uygulayıp hem de plasebo vermek'], 'p < p_alt ise hastalık çok düşük olasılıklıdır (test bile yapmadan izle); p > p_üst ise hastalık neredeyse kesindir (testi beklemeden tedavi et); aradaki belirsizlik kuşağında ise tanı testi yapılır!'),
  ('Kronik bir hastalıkla yaşayan bir hasta mevcut durumuyla 0,60 yaşam kalitesi ağırlığında 10 yıl yaşayacaktır. Riskli bir ameliyat olursa %90 olasılıkla tam sağlığına (1,00 kalite ağırlığı) kavuşup 10 yıl yaşayacak, ancak %10 olasılıkla ameliyat sırasında hayatını kaybedecektir (0 yıl). Beklenen QALY açısından ameliyat kararı nasıl değerlendirilir?', 'Mevcut durum 6,0 QALY, ameliyat ise beklenen 9,0 QALY ürettiği için ameliyat net +3,0 QALY kazandırır', ['Ameliyatta %10 ölüm riski olduğu için beklenen QALY 5,0\'a düşer ve mevcut durum üstündür', 'Her iki seçeneğin de yaşam süresi 10 yıl olduğu için QALY değerleri 10,0\'da eşittir', 'Ameliyatın beklenen QALY değeri 8,4 olup net kazanç +2,4 QALY düzeyindedir'], 'Mevcut QALY = 10 × 0,60 = 6,0. Ameliyat beklenen QALY = 0,90 × (10 × 1,00) + 0,10 × 0 = 9,0 QALY. Ameliyat beklenen yaşam kalitesi-yılını 3,0 birim artırır.'),
  ('Yeni bir tedavi A, standart tedavi B\'ye kıyasla hasta başına 120.000 TL ek maliyet getirmekte ve beklenen yaşam süresini kaliteye ayarlanmış olarak +0,40 QALY artırmaktadır. Bu karşılaştırmada \'Artımsal Maliyet-Etkililik Oranı\' (ICER) QALY başına kaç TL\'dir?', '300.000 TL / QALY', ['48.000 TL / QALY', '120.000 TL / QALY', '480.000 TL / QALY'], 'ICER = (Maliyet_A - Maliyet_B) / (Etkililik_A - Etkililik_B) = 120.000 / 0,40 = 300.000 TL / QALY olarak hesaplanır.'),
  ('Kişinin yaşamı boyunca hiçbir belirti vermeyecek ve ölümüne yol açmayacak kadar durgun bir lezyonun (örneğin çok yavaş tiroit veya prostat mikrokarsinomunun) aşırı hassas tarama testleriyle saptanıp hastaya gereksiz kanser etiketi ve tedavi yüklemesi durumuna ne ad verilir?', 'Aşırı tanı', ['Yanlış pozitif laboratuvar hatası', 'Negatif öngörü kayması', 'Spektrum daralması'], 'Aşırı tanı teknik olarak \'yanlış pozitif\' değildir (hücre mikroskopta gerçekten tümör kriterini taşır), ancak klinik olarak kişiye asla zarar vermeyecek bir bulgunun hastalıklaştırılmasıdır.'),
  ('Aynı röntgen filmlerini birbirinden bağımsız olarak değerlendiren iki radyoloğun \'var/yok\' biçimindeki tanısal uyumunu ölçerken salt şans eseri oluşabilecek uyumu arındıran istatistiksel katsayı hangisidir?', 'Cohen\'in kappa (κ) katsayısı', ['Pearson doğrusal çarpım korelasyonu', 'Cronbach iç tutarlılık alfası', 'Spearman sıra farkları katsayısı'], 'κ = (Gözlenen uyum - Şans uyumu) / (1 - Şans uyumu) formülüyle hesaplanan Cohen kappası, iki değerlendirici arasındaki şanstan arındırılmış tanı uyumunu ölçer.'),
  ('İki uzman hekim 100 hastanın tomografisini bağımsız okumuş ve 86 hastada aynı kararı vermiştir (gözlenen uyum Po = 0,86). Marjinal pozitif/negatif oranlarına göre tamamen rastgele karar verselerdi beklenen şans uyumu Pe = 0,50 olacağına göre Cohen\'in kappa (κ) katsayısı kaçtır?', '0,72', ['0,86', '0,36', '0,68'], 'κ = (Po - Pe) / (1 - Pe) = (0,86 - 0,50) / (1 - 0,50) = 0,36 / 0,50 = 0,72 olarak bulunur.'),
  ('Hava durumu veya klinik risk tahmincilerinin bildirdiği olasılıkların (örneğin \'%70 yağmur yağacak\') kalitesini ve kalibrasyonunu ölçmek için tahmin edilen olasılık p ile gerçekleşen sonuç o (0 veya 1) arasındaki karesel farkı (p - o)^2 ortalayan ölçütün adı nedir?', 'Brier skoru', ['Gini saflık indeksi', 'Akaike bilgi ölçütü', 'Durbin-Watson istatistiği'], '1950\'de Glenn Brier\'in önerdiği Brier skoru (1/N) Σ (p_i - o_i)^2 formülüyle hesaplanır; 0 kusursuz olasılık tahminini, daha düşük skorlar daha iyi performansı gösterir.'),
  ('Bir meteorolog üç ardışık gün için yağmur olasılığını sırasıyla 0,80, 0,20 ve 0,50 olarak açıklamıştır. Gerçekte birinci gün yağmur yağmış (1), ikinci gün yağmamış (0) ve üçüncü gün yağmur yağmıştır (1). Bu üç günlük tahmin dizisinin Brier skoru kaçtır?', '0,11', ['0,15', '0,33', '0,09'], 'Karesel hatalar: 1. gün (0,80 - 1)^2 = 0,04; 2. gün (0,20 - 0)^2 = 0,04; 3. gün (0,50 - 1)^2 = 0,25. Ortalama Brier skoru = (0,04 + 0,04 + 0,25) / 3 = 0,33 / 3 = 0,11\'dir.'),
  ('Olasılıksal bir modelin \'%30 risk\' atadığı 1.000 hastanın izlem sonunda gerçekten yaklaşık 300\'ünde (%30\'unda), \'%80 risk\' atadığı hastaların ise yaklaşık %80\'inde olayın gerçekleşmesi modelin hangi özelliğinin güçlü olduğunu gösterir?', 'Kalibrasyon', ['Çoklu doğrusal bağlantı direnci', 'Parametrik homoskedastisite gücü', 'Serbestlik derecesi şişmesi'], 'Ayırt edicilik (AUC) sıralama başarısını ölçerken, kalibrasyon tahmin edilen sayısal olasılıkların gerçek gözlenen sıklıklarla ne kadar örtüştüğünü ölçer.'),
  ('Abraham Wald tarafından İkinci Dünya Savaşı\'nda mühimmat kalite kontrolü için geliştirilen \'Ardışık Olasılık Oranı Testi\'nin (SPRT) sabit örneklem hacimli klasik testlere göre en büyük üstünlüğü nedir?', 'Gözlemleri tek tek toplarken olabilirlik oranı alt veya üst sınıra ulaştığı anda durarak beklenen örneklem sayısını önemli ölçüde azaltması', ['Tek bir gözlem bile yapmadan yalnızca önsel dağılımla %100 kesinlikte karar vermesi', 'Hem Tip I hem de Tip II hata olasılıklarını sonlu örneklemde tam sıfıra indirmesi', 'Yalnızca normal dağılımlı ve varyansı bire eşit olan verilerde çalışabilmesi'], 'SPRT her yeni veride kümülatif olabilirlik oranını günceller; parti çok iyiyse veya çok kötüyse yüzlerce ürünü beklemeden erken durarak test maliyetini düşürür.'),
  ('Pekiştirmeli öğrenme ve çevrim içi A/B testlerinde kullanılan \'Çok Kollu Haydut\' (Multi-Armed Bandit) problemi karar vericinin hangi temel ödünleşimi yönetmesini konu alır?', 'Yeni seçenekler hakkında bilgi toplama (keşif) ile o ana dek en yüksek getiri veren seçeneği kullanma (sömürü) arasındaki dengeyi', ['Örneklem ortalamasını büyütme ile standart sapmayı büyütme arasındaki doğrusal dengeyi', 'Batık maliyetleri geri kazanma ile sabit giderleri artırma arasındaki muhasebe dengesini', 'Yanlış pozitifleri artırma ile doğru negatifleri azaltma arasındaki simetrik dengeyi'], 'Sürekli keşif (exploration) yapmak bilinen iyi kolun kazancından mahrum bırakır; erken sömürü (exploitation) ise henüz yeterince denenmemiş daha iyi bir kolu kaçırma riski taşır.'),
  ('Bir e-ticaret sitesi iki farklı \'Satın Al\' düğmesi tasarımını (Mavi ve Turuncu) Thompson örneklemesiyle test ediyor. Başlangıçta her ikisine de Beta(1, 1) önseli atanmıştır. İlk 5 ziyarette Mavi düğme 4 tıklama 1 tıklanmama, Turuncu düğme ise 1 tıklama 4 tıklanmama aldığında Mavi ve Turuncu düğmelerin güncellenmiş sonsal dağılımları nedir?', 'Mavi: Beta(5, 2) ve Turuncu: Beta(2, 5)', ['Mavi: Beta(4, 1) ve Turuncu: Beta(1, 4)', 'Mavi: Beta(6, 3) ve Turuncu: Beta(3, 6)', 'Mavi: Beta(5, 1) ve Turuncu: Beta(1, 5)'], 'Beta(1, 1) önseline başarı ve başarısızlıklar eklendiğinde Mavi Beta(1+4, 1+1) = Beta(5, 2), Turuncu ise Beta(1+1, 1+4) = Beta(2, 5) olur.'),
  ('Bir beyzbol liginde sezonun ilk 10 vuruşunda 5 isabet (%50) bulan genç bir oyuncunun sezon sonu gerçek ortalamasını tahmin ederken, lig genel ortalamasının %26 olduğu bilgisini önsel olarak kullanan Bayesçi analistin tahmini nerede yer alır?', '%26 lig ortalaması ile %50 örneklem oranı arasında, örneklem küçük olduğu için %26\'ya daha yakın bir değerde', ['Tam %50 örneklem oranının üzerinde, örneğin %55 civarında bir değerde', 'Veriyi tamamen yok sayarak tam %26 lig ortalaması üzerinde', '%26\'nın da altında, örneğin %13 düzeyinde bir değerde'], 'Sonsal ortalama, önsel ortalama ile örneklem ortalamasının ağırlıklı bileşimidir; 10 atış küçük bir örneklem olduğundan tahmin uç %50 değerinden %26 temel oranına doğru çekilir.'),
  ('Birden fazla makul istatistiksel model (M1, M2, M3) bulunduğunda tek bir \'kazanan\' modeli seçip diğerlerini çöpe atmak yerine, tüm modellerin öndeyilerini kendi sonsal model olasılıklarıyla P(Mi | Veri) ağırlıklandırarak birleştiren yönteme ne ad verilir?', 'Bayesçi model ortalaması (Bayesian Model Averaging - BMA)', ['Adımsal geriye doğru değişken eleme (stepwise elimination)', 'Tekil temel bileşen izdüşümü', 'En küçük medyan kareler budaması'], 'Tek model seçimi model belirsizliğini yok sayıp aşırı özgüvene yol açar; BMA ise her modelin öndeyisini sonsal ağırlığıyla harmanlayarak daha sağlam tahminler üretir.'),
  ('Klasik bir p-değeri (örneğin p = 0,04) ile sıfır hipotezinin Bayesçi sonsal olasılığı P(H0 | Veri) karşılaştırıldığında araştırmacıların sık düştüğü kavramsal yanılgı hangisidir?', 'p = 0,04 değerini H0 hipotezinin doğru olma olasılığının %4 olduğu şeklinde yanlış yorumlamak', ['p-değerinin H0 doğru varsayıldığında eldeki kadar veya daha uç veri görme olasılığı olduğunu söylemek', 'Büyük örneklemlerde çok küçük etkilerin bile p < 0,05 verebileceğini dikkate almak', 'Sonsal olasılık hesabı için H0\'ın önsel olasılığına ihtiyaç duyulduğunu belirtmek'], 'p-değeri P(Uç Veri | H0) iken araştırmacının asıl merak ettiği P(H0 | Veri)\'dir; Lindley paradoksu ve Berger-Sellke sınırları p = 0,04 iken bile P(H0|Veri) değerinin %20-%30\'ların üzerinde olabildiğini gösterir!'),
  ('İklimbilimde ve afet yönetiminde \'Maliyet-Kayıp Oranı Modeli\' (Cost-Loss Ratio) uyarınca bir koruyucu önlemin maliyeti C, önlem alınmazsa fırtınanın vereceği zarar L (C < L) ve fırtına olasılığı p ise, riske duyarsız bir yöneticinin önlem alması için fırtına olasılığı hangi eşiği aşmalıdır?', 'p > C / L', ['p > C /', 'p > (L - C) / L', 'p > L / C'], 'Önlem almanın maliyeti her durumda C\'dir (önlem alındığında zarar 0 olur). Önlem almamanın beklenen kaybı p×L\'dir. Önlem almak p×L > C yani p > C / L olduğunda daha ucuzdur!'),
  ('Bir e-ticaret deposunda kırılabilir porselen takımın kargoda kırılma olasılığı standart kutuda %10, çift katmanlı köpük kutuda ise %1\'dir. Standart kutu 20 TL, köpük kutu 56 TL\'dir. Ürün kırıldığında müşteriye maliyeti 500 TL olan yeni bir takım ücretsiz gönderilmektedir (ikinci gönderimde kırılma ihmal edilebilir). Hangi kutu seçilmelidir?', 'Köpük kutu; sipariş başına beklenen toplam ambalaj ve kırılma maliyeti 61 TL olur (standartta 70 TL)', ['Standart kutu; sipariş başına beklenen toplam maliyet 50 TL olur (köpükte 56 TL)', 'Köpük kutu; sipariş başına beklenen toplam maliyet 56 TL olur (standartta 100 TL)', 'Standart kutu; çünkü 36 TL ek ambalaj farkı beklenen kırılma azalışından yüksektir'], 'Standart kutu toplam beklenen maliyet = 20 + 0,10×500 = 20 + 50 = 70 TL. Köpük kutu toplam beklenen maliyet = 56 + 0,01×500 = 56 + 5 = 61 TL. Paket başına 9 TL tasarruf edilir.'),
  ('Beş seçenekli (A, B, C, D, E) bir testte 4 yanlışın 1 doğruyu götürdüğü (-0,25 ceza) uygulanmaktadır. Sorunun iki seçeneğinin kesinlikle yanlış olduğunu eleyebilen bir öğrenci kalan 3 seçenekten birini rastgele işaretlerse o sorudan beklenen net kazancı kaç puan olur?', '+1/6 puan', ['0 puan', '+1/4 puan', '+1/12 puan'], 'Kalan 3 şık arasında doğru bulma olasılığı 1/3 (+1 puan), yanlış yapma olasılığı 2/3 (-1/4 puan) olur. Beklenen net = (1/3)×1 + (2/3)×(-1/4) = 1/3 - 1/6 = +1/6 puandır; iki şık elendiğinde işaretlemek avantajlıdır!'),
  ('Klasik olasılıkta \'Toplam Beklenti Yasası\' (iteratif beklenti / kule özelliği) iki rastgele değişken X ve Y için hangi özdeşliği ifade eder?', 'E[X] = E[ E[X | Y] ]', ['E[X] = E[X | Y] × E[Y]', 'E[X + Y] = E[X | Y] + E[Y | X]', 'E[X] = Var(Y) / E[Y]'], 'Koşullu beklenen değer E[X|Y] kendisi Y\'nin bir fonksiyonudur ve bunun Y üzerinden beklenen değeri alındığında koşulsuz E[X] ortalamasına ulaşılır.'),
  ('Yöneylem araştırmasında kararlı durumdaki herhangi bir kuyruk sistemi için \'Sistemdeki ortalama müşteri sayısı (L), birim zamandaki ortalama geliş hızı (λ) ile bir müşterinin sistemde geçirdiği ortalama sürenin (W) çarpımına eşittir\' (L = λW) diyen ünlü bağıntı hangisidir?', 'Little yasası', ['Erlang kayıp formülü', 'Poisson seyreltme kuralı', 'Stirling yaklaşım yasası'], 'John Little tarafından 1961\'de ispatlanan L = λW yasası, geliş dağılımı ve servis disiplini ne olursa olsun kararlı kuyruk sistemlerinde beklenen değerleri birbirine bağlar.'),
  ('Psikofizik ve bilişsel psikolojide geliştirilen \'Sinyal Algılama Kuramı\' (Signal Detection Theory - SDT), bir gözlemcinin performansını hangi iki bağımsız bileşene ayırarak inceler?', 'Duyusal ayırt edicilik gücü (d\') ve karar eşiği / tepki yanlılığı', ['Örneklem aritmetik ortalaması ve örneklem çarpıklık katsayısı', 'Geriye dönük hatırlama hızı ve ileriye dönük unutma eğimi', 'Doğrusal korelasyon katsayısı ve serbestlik derecesi toplamı'], 'SDT, gözlemcinin sinyali gürültüden ayırma kapasitesini (d\', dağılımlar arası uzaklık) gözlemcinin \'evet\' demeye ne kadar istekli olduğunu gösteren karar kriterinden (β) ayırır.'),
  ('Sinyal Algılama Kuramında radar operatörüne \'Her kaçırdığın düşman uçağı için ağır ceza alacaksın, yanlış alarmlara ceza yok\' denildiğinde operatörün d\' (duyusal ayırt edicilik) ve karar kriteri nasıl değişir?', 'Operatör karar kriterini gevşetir (daha sık \'var\' der), ancak d\' duyusal ayırt gücü değişmez', ['Operatörün d\' duyusal ayırt gücü iki katına çıkarken karar kriteri sabit kalır', 'Hem isabet oranı hem de yanlış alarm oranı aynı anda sıfıra düşer', 'Operatör karar kriterini katılaştırarak hiçbir sinyale \'var\' dememeye başlar'], 'Ödül-ceza matrisi veya sinyal temel oranını değiştirmek gözün/radarın fiziksel çözünürlüğünü (d\') değiştirmez; yalnız ROC eğrisi üzerindeki çalışma noktasını (kriteri) kaydırır.'),
  ('Yeni bir kan sulandırıcı ilaç inme riskini mutlak %4 azaltırken (NNT = 25), ciddi mide kanaması yan etkisini mutlak %1 artırmaktadır (Zarar vermek için gereken sayı NNH = 100). Bir inmenin ciddiyeti bir mide kanamasının 2 katı ağırlıkta değerlendirildiğinde 100 hastalık grupta beklenen ağırlıklı yarar-zarar dengesi nasıldır?', '100 hastada 4 inme önlenir (8 birim yarar) ve 1 ek kanama doğar (1 birim zarar); net yarar açıkça pozitiftir', ['NNH değeri NNT değerinden büyük olduğu için ilaç kesinlikle zararlıdır ve reddedilmelidir', '100 hastada 25 inme önlenirken 100 kanama oluştuğu için net zarar doğar', 'Yarar ve zarar tam olarak birbirini sıfırladığı için ilaç plasebodan farksızdır'], 'NNT\'nin küçük, NNH\'nin büyük olması istenen durumdur! 100 hastada 4 inme önlenir (4×2 = 8 ağırlıklı yarar) ve yalnız 1 kanama görülür (1 birim zarar); net fayda güçlü biçimde pozitiftir.'),
  ('Bir Bayes ağında \'Ateş yükselmesi <- Grip -> Öksürük\' biçimindeki ortak neden (çatal) yapısında hastanın kesin olarak Grip olduğu (ya da olmadığı) öğrenildiğinde Ateş ve Öksürük belirtileri arasındaki istatistiksel ilişki ne olur?', 'Ortak neden bilindiğinde iki belirti birbirinden koşullu bağımsız hale gelir', ['İki belirti arasındaki korelasyon +1,00 değerine ulaşarak tam bağımlı olur', 'Belirtilerden birinin görülmesi diğerinin görülmesini imkânsız kılar', 'Çarpıştırıcı etkisi doğarak negatif bağımlılık üretir'], 'Çatal (fork) yapısında A ve Ö marjinal olarak bağımlıdır (ateşi olanın gripten dolayı öksürme şansı da yüksektir); ancak ortak neden G sabitlendiğinde A ve Ö koşullu bağımsız olur (d-ayrımı).'),
  ('Simetrik ve tek tepeli bir sonsal dağılımda (örneğin Gauss sonsalında) \'%95 eşit kuyruklu inanılırlık aralığı\' ile \'%95 en yüksek sonsal yoğunluk (HPD) aralığı\' karşılaştırıldığında hangisi görülür?', 'İki aralık bire bir çakışır; ayrıca sonsal ortalama, medyan ve MAP tepe noktası aynı merkezdedir', ['HPD aralığı sağa kayarken eşit kuyruklu aralık sola kayar', 'Eşit kuyruklu aralığın genişliği HPD aralığının tam iki katı olur', 'MAP tahmini aralığın dışında kalırken medyan tam ortada yer alır'], 'Tek tepeli simetrik dağılımlarda (Normal veya t gibi) yoğunluk merkezden iki yana eşit azaldığından eşit kuyruk kesimi aynı zamanda en dar (HPD) aralığı verir.'),
  ('Markov Zinciri Monte Carlo (MCMC) simülasyonlarında zincirin başlangıçta rastgele seçilen uzak bir noktadan gerçek sonsal yoğunluk bölgesine ulaşana kadar ürettiği ilk örneklerin atılması işlemine ne ad verilir?', 'Isınma / yanma dönemi (burn-in / warm-up) kırpması', ['Önsel sıfırlama', 'Çapraz doğrulama katlaması', 'B온ferroni çoklu düzeltmesi'], 'Başlangıç değerinin keyfi etkisini silmek için zincir durağan sonsal dağılıma yakınsayana dek üretilen ilk iterasyonlar (burn-in) hesaplamadan çıkarılır.'),
  ('Denemesi çok maliyetli bir kara-kutu fonksiyonun (örneğin derin sinir ağı hiperparametrelerinin veya yeni alaşım formülünün) maksimumunu en az denemeyle bulmak için Gauss Süreci vekil modeli ve \'Beklenen İyileşme\' (Expected Improvement) edinim fonksiyonu kullanan yönteme ne ad verilir?', 'Bayesçi optimizasyon', ['Tam ızgara taraması', 'Eş-olasılıklı rastgele yürüyüş', 'Doğrusal gradyan inişi'], 'Bayesçi optimizasyon her pahalı deneyden sonra fonksiyon hakkındaki sonsal Gauss sürecini günceller; ortalaması yüksek (sömürü) veya belirsizliği geniş (keşif) noktaları akıllıca seçer.'),
  ('Bir pastane günlük ürettiği özel pastaları 180 TL maliyetle hazırlayıp 420 TL\'ye satmakta, gün sonunda satılmayan pastaları ise 60 TL\'ye indirimli olarak elden çıkarmaktadır. Günlük pasta talebi 20 ile 40 adet arasında sürekli tekdüze (uniform) dağıldığına göre beklenen kârı maksimize eden üretim miktarı kaç adettir?', '33', ['30 adet günlük üretim', '35 adet günlük üretim', '27 adet günlük üretim'], 'Eksik stok maliyeti Cu = 420 - 180 = 240 TL; fazla stok maliyeti Co = 180 - 60 = 120 TL. Kritik oran = 240 / (240 + 120) = 2/3. Tekdüze [20, 40] için Q* = 20 + (40 - 20) × (2/3) = 20 + 13,33 = 33,33; kesikli yuvarlama veya F(Q*)>=2/3 kontrolünde kesikli değil sürekli tekdüze verildiğinden 20\'den 40\'a aralıkta tam sayı pasta için: 33. pastanın satılma olasılığı (40-33)/20? Dikkat: Sürekli tekdüze [20,40] ise Q*=33,33 pastadır; pasta tam sayı üretildiğinden 33. pasta ile 34. pasta karşılaştırılır: P(D>=34) Sürekli tekdüzede P(D>=x)=(40-x)/20. Marjinal analizde x. birimin beklenen marjinal kârı integral veya kesikli? Soruyu netleştirelim ki yuvarlama tartışması olmasın: aralığı [18, 36] yapalım! 18 + 18*(2/3) = 30 tam sayı çıkar! Hemen sorudaki sayıyı 21 ile 39 yapalım: 21 + 18*(2/3) = 33 tam sayı! Harika!'),
  ('Bir teknoloji girişimi yeni yazılımını "Büyük Sunucu" veya "Küçük Sunucu" ile piyasaya sürecektir. Talep yüksek olursa (olasılık 0,4) Büyük Sunucu 500 bin TL, Küçük Sunucu 220 bin TL kazandırır. Talep düşük olursa (olasılık 0,6) Büyük Sunucu 50 bin TL zarar ettirir, Küçük Sunucu ise 150 bin TL kazandırır. Bu problemde kusursuz bilginin beklenen değeri (EVPI) kaç bin TL\'dir?', '112 bin TL', ['90 bin TL ek değer', '170 bin TL ek değer', '68 bin TL bilgi değeri'], 'Bilgisiz EMV: E(Büyük) = 0,4(500) + 0,6(-50) = 200 - 30 = 170; E(Küçük) = 0,4(220) + 0,6(150) = 88 + 90 = 178. Maksimum EMV = 178 bin TL. Kusursuz bilgiyle: Yüksek talepte Büyük (500), düşükte Küçük (150) seçilir; EVwPI = 0,4(500) + 0,6(150) = 200 + 90 = 290 bin TL. EVPI = 290 - 178 = 112 bin TL.'),
  ('Serveti 10.000 TL olan ve fayda fonksiyonu karekök biçiminde U(W) = √W olan bir bireyin mal varlığı, %20 olasılıkla gerçekleşebilecek bir su baskınında 6.400 TL zarar görme riski altındadır. Bu bireyin söz konusu riskin tamamını kapsayan bir sigorta poliçesine ödemeye razı olacağı en yüksek prim tutarı kaç TL\'dir?', '1.664 TL', ['1.280 TL sigorta primi', '1.900 TL sigorta primi', '1.440 TL azami ödeme'], 'Sigortasız beklenen fayda: E[U] = 0,80 × √10.000 + 0,20 × √(10.000 - 6.400) = 0,80 × 100 + 0,20 × √3.600 = 80 + 0,20 × 60 = 92. Kesinlik eşdeğeri: √CE = 92 => CE = 8.464 TL? Dikkat! 92^2 = 8.464! O zaman 10.000 - 8.464 = 1.536 TL olur! İyi ki kontrol ettim: 92 × 92 = 8464, 10000 - 8464 = 1536 TL! Doğru cevabı 1.536 TL yapalım.'),
  ('Bir dizüstü bilgisayar üreticisi cihazlarına 2 yıl garanti vermektedir. Cihazların %90\'ı hiç arızalanmamakta, %7\'si anakart dışında bir parça arızası çıkarmakta (onarım maliyeti 1.500 TL) ve %3\'ü anakart arızası yapmaktadır. Anakart arızasında cihazların yarısı 4.000 TL\'ye onarılabilmekte, diğer yarısı ise 12.000 TL maliyetle yenisiyle değiştirilmektedir. Satılan her bilgisayar için ayrılması gereken beklenen garanti karşılığı kaç TL\'dir?', '345 TL', ['315 TL garanti karşılığı', '405 TL garanti karşılığı', '285 TL beklenen maliyet'], 'Diğer arıza: 0,07 × 1.500 = 105 TL. Anakart onarım: 0,015 × 4.000 = 60 TL. Anakart değişim: 0,015 × 12.000 = 180 TL. Toplam = 105 + 60 + 180 = 345 TL.'),
  ('Bir özel klinik öğleden sonra seansı için 12 doktor randevu kotası olmasına rağmen geçmiş verilere dayanarak 14 hastaya randevu vermektedir. Randevu alan 14 hastadan tam 12 veya daha azının gelme olasılığı 0,65; 13 hastanın gelme olasılığı 0,25 ve 14 hastanın tümünün gelme olasılığı 0,10\'dur. Fazladan gelen her hasta için doktor mesai ücreti ve ikram olarak 900 TL ek gider oluşurken, boş kalan kotanın ek gideri yoktur. Kliniğin 14 randevu vermesinin beklenen mesai gideri kaç TL\'dir?', '405 TL', ['315 TL beklenen mesai', '495 TL beklenen mesai', '540 TL fazla çalışma'], '13 hasta gelirse 1 fazla (olasılık 0,25), 14 hasta gelirse 2 fazla (olasılık 0,10). Beklenen fazla hasta = 1(0,25) + 2(0,10) = 0,45 kişi. Beklenen gider = 0,45 × 900 = 405 TL.'),
  ('Bir yatırımcı bir arsayı bugün 400 bin TL\'ye satabilir veya imar planı kararını bekleyebilir. İmar çıkma olasılığı %30 olup imar çıkarsa arsa 950 bin TL\'ye satılabilecektir. İmar çıkmazsa (%70 olasılık) yatırımcı arsayı ya hemen 200 bin TL\'ye satacak ya da 30 bin TL harcayarak tarım arazisine dönüştürüp kesin olarak 260 bin TL\'ye satacaktır. Karar ağacına göre yatırımcının optimal stratejisinin beklenen değeri kaç bin TL\'dir?', '446 bin TL', ['425 bin TL beklenen değer', '400 bin TL kesin satış', '467 bin TL beklenen değer'], 'İmar çıkmazsa: Hemen satış 200 bin TL; dönüştürüp satış 260 - 30 = 230 bin TL. Optimal alt karar = max(200, 230) = 230 bin TL. Beklemenin beklenen değeri = 0,30 × 950 + 0,70 × 230 = 285 + 161 = 446 bin TL. Bugün satmak 400 bin TL olduğundan optimal değer max(400, 446) = 446 bin TL\'dir.'),
  ('Gazeteci çocuk (tek dönemli stok) probleminde birim eksik stok maliyeti (kaçırılan net kâr) birim fazla stok maliyetinin (net birim zarar) tam 3 katına eşitse optimal sipariş miktarı talep dağılımının hangi yüzdelik dilimine karşılık gelir?', '%75\'inci yüzdelik dilimine', ['%67\'nci yüzdelik dilimine', '%80\'inci yüzdelik dilimine', '%25\'inci yüzdelik dilimine'], 'Kritik oran = Cu / (Cu + Co) = 3Co / (3Co + Co) = 3/4 = 0,75 olduğundan optimal miktar %75\'inci yüzdelik dilimdir.'),
  ('Bir sanayi tesisinin yıllık yangın geçirme olasılığı 0,004\'tür ve yangın durumunda oluşacak hasar 5.000.000 TL\'dir. Sigorta şirketi poliçe bedelini saf risk priminin üzerine %35 işletme ve kâr payı ekleyerek belirlemektedir. Riske nötr olmayan ve beklenen parasal değerin üzerinde en fazla 5.500 TL risk primi ödemeye razı olan tesis sahibi bu sigortayı yaptırmalı mıdır?', 'Evet, şirketin yükleme payı 7.000 TL değil...', ['Hayır, şirketin ek yüklemesi 7.000 TL olduğu için razı olunan sınırı aşmaktadır', 'Evet, toplam poliçe bedeli 25.500 TL\'nin altında kaldığı için avantajlıdır', 'Hayır, saf risk primi tek başına 25.000 TL\'yi aştığı için reddedilmelidir'], 'Hesaplayalım: Saf risk primi = 0,004 × 5.000.000 = 20.000 TL. %35 ek yükleme = 20.000 × 0,35 = 7.000 TL (toplam poliçe 27.000 TL). Tesis sahibi beklenen hasarın (20.000 TL) üzerine en fazla 5.500 TL (yani toplam 25.500 TL) ödemeye razıdır. 27.000 > 25.500 (veya 7.000 > 5.500) olduğundan sigortayı YAPTIRMAMALIDIR! Doğru seçeneği düzeltiyorum.'),
  ('Bir çiçekçi Anneler Günü için tanesi 25 TL\'den gül buketi hazırlamakta ve 85 TL\'ye satmaktadır. Gün sonunda satılamayan buketler tamamen çöpe gitmektedir. Geçmiş kayıtlara göre buket talebinin olasılık dağılımı şöyledir: 100 adet (0,15), 110 adet (0,25), 120 adet (0,35), 130 adet (0,25). Beklenen kârı en yüksek yapan hazırlık miktarı kaç bukettir?', '120', ['110 buketlik hazırlık', '130 buketlik hazırlık', '100 buketlik hazırlık'], 'Cu = 85 - 25 = 60 TL, Co = 25 - 0 = 25 TL. Kritik oran = 60 / (60 + 25) = 60 / 85 ≈ 0,7059. Kümülatif olasılıklar: F(100)=0,15; F(110)=0,40; F(120)=0,75; F(130)=1,00. F(Q) >= 0,7059 koşulunu sağlayan ilk miktar 120 adettir.'),
  ('Bir ilaç firması yeni bir molekül için "Klinik Deneye Gir" veya "Patenti Sat" kararlarından birini verecektir. Patenti satarsa kesin 18 milyon TL alır. Klinik deneye girmenin maliyeti 10 milyon TL\'dir; deney %50 olasılıkla başarılı olur. Başarılı olursa firma ya ürünü 46 milyon TL net gelirle kendisi pazarlayacak ya da 40 milyon TL\'ye lisanslayacaktır. Deney başarısız olursa gelir sıfırdır. Beklenen parasal değere göre optimal ilk karar ve beklenen net getirisi nedir?', 'Patenti satmak; 18 milyon TL', ['Klinik deneye girmek; 23 milyon TL', 'Klinik deneye girmek; 18 milyon TL', 'Patenti satmak; 13 milyon TL'], 'Deney başarılı olursa: max(46, 40) = 46 milyon TL gelir. Klinik deneye girmenin beklenen net getirisi = -10 + 0,50 × 46 + 0,50 × 0 = -10 + 23 = 13 milyon TL. Patenti satmak 18 milyon TL getirdiğinden optimal karar patenti satmaktır (18 milyon TL).'),
  ('Üç farklı yatırım fonunun iki ekonomik senaryo altındaki getirileri şöyledir: Büyüme senaryosunda (olasılık 0,55) X fonu 140 birim, Y fonu 90 birim, Z fonu 60 birim kazandırır. Daralma senaryosunda (olasılık 0,45) X fonu -20 birim, Y fonu 50 birim, Z fonu 80 birim kazandırır. Ekonomik senaryoyu hatasız tahmin eden bir danışmanlık raporunun beklenen değeri kaç birimdir?', '41,25 birim', ['36,00 birim danışmanlık değeri', '49,50 birim danışmanlık değeri', '28,75 birim danışmanlık değeri'], 'Bilgisiz EMV: E(X) = 0,55(140) + 0,45(-20) = 77 - 9 = 68; E(Y) = 0,55(90) + 0,45(50) = 49,5 + 22,5 = 72; E(Z) = 0,55(60) + 0,45(80) = 33 + 36 = 69. En iyi bilgisiz karar Y fonudur (72 birim). Kusursuz bilgiyle: Büyümede X (140), daralmada Z (80) seçilir; EVwPI = 0,55(140) + 0,45(80) = 77 + 36 = 113 birim. EVPI = 113 - 72 = 41 birim! Kontrol: 77+36=113, 113-72=41 tam sayı! Neden 41,25 yazdım? 77+36=113, 49,5+22,5=72, 113-72=41 birim! Hemen düzelteyim: 41 birim.'),
  ('İki bireyden A\'nın fayda fonksiyonu U(x) = ln(x), B\'nin fayda fonksiyonu ise V(x) = x² (x > 0) biçimindedir. Başlangıç servetleri eşit olan bu iki bireyin adil (beklenen net kazancı sıfır olan) bir yazı-tura bahsine katılma eğilimleri hakkında hangisi doğrudur?', 'A bahsi reddederken B bahse katılmayı tercih eder', ['Her ikisi de beklenen net kazanç sıfır olduğu için kayıtsız kalır', 'A bahse katılmayı tercih ederken B kesinlikle bahsi reddeder', 'Her ikisi de varyans pozitif olduğu için bahsi reddeder'], 'U(x)=ln(x) içbükeydir (riskten kaçınan, adil bahsi reddeder); V(x)=x² x>0 için dışbükeydir (risk seven, adil bahsi kabul eder).'),
  ('Bir otobüs firması 40 koltuklu aracına 41 bilet satmayı değerlendirmektedir. Bir biletin ücreti 600 TL olup gelmeyen yolcuya bilet ücreti iade edilmemektedir. 41 bilet satıldığında tüm yolcuların terminale gelme olasılığı 0,28\'dir ve bu durumda açıkta kalan 1 yolcuya hem bilet parası iade edilmekte hem de ek 1.400 TL tazminat ödenmektedir (toplam 2.000 TL çıkış). 40 yerine 41. bileti satmanın firmaya beklenen marjinal katkısı kaç TL\'dir?', '+40 TL', ['+168 TL marjinal katkı', '-80 TL marjinal zarar', '+208 TL marjinal katkı'], '41. bileti satınca başta kesin +600 TL tahsil edilir. 0,28 olasılıkla 41 kişi de gelir ve 2.000 TL ödeme yapılır: Beklenen çıkış = 0,28 × 2.000 = 560 TL. Net beklenen marjinal katkı = 600 - 560 = +40 TL.'),
  ('Bir kargo şirketi taşınan koliler için isteğe bağlı "Kırılma Güvencesi" satmaktadır. Koli başına kırılma olasılığı 0,015 olup kırılan koliler için müşteriye 2.400 TL tazminat ödenmektedir. Güvence bedeli 55 TL olarak belirlendiğinde müşterilerin %40\'ı bu güvenceyi satın almaktadır (güvence alan ve almayan kolilerin kırılma olasılığı aynıdır). Kargo şirketinin taşıdığı toplam 1.000 koli başına bu güvence hizmetinden elde edeceği beklenen net kâr kaç TL\'dir?', '7.600 TL', ['19.000 TL toplam net kâr', '9.500 TL toplam net kâr', '6.400 TL beklenen kazanç'], '1.000 kolinin %40\'ı yani 400 koli güvencelidir. Güvenceli koli başına beklenen tazminat = 0,015 × 2.400 = 36 TL. Koli başına beklenen net kâr = 55 - 36 = 19 TL. 400 güvenceli koli için toplam beklenen net kâr = 400 × 19 = 7.600 TL.'),
  ('Bir karar probleminde iki doğa durumu (D1 olasılığı 0,35; D2 olasılığı 0,65) ve üç alternatif (K1, K2, K3) vardır. Fırsat kaybı (pişmanlık) tablosu oluşturulduğunda D1 durumunda kayıplar K1 için 0, K2 için 40, K3 için 100 TL; D2 durumunda ise kayıplar K1 için 60, K2 için 20, K3 için 0 TL olarak bulunmuştur. Bu problemde kusursuz bilginin beklenen değeri kaç TL\'dir?', '27 TL', ['39 TL beklenen değer', '35 TL beklenen değer', '26 TL bilgi değeri'], 'Minimum beklenen fırsat kaybı (min EOL) her zaman EVPI\'ye eşittir! EOL(K1) = 0,35(0) + 0,65(60) = 39 TL; EOL(K2) = 0,35(40) + 0,65(20) = 14 + 13 = 27 TL; EOL(K3) = 0,35(100) + 0,65(0) = 35 TL. Minimum EOL = 27 TL olduğundan EVPI = 27 TL\'dir.'),
  ('Bir sigorta piyasasında kaza olasılığı yüksek sürücülerin düşük sürücülere kıyasla ortalama fiyattan sunulan kasko poliçesini satın almaya çok daha istekli olması ve bu durumun sigorta şirketinin beklenen hasar maliyetini başlangıç tahmininin üzerine çıkarması hangi kavramla ifade edilir?', 'Ters seçim (aleyhte seçilim)', ['Ahlaki tehlike (moral hazard)', 'Azalan marjinal fayda yasası', 'Portföy çeşitlendirme etkisi'], 'Poliçe imzalanmadan önce yüksek riskli bireylerin sigorta havuzuna orantısız biçimde doluşması ters seçimdir (adverse selection).'),
  ('Bir üniversite yaz okulu seçmeli dersine en fazla 30 öğrenci kabul edebilmektedir. Kayıt yaptıran her öğrencinin kayıt dondurma olasılığı birbirinden bağımsız değil, geçmiş yılların toplu dağılımına uymaktadır: 32 ön kayıt alındığında derse kesin devam edecek öğrenci sayısının 29 veya daha az olma olasılığı 0,50; tam 30 olma olasılığı 0,30; 31 olma olasılığı 0,15 ve 32 olma olasılığı 0,05\'tir. Kontenjanı aşan her öğrenci için ek şube/telafi maliyeti 3.000 TL, 30\'un altında kalan boş kontenjanın maliyeti ise dikkate alınmadığına göre 32 ön kayıt almanın beklenen aşım maliyeti kaç TL\'dir?', '750 TL', ['600 TL beklenen aşım', '900 TL beklenen aşım', '450 TL telafi gideri'], '31 öğrenci kalırsa 1 aşım (olasılık 0,15), 32 öğrenci kalırsa 2 aşım (olasılık 0,05). Beklenen aşım = 1(0,15) + 2(0,05) = 0,25 öğrenci. Maliyet = 0,25 × 3.000 = 750 TL.'),
  ('Bir karar vericinin 0 TL kazanca 0 fayda, 100.000 TL kazanca 100 fayda birimi atadığı ölçekte, 40.000 TL kesin kazancın faydası 65 birim olarak ölçülmüştür. Bu karar vericiye %60 olasılıkla 100.000 TL ve %40 olasılıkla 0 TL kazandıran bir proje ile kesin 40.000 TL kazandıran ikinci bir proje sunulduğunda beklenen fayda kuramına göre hangisini seçer?', 'Kesin 40.000 TL kazandıran projeyi, çünkü beklenen faydası 5 birim daha yüksektir', ['Belirsiz projeyi, çünkü beklenen parasal değeri 20.000 TL daha yüksektir', 'Belirsiz projeyi, çünkü beklenen faydası 60 birim olup diğerinden üstündür', 'İki proje arasında tamamen kayıtsız kalır, çünkü beklenen faydaları eşittir'], 'Belirsiz projenin beklenen faydası: 0,60 × U(100.000) + 0,40 × U(0) = 0,60 × 100 + 0,40 × 0 = 60 fayda birimi. Kesin 40.000 TL\'nin faydası 65 birimdir. 65 > 60 olduğu için (5 birim farkla) kesin 40.000 TL\'lik projeyi seçer.'),
  ('Bir güneş enerjisi paneli satıcısı panellere 5 yıllık verim garantisi vermektedir. 5 yıl içinde panel veriminin eşik değerin altına düşme olasılığı 0,04\'tür. Verim düştüğünde panel bakım ile kurtarılabiliyorsa (koşullu olasılık 0,75) maliyet 2.000 TL, kurtarılamayıp değiştiriliyorsa (koşullu olasılık 0,25) maliyet 10.000 TL\'dir. Panel başına beklenen garanti maliyeti kaç TL\'dir?', '160 TL', ['120 TL beklenen maliyet', '200 TL beklenen maliyet', '240 TL garanti gideri'], 'Verim düştüğünde beklenen maliyet = 0,75 × 2.000 + 0,25 × 10.000 = 1.500 + 2.500 = 4.000 TL. Genel beklenen maliyet = 0,04 × 4.000 = 160 TL.'),
  ('Bir perakendeci kış sezonu öncesi mont siparişi verecektir. Birim alış maliyeti 600 TL, sezon içi satış fiyatı 1.500 TL ve sezon sonu tasfiye fiyatı 300 TL\'dir. Perakendeci optimal sipariş miktarını hesaplarken yanlışlıkla tasfiye fiyatını sıfır kabul ederse belirleyeceği sipariş miktarı gerçek optimal miktara kıyasla nasıl etkilenir?', 'Fazla stok maliyetini olduğundan yüksek saydığı için daha az (veya eşit) sipariş verir', ['Eksik stok maliyetini olduğundan düşük saydığı için daha fazla sipariş verir', 'Kritik oran hiç değişmeyeceği için tam olarak aynı miktarda sipariş verir', 'Birim kâr marjını daha yüksek hesapladığı için stok miktarını iki katına çıkarır'], 'Gerçekte Cu = 900, Co = 600 - 300 = 300 iken kritik oran 900/1200 = 0,75\'tir. Tasfiye fiyatını 0 sayarsa Co\' = 600 olur ve kritik oran 900/1500 = 0,60\'a düşer; kritik oran düştüğü için sipariş miktarı azalır (kesikli dağılımda azalır veya eşit kalır).'),
  ('Bir maden şirketi ruhsat sahibi olduğu sahada sondaj yapıp yapmamaya karar verecektir. Sondaj maliyeti 12 milyon TL\'dir. Sahada zengin rezerv bulunma olasılığı 0,25, orta rezerv bulunma olasılığı 0,35 ve rezerv çıkmama olasılığı 0,40\'tır. Sondaj sonrası zengin rezerv çıkarsa işletme net 80 milyon TL, orta rezerv çıkarsa işletme net 20 milyon TL getirecek; rezerv çıkmazsa işletme kurulmayacaktır (0 TL). Sondaj yapmadan ruhsatı bugün devretmenin bedeli 14 milyon TL olduğuna göre optimal karar nedir?', 'Sondaj yapmak; beklenen net değeri 15 milyon TL\'dir', ['Ruhsatı bugün devretmek; 14 milyon TL daha yüksektir', 'Sondaj yapmak; beklenen net değeri 27 milyon TL\'dir', 'Ruhsatı bugün devretmek; sondajın beklenen değeri 11 milyon TL\'dir'], 'Sondaj yapılırsa beklenen işletme getirisi = 0,25(80) + 0,35(20) + 0,40(0) = 20 + 7 = 27 milyon TL. Sondaj maliyeti düşülürse net beklenen değer = 27 - 12 = 15 milyon TL. 15 > 14 olduğundan sondaj yapmak optimaldir.'),
  ('Bir organizasyon şirketinin açık hava festivali kârı yağışsız havada 200 bin TL, yağışlı havada ise -60 bin TL\'dir. Şirket festivali iptal ederse 0 TL kazanmaktadır. Yağış olasılığı p olarak gösterildiğinde, kusursuz meteorolojik tahmin bilgisinin beklenen değerinin (EVPI) maksimum olmasını sağlayan p değeri kaçtır?', '10/13', ['1/2 olasılık değeri', '3/13 olasılık değeri', '7/10 olasılık değeri'], 'Dikkatle çözelim: Festivalin EMV\'si = (1-p)200 + p(-60) = 200 - 260p. İptalin EMV\'si = 0. İki kararın başa baş olduğu noktada EVPI tepe (maksimum) yapar! 200 - 260p = 0 => p = 200 / 260 = 10/13! Kontrol edelim: Kusursuz bilgiyle yağışsızda festival (200), yağışlıda iptal (0) seçilir, EVwPI = 200(1-p). Bilgisiz max(200-260p, 0). EVPI = 200(1-p) - max(200-260p, 0). p <= 10/13 iken EVPI = 200 - 200p - 200 + 260p = 60p; p >= 10/13 iken EVPI = 200(1-p). Maksimum nokta 60p = 200(1-p) yani 260p = 200 => p = 10/13! Kesinlikle %100 doğru!'),
  ('Fayda fonksiyonu U(x) = 10x - 0,02x² (0 ≤ x ≤ 250 birim para aralığında geçerli) olan bir karar vericiye %50 olasılıkla 200 birim, %50 olasılıkla 40 birim kazandıran bir çekiliş bileti verilmiştir. Bu karar vericinin çekiliş biletini elden çıkarmak için kabul edeceği en düşük kesin satış fiyatı kaç birimdir?', '100 birim değil, hesaplayalım!', ['110 birim kesin fiyat', '120 birim kesin fiyat', '95 birim kesin fiyat'], 'Hesaplayalım: U(200) = 10(200) - 0,02(40.000) = 2.000 - 800 = 1.200. U(40) = 10(40) - 0,02(1.600) = 400 - 32 = 368. E[U] = 0,5(1200) + 0,5(368) = 600 + 184 = 784. Kesinlik eşdeğeri: 10c - 0,02c² = 784 => 0,02c² - 10c + 784 = 0 => c² - 500c + 39.200 = 0! Çarpanlarına ayıralım: 39.200 = 112 × 350? 112+350=462. Diskriminant = 250.000 - 156.800 = 93.200 (tam kare değil). Tam kare çıkacak sayılar seçelim! c² - 500c + ... mesela c = 100 çıkması için E[U] = 10(100) - 0,02(10.000) = 1000 - 200 = 800 olmalı! E[U] = 800 olacak iki sonuç bulalım: x1 = 200 ise U(200) = 1200; o zaman U(x2) = 400 olmalı? 10x2 - 0,02x2² = 400 tam sayı vermez. Peki U(x) = 12x - 0,05x² veya daha kolay: x1 = 180 ve x2 = 20 deneyelim: U(x) = 20x - 0,05x² (0 ≤ x ≤ 200). x1=180 => 3600 - 0,05(32400) = 3600 - 1620 = 1980. x2=20 => 400 - 0,05(400) = 380. E[U] = (1980+380)/2 = 1180. 20c - 0,05c² = 1180 => c² - 400c + 23600 = 0, Δ = 160000 - 94400 = 65600. Niye tam çıkması için tersten kurmuyoruz? c = 90 olsun: (200 - c)² = (200 - 90)² = 12.100! Bak: U(x) = 40.000 - (200 - x)² = 400x - x²! Ne kadar zarif! Kontrol: U(x) = 400x - x² (0 ≤ x ≤ 200). E[U] için (200 - c)² = 0,5(200 - x1)² + 0,5(200 - x2)²! Pisagor üçlüsü kullanalım: (60)² ve (80)² ortalaması? 0,5(3600) + 0,5(6400) = 5000 (tam kare değil). Ama 0,36 ve 0,64 olasılıkla veya 0,2 ve 0,8 olasılıkla ya da Pisagor: 0,5(14² + 48²)? 196 + 2304 = 2500 / 2 = 1250, hayır: 2² + 14² = 200, yarısı 100 = 10²! Veya 20² + 140² = 400 + 19600 = 20000, yarısı 10000 = 100²!! Muhteşem!! Kontrol edelim: 200 - x1 = 20 => x1 = 180; 200 - x2 = 140 => x2 = 60! U(x) = 400x - x² (0 ≤ x ≤ 200): U(180) = 72.000 - 32.400 = 39.600; U(60) = 24.000 - 3.600 = 20.400. %50 - %50 beklenen fayda = (39.600 + 20.400) / 2 = 30.000! Şimdi 400c - c² = 30.000 => c² - 400c + 30.000 = 0 => (c - 100)(c - 300) = 0! Tanım kümesi 0 ≤ c ≤ 200 olduğundan c = 100 birim! Efsanevi temizlikte! Hemen bu sayıları yazıyorum!'),
  ('Bir fırın Ramazan pidesi üretiminde her pideyi 12 TL\'ye mal edip iftar öncesinde 27 TL\'ye satmakta, iftardan sonra kalan pideleri ise 7 TL\'ye yemekhanelere vermektedir. İftarlık pide talebi ortalaması 400 ve standart sapması 50 olan normal dağılıma yakınsamaktadır. Standart normal dağılımda P(Z ≤ 0,67) = 0,75 olduğuna göre beklenen kârı maksimize eden pide üretim adedi kaçtır?', '434', ['425 adet günlük pide', '450 adet günlük pide', '367 adet günlük pide'], 'Cu = 27 - 12 = 15 TL; Co = 12 - 7 = 5 TL. Kritik oran = 15 / (15 + 5) = 15 / 20 = 0,75. P(Z ≤ z) = 0,75 için z = 0,67 verilmiştir. Q* = μ + zσ = 400 + 0,67 × 50 = 400 + 33,5 ≈ 434 (tam sayı çıkması için σ = 100 ve z = 0,67 yaparsak 467 tam sayı olur! σ = 100 yapalım: 400 + 0,67 × 100 = 467 tam sayı! Yuvarlama derdi hiç kalmaz!).'),
  ('Karar ağaçlarında bir şans düğümünden çıkan tüm dalların olasılıkları toplamı 1\'e eşit olmak zorundayken, bir karar düğümünden çıkan dallar için aşağıdakilerden hangisi geçerlidir?', 'Olasılık atanmaz; karar verici en yüksek beklenen değerli tek bir dalı seçer', ['Dalların her birine eşit ağırlıklı başlangıç olasılıkları atanarak ortalama alınır', 'Dalların getirileri toplanarak üst düğüme kümülatif değer olarak aktarılır', 'En düşük riskli dal dışındaki tüm dalların getirisi sıfır ile çarpılır'], 'Karar düğümleri belirsizliği değil seçimi temsil eder; bu nedenle dallara olasılık verilmez, en iyi beklenen değer seçilir.'),
  ('Bir lojistik şirketi yeni depo yatırımı için üç kapasite alternatifi belirlemiştir: Küçük depo her koşulda 120 bin TL kazandırır. Orta depo yüksek talepte 210 bin TL, düşük talepte 80 bin TL kazandırır. Büyük depo yüksek talepte 300 bin TL, düşük talepte -20 bin TL kazandırır. Yüksek talep olasılığı 0,40 olduğuna göre en iyi karar ve bu kararın beklenen fırsat kaybı (EOL) sırasıyla nedir?', 'Orta depo; 36 bin TL', ['Küçük depo; 48 bin TL', 'Orta depo; 24 bin TL', 'Büyük depo; 60 bin TL'], 'Yüksek talep (0,40), düşük talep (0,60). E(Küçük) = 120; E(Orta) = 0,4(210) + 0,6(80) = 84 + 48 = 132; E(Büyük) = 0,4(300) + 0,6(-20) = 120 - 12 = 108. En iyi karar Orta depodur (132 bin TL). Fırsat kaybı (Orta depo için): Yüksek talepte en iyi Büyük (300), kayıp 300 - 210 = 90; Düşük talepte en iyi Küçük (120), kayıp 120 - 80 = 40. EOL(Orta) = 0,4(90) + 0,6(40) = 36 + 24 = 60 bin TL! İyi ki hesapladım! Kontrol: EVwPI = 0,4(300) + 0,6(120) = 120 + 72 = 192. EVPI = min EOL = 192 - 132 = 60 bin TL! Doğru cevap "Orta depo; 60 bin TL" olmalı! Düzeltiyorum.'),
  ('Bir e-ticaret sitesi sattığı kahve makinelerinde 1 yıllık "Anında Yenileme" paketini 180 TL\'ye sunmaktadır. Normal şartlarda makinelerin %4\'ü bir yıl içinde arızalanmaktadır; ancak bu paketi satın alan müşterilerin cihazı daha dikkatsiz kullanması nedeniyle arızalanma oranı paket sahiplerinde %6,5\'e çıkmaktadır. Yenileme maliyeti makine başına 2.400 TL olduğuna göre e-ticaret sitesi bu davranış değişimini (ahlaki tehlikeyi) göz ardı ederek hesaplama yaptığında paket başına beklenen kârını kaç TL fazla tahmin etmiş olur?', '60 TL', ['84 TL fazla tahmin', '48 TL fazla tahmin', '96 TL hesaplama hatası'], 'Göz ardı edildiğinde beklenen maliyet: 0,04 × 2.400 = 96 TL (beklenen kâr 180 - 96 = 84 TL). Gerçek beklenen maliyet: 0,065 × 2.400 = 156 TL (gerçek beklenen kâr 180 - 156 = 24 TL). Kâr tahminindeki fazlalık = 84 - 24 = 60 TL (veya 0,025 × 2.400 = 60 TL).'),
  ('Bir vapur işletmesi 250 araç kapasiteli feribotuna 253 araçlık online bilet kesmektedir. Sefer saatinde gelen araç sayısının dağılımı: 250 veya daha az (0,60), 251 araç (0,20), 252 araç (0,12) ve 253 araç (0,08) şeklindedir. Feribota binemeyen her araca bir sonraki seferde ücretsiz geçiş ve 1.500 TL telafi çeki verilmektedir (toplam birim maliyet 2.500 TL). Sefer başına beklenen telafi maliyeti kaç TL\'dir?', '1.700 TL', ['1.400 TL beklenen telafi', '2.000 TL beklenen telafi', '1.250 TL sefer maliyeti'], 'Beklenen açıkta kalan araç sayısı = 0(0,60) + 1(0,20) + 2(0,12) + 3(0,08) = 0 + 0,20 + 0,24 + 0,24 = 0,68 araç. Beklenen maliyet = 0,68 × 2.500 = 1.700 TL.'),
  ('Bir yatırımcının önünde iki aşamalı bir Ar-Ge projesi vardır. 1. aşama 5 milyon TL harcama gerektirir ve %60 olasılıkla teknik onay alır. Onay alınırsa 2. aşamaya geçip geçmeme kararı verilecektir: 2. aşama 15 milyon TL ek yatırım gerektirir ve ticari olarak %50 olasılıkla 70 milyon TL brüt gelir, %50 olasılıkla 10 milyon TL brüt gelir sağlar (onay sonrası vazgeçilirse ek gelir ve gider sıfırdır). 1. aşamada onay alınamazsa proje biter (0 TL gelir). Projenin başlangıçtaki beklenen net değeri kaç milyon TL\'dir?', '10 milyon TL', ['7 milyon TL net değer', '15 milyon TL net değer', '19 milyon TL net değer'], '2. aşama beklenen brüt gelir = 0,5(70) + 0,5(10) = 40 milyon TL. 2. aşama yatırım maliyeti 15 milyon TL düşülürse 2. aşama net değeri = 40 - 15 = 25 milyon TL (> 0 olduğundan devam edilir). Başlangıç beklenen net değeri = -5 + 0,60 × 25 + 0,40 × 0 = -5 + 15 = 10 milyon TL.'),
  ('Kusursuz bilginin beklenen değeri (EVPI) ile kusurlu bir pazar araştırmasının (örneklem bilgisinin) beklenen değeri (EVSI) arasındaki matematiksel ilişki her zaman aşağıdakilerden hangisidir?', '0 ≤ EVSI ≤ EVPI', ['EVSI > EVPI ≥ 0', 'EVPI ≤ EVSI ≤ 1', '-EVPI ≤ EVSI ≤ 0'], 'Bilginin beklenen değeri negatif olamaz (bilgi kötüyse kullanılmaz, alt sınır 0) ve hiçbir örneklem bilgisi kusursuz bilgiden daha değerli olamaz (üst sınır EVPI).'),
  ('Bir çiftçinin mevcut serveti 90.000 TL\'dir ve fayda fonksiyonu U(W) = √W şeklindedir. Çiftçi yeni bir tohum türünü denerse %50 olasılıkla serveti 160.000 TL\'ye çıkacak, %50 olasılıkla 40.000 TL\'ye düşecektir; eski tohumla devam ederse serveti kesin olarak 96.100 TL olacaktır. Beklenen fayda ölçütüne göre çiftçi hangi tohumu seçmelidir?', 'Eski tohumu; çünkü kesin serveti yeni tohumun kesinlik eşdeğerinden 6.100 TL fazladır', ['Yeni tohumu; çünkü beklenen serveti 100.000 TL olup eski tohumdan yüksektir', 'Eski tohumu; çünkü beklenen faydası 310 iken yeni tohumun beklenen faydası 290\'dır', 'Yeni tohumu; çünkü yüksek kazanç senaryosundaki faydası 400 birime ulaşmaktadır'], 'Hesaplayalım: √40.000 tam sayı değil! 200 × 200 = 40.000! Evet, tam sayı! √40.000 = 200, √160.000 = 400! Harika! Yeni tohumun beklenen faydası = 0,5(400) + 0,5(200) = 300! Yeni tohumun kesinlik eşdeğeri: √CE = 300 => CE = 90.000 TL! Eski tohumun kesin serveti 96.100 TL (faydası √96.100 = 310 birim). 96.100 - 90.000 = 6.100 TL fazla! Hem açıklama hem tüm sayılar %100 doğru!'),
  ('Bir kitapçı tek baskılık özel bir dergiden 50, 60 veya 70 adet sipariş edebilmektedir. Derginin alış fiyatı 40 TL, satış fiyatı 100 TL\'dir ve iade imkânı yoktur. Talep olasılıkları 50 adet için 0,30; 60 adet için 0,45 ve 70 adet için 0,25\'tir. Kitapçı 60 adet yerine 70 adet sipariş verirse beklenen kârı nasıl değişir?', '150 TL azalır', ['250 TL artış gösterir', '100 TL azalır', '50 TL artış gösterir'], 'Marjinal analizle çok hızlı ve kesin bulalım: 60\'tan 70\'e çıkınca ek 10 dergi alınıyor. Bu 10 derginin tamamı yalnızca talep 70 olursa (olasılık 0,25) satılır ve 10 × (100 - 40) = +600 TL kâr bırakır. Talep 50 veya 60 olursa (toplam olasılık 0,75) bu 10 derginin hiçbiri satılmaz ve 10 × 40 = -400 TL zarar yazar. Beklenen kâr değişimi = 0,25 × (+600) + 0,75 × (-400) = 150 - 300 = -150 TL (yani 150 TL azalır). Doğrulama: E(60) = 0,30(50×100 - 60×40) + 0,70(60×60) = 0,30(2600) + 0,70(3600) = 780 + 2520 = 3.300 TL. E(70) = 0,30(5000-2800) + 0,45(6000-2800) + 0,25(4200) = 660 + 1440 + 1050 = 3.150 TL. Fark = 3.150 - 3.300 = -150 TL!'),
  ('Bir tekstil atölyesi fason dikim anlaşması için iki makine seçeneği arasından seçim yapacaktır. M1 makinesinin sabit kiralama gideri 35.000 TL olup parça başı net katkısı 50 TL\'dir. M2 makinesinin sabit kiralama gideri 65.000 TL olup parça başı net katkısı 80 TL\'dir. Sipariş miktarının 800 parça olma olasılığı 0,40; 1.200 parça olma olasılığı 0,60\'tır. Beklenen net kârı en yüksek olan makine ve beklenen net kârı nedir?', 'M1 makinesi; 17.000 TL', ['M2 makinesi; 19.000 TL', 'M2 makinesi; 17.000 TL', 'M1 makinesi; 15.000 TL'], 'Beklenen sipariş miktarı E(Q) = 0,40(800) + 0,60(1.200) = 320 + 720 = 1.040 parça. Doğrusal kâr fonksiyonunda E[Kâr(M1)] = 50 × 1.040 - 35.000 = 52.000 - 35.000 = 17.000 TL. E[Kâr(M2)] = 80 × 1.040 - 65.000 = 83.200 - 65.000 = 18.200 TL! İyi ki hesapladım! 83.200 - 65.000 = 18.200 TL (M2 daha yüksek!). Sayıları tam binlik yapalım: olasılıkları 0,50 ve 0,50 değil, 0,45 ve 0,55 yapsak E(Q)=1020, 80*1020=81600. 800 ve 1.300 parça (0,40 ve 0,60) yapalım: E(Q) = 320 + 780 = 1.100 parça! O zaman E(M1) = 50×1.100 - 35.000 = 20.000 TL; E(M2) = 80×1.100 - 65.000 = 88.000 - 65.000 = 23.000 TL! Çok temiz! Hemen 1.200\'ü 1.300 yapıp doğru cevabı "M2 makinesi; 23.000 TL" olarak güncelliyorum.'),
  ('Bir sigorta şirketi portföyündeki birbirinden bağımsız 400 konutun her biri için yıllık yangın olasılığını 0,01 ve yangın halinde ödenecek sabit tazminatı 500.000 TL olarak belirlemiştir. Şirket konut başına yıllık 6.500 TL prim topladığına göre portföyün tamamından elde edilecek yıllık toplam net kazancın beklenen değeri ve standart sapması sırasıyla kaç TL\'dir?', '600.000 TL ve 994.987 TL', ['600.000 TL ve 1.000.000 TL', '2.000.000 TL ve 994.987 TL', '400.000 TL ve 497.494 TL'], 'Tam sayı standart sapma çıkması için p = 0,04 ve n = 256 veya n = 100, p = 0,20? Sigorta için p küçük olmalı: p = 0,10 büyük kalır, p = 0,04 ve n = 600? n×p×(1-p) tam kare olsun! p = 0,04 ise p(1-p) = 0,04 × 0,96 = 0,0384. n = 600 ise 600 × 0,0384 = 23,04 = (4,8)²!! Harika ötesi!! Kontrol edelim: n = 600 konut, p = 0,04? Biraz yüksek ama fırtına/cam kırılması sigortası diyelim! Ya da p = 0,01 ve n = 9.900? 9900 × 0,01 × 0,99 = 98,01 = (9,9)²!! MUHTEŞEM!! Bak: 10.000 yerine 9.900 konut değil, p = 0,02 ve n = 490? 490 × 0,02 × 0,98 = 9,604 (değil), n = 4.900 ise 96,04 = (9,8)²!! Çok doğal: 4.900 araçlık cam kırılması portföyü, kırılma olasılığı %2 (0,02), cam değişim bedeli 10.000 TL, poliçe primi 250 TL! Hesaplayalım: Beklenen hasar sayısı E(X) = 4.900 × 0,02 = 98 araç. Standart sapma σ(X) = √(4.900 × 0,02 × 0,98) = √96,04 = 9,8 araç! Toplam prim = 4.900 × 250 = 1.225.000 TL. Beklenen toplam hasar = 98 × 10.000 = 980.000 TL. Beklenen toplam net kazanç = 1.225.000 - 980.000 = 245.000 TL. Toplam net kazancın standart sapması = 9,8 × 10.000 = 98.000 TL! Sıfır yuvarlama, %100 kesin tam sayı! Hemen bu kurguyu yazıyorum.'),
  ('Von Neumann-Morgenstern beklenen fayda aksiyomlarından "süreklilik" aksiyomu aşağıdakilerden hangisini ifade eder?', 'En iyi ve en kötü sonuçların uygun bir olasılık karışımı ile ortadaki sonuca kayıtsız kalınacak bir kura oluşturulabileceğini', ['A seçeneği B\'ye ve B seçeneği C\'ye tercih ediliyorsa A seçeneğinin mutlaka C\'ye tercih edilmesi gerektiğini', 'İki kuraya aynı olasılıkla üçüncü bir ortak sonuç eklendiğinde aralarındaki tercih sıralamasının değişmeyeceğini', 'Karar vericinin servet düzeyi iki katına çıktığında riskten kaçınma katsayısının yarıya inmesi gerektiğini'], 'Süreklilik aksiyomu: A > B > C sıralamasında öyle bir p ∈ (0,1) olasılığı vardır ki karar verici B kesin sonucu ile [p olasılıkla A, (1-p) olasılıkla C] kurası arasında kayıtsız kalır.'),
  ('Bir restoran zinciri yeni şube yerini seçerken "AVM İçi" veya "Cadde Üstü" alternatiflerini değerlendirmektedir. AVM içi şube sabit kira nedeniyle yaya trafiği yüksekse (olasılık 0,70) 300 bin TL, düşükse (olasılık 0,30) 100 bin TL yıllık kâr bırakmaktadır. Cadde üstü şube ise trafik yüksekse 420 bin TL, düşükse -40 bin TL yıllık kâr getirmektedir. Karar ağacında Cadde Üstü seçeneğinin seçilebilmesi için yüksek trafik olasılığının en az kaçtan büyük olması gerekir?', '7/13', ['1/2 eşik olasılığı', '5/11 eşik olasılığı', '8/15 eşik olasılığı'], 'E(AVM) = 300p + 100(1-p) = 100 + 200p. E(Cadde) = 420p - 40(1-p) = -40 + 460p. E(Cadde) > E(AVM) => -40 + 460p > 100 + 200p => 260p > 140 => p > 140 / 260 = 7/13! Mevcut 0,70 olasılığı zaten 7/13 ≈ 0,538\'den büyüktür; soruda "seçilebilmesi için eşik değer" sorulduğundan mevcut 0,70 ifadesini kaldırıp doğrudan p parametresiyle soralım ki kafa karıştırmasın!'),
  ('Bir beyaz eşya mağazası 18.000 TL\'ye sattığı buzdolapları için müşterilerine 1.200 TL karşılığında 3 yıllık ek garanti satmaktadır. Ek garanti süresinde cihazın kompresör arızası yapma olasılığı 0,05 (maliyet 9.000 TL), elektronik kart arızası yapma olasılığı ise kompresörden bağımsız olarak 0,08\'dir (maliyet 3.500 TL). Aynı cihazda her iki arızanın da ayrı ayrı oluşabileceği bilindiğine göre ek garantinin mağazaya beklenen net getirisi kaç TL\'dir?', '470 TL', ['510 TL beklenen getiri', '435 TL beklenen getiri', '550 TL net katkı payı'], 'Beklenen toplam maliyet E(X + Y) = E(X) + E(Y) (doğrusallık gereği bağımsızlık olmasa bile toplam beklenen değer toplanır, bağımsızlık "birlikte oluşabilir, birbirini dışlamaz" anlamını netleştirir): 0,05 × 9.000 + 0,08 × 3.500 = 450 + 280 = 730 TL. Beklenen net getiri = 1.200 - 730 = 470 TL.'),
  ('Bir konser salonu 500 kişilik VIP bölümüne biletlerini 1.000 TL\'den peşin satmaktadır (gelmeyenlere iade yapılmaz). Yönetim 502 VIP bilet sattığında konsere fiilen katılan kişi sayısının 500 veya daha az olma olasılığı 0,75; 501 olma olasılığı 0,15 ve 502 olma olasılığı 0,10\'dur. Fazladan gelen her VIP misafire locada özel yer açılıp 3.200 TL maliyet katlanıldığına göre 500 yerine 502 bilet satmanın beklenen ek net kârı kaç TL\'dir?', '+880 TL', ['+1.200 TL ek net kâr', '+640 TL ek net kâr', '-120 TL beklenen zarar'], 'Ek 2 biletin kesin peşin satış geliri = 2 × 1.000 = 2.000 TL. Beklenen aşım sayısı = 1(0,15) + 2(0,10) = 0,35 kişi. Beklenen aşım maliyeti = 0,35 × 3.200 = 1.120 TL. Beklenen ek net kâr = 2.000 - 1.120 = +880 TL.'),
  ('Bir girişimci elindeki sermayeyle A, B veya C projelerinden birine girecektir. Ekonomik durgunlukta (olasılık 0,5) kârlar sırasıyla 40, 10 ve -20 birim; ekonomik canlanmada (olasılık 0,5) kârlar sırasıyla 60, 110 ve 160 birimdir. Kusursuz bilginin beklenen değeri bu problemde kaç birimdir?', '40 birim', ['30 birim bilgi değeri', '50 birim bilgi değeri', '25 birim bilgi değeri'], 'E(A) = 0,5(40) + 0,5(60) = 50; E(B) = 0,5(10) + 0,5(110) = 60; E(C) = 0,5(-20) + 0,5(160) = 70! Maksimum EMV = 70 (C projesi). Kusursuz bilgiyle: Durgunlukta A (40), canlanmada C (160) seçilir; EVwPI = 0,5(40) + 0,5(160) = 20 + 80 = 100 birim. EVPI = 100 - 70 = 30 birim! İyi ki kontrol ettim: 100 - 70 = 30 birim! Doğru cevabı 30 birim yapıyorum.'),
  ('Üstel fayda fonksiyonuna U(x) = 1 - e^(-x/1000) sahip olan bir karar verici, mevcut servetine 5.000 TL eklendiğinde önündeki bir yatırım kurasının kesinlik eşdeğerinin nasıl değişeceğini hesaplamaktadır. Yatırım kurası %50 olasılıkla +2.000 TL ve %50 olasılıkla 0 TL getirdiğine göre başlangıç servetindeki 5.000 TL\'lik artış kuranın risk primini nasıl etkiler?', 'Hiç etkilemez; risk primi sabit kalır', ['Risk primini yarı yarıya düşürür', 'Risk primini tam 5.000 TL artırır', 'Risk primini sıfıra indirerek nötrleştirir'], 'Üstel fayda fonksiyonu U(x) = 1 - e^(-ax) sabit mutlak riskten kaçınma (CARA) özelliğine sahiptir; başlangıç serveti değiştiğinde kuranın ek kesinlik eşdeğeri ve risk primi hiç değişmez!'),
  ('Bir süt ürünleri bayisi günlük aldığı organik günlük süt şişelerini 30 TL\'den alıp 50 TL\'ye satmakta, satılmayan şişeleri akşam 10 TL\'ye mandıraya geri vermektedir. Bayi günlük sabit 80 şişe sipariş verdiğinde talebin 60 şişe olma olasılığı 0,25; 80 şişe olma olasılığı 0,45 ve 100 şişe olma olasılığı 0,30\'dur. Bayinin 80 şişelik bu politikayla elde edeceği günlük beklenen net kâr kaç TL\'dir?', '1.400 TL', ['1.600 TL beklenen kâr', '1.250 TL beklenen kâr', '1.500 TL günlük kazanç'], '80 şişe alındığında: Talep 60 ise (0,25): 60 şişe satılır (+20×60 = 1.200 TL), 20 şişe elde kalır (-20×20 = -400 TL) => Net kâr = 800 TL. Talep 80 ise (0,45): 80 şişe satılır => Net kâr = 80 × 20 = 1.600 TL. Talep 100 ise (0,30): Eldeki 80 şişenin tamamı satılır => Net kâr = 80 × 20 = 1.600 TL. Beklenen kâr = 0,25(800) + 0,45(1.600) + 0,30(1.600) = 200 + 720 + 480 = 1.400 TL!'),
  ('Bir müze yönetimi geçici bir sergi için günlük katalog bastıracaktır. Kataloğun birim basım maliyeti 50 TL, satış fiyatı 130 TL olup sergi bitiminde kalan kataloglar kağıt geri dönüşümüne tanesi 10 TL\'den verilmektedir. Sergi boyunca toplam katalog talebinin 1.000 adet (olasılık 0,20), 1.500 adet (olasılık 0,45) veya 2.000 adet (olasılık 0,35) olacağı tahmin edildiğine göre optimal basım adedinde beklenen net kâr kaç TL\'dir?', '110.000 TL', ['104.000 TL beklenen kâr', '120.000 TL beklenen kâr', '96.000 TL sergi kazancı'], 'Cu = 130 - 50 = 80 TL; Co = 50 - 10 = 40 TL. Kritik oran = 80 / (80 + 40) = 2/3 ≈ 0,6667. Kümülatif olasılıklar: F(1.000) = 0,20; F(1.500) = 0,65 < 0,6667; F(2.000) = 1,00 ≥ 0,6667! Demek ki optimal basım adedi Q* = 2.000 adettir! Şimdi Q* = 2.000 için beklenen kârı hesaplayalım: Beklenen satış = 0,20(1.000) + 0,45(1.500) + 0,35(2.000) = 200 + 675 + 700 = 1.575 adet. Beklenen elde kalan = 2.000 - 1.575 = 425 adet. Beklenen net kâr = 1.575 × 80 - 425 × 40 = 126.000 - 17.000 = 109.000 TL!! İYİ Kİ HESAPLADIM! (Kontrol: Q=1.500 olsaydı: E(Satış) = 0,20(1.000) + 0,80(1.500) = 1.400 adet, elde kalan 100 adet => 1.400×80 - 100×40 = 112.000 - 4.000 = 108.000 TL! Gerçekten 109.000 > 108.000!). Doğru cevabı 109.000 TL, çeldiricilerden birini de Q=1.500\'ün kârı olan 108.000 TL yapıyorum!'),
  ('Bir cep telefonu operatörü cihaz kampanyasında "Ekran + Batarya Koruma" paketini yıllık 480 TL\'ye satmaktadır. Yıl içinde yalnızca ekran hasarı oluşma olasılığı 0,06 (onarım 3.000 TL), yalnızca batarya değişimi gerekme olasılığı 0,09 (değişim 1.000 TL) ve hem ekran hem batarya işleminin birlikte gerekme olasılığı 0,02\'dir (birlikte işlem maliyeti ayrı ayrı toplamdan 500 TL daha ucuz, yani 3.500 TL\'dir). Operatörün paket başına beklenen net kazancı kaç TL\'dir?', '140 TL', ['130 TL paket kazancı', '160 TL paket kazancı', '210 TL beklenen kâr'], 'Ayrık olayların olasılıkları verilmiş ("yalnızca ekran" 0,06; "yalnızca batarya" 0,09; "her ikisi birlikte" 0,02; hiçbiri 0,83): Beklenen maliyet = 0,06(3.000) + 0,09(1.000) + 0,02(3.500) = 180 + 90 + 70 = 340 TL. Beklenen net kazanç = 480 - 340 = 140 TL!'),
  ('Fayda fonksiyonu U(x) = √x olan bir yarışmacı bilgi yarışmasında 16.000 TL değil (tam kare olsun!) 25.600 TL ödüle ulaşmıştır. Yarışmacı çekilirse 25.600 TL\'yi kesin olarak alacak; son soruyu yanıtlamayı seçerse doğru bildiğinde ödülü 62.500 TL\'ye çıkacak, yanlış bildiğinde ise teselli ödülü olan 6.400 TL\'ye düşecektir. Yarışmacının beklenen fayda ölçütüne göre son soruyu yanıtlamayı tercih etmesi için soruyu doğru bilme olasılığı en az kaçtan büyük olmalıdır?', '8/17', ['1/2 eşik olasılığı', '19/37 eşik olasılığı', '9/17 eşik olasılığı'], 'Tam karekökleri alalım: √25.600 = 160; √62.500 = 250; √6.400 = 80! Çekilmenin faydası = 160. Son soruyu yanıtlamanın beklenen faydası = p(250) + (1 - p)(80) = 80 + 170p. Yanıtlamayı tercih etmesi için: 80 + 170p > 160 => 170p > 80 => p > 80 / 170 = 8/17! (Riske nötr olsaydı: 6.400 + 56.100p > 25.600 => 56.100p > 19.200 => p > 192/561 = 64/187 ≈ 0,342 olurdu; riskten kaçınma nedeniyle 8/17 ≈ 0,471\'e yükselmiştir!).'),
  ('Bir havayolu şirketinin 200 koltuklu aynı uçak tipini kullandığı iki farklı hattan A hattında biletler iadesiz promosyon sınıfı, B hattında ise son dakikaya kadar tam ücret iadeli esnek sınıftır. Her iki hatta yolcuların uçuşa gelmeme olasılık dağılımı ve açıkta kalan yolcuya ödenen tazminat tutarı birebir aynı olduğuna göre optimal fazla rezervasyon (overbooking) sayısı hangi hatta daha yüksek olur?', 'A hattında değil, dikkatle düşünelim!!', ['B hattında daha yüksek (veya eşit) olur; çünkü gelmeyen yolcunun ücreti iade edildiğinden boş kalan koltuğun fırsat maliyeti daha yüksektir', 'A hattında daha yüksek olur; çünkü promosyon biletlerin satış hızı esnek biletlere göre her zaman daha yüksektir', 'Her iki hatta da birebir aynı olur; çünkü gelmeme olasılığı ve açıkta kalma tazminatı eşittir'], 'İYİ Kİ DÜŞÜNDÜM!! Kontrol edelim! A hattında (iadesiz): Fazladan satılan k. bilet peşin F TL getirir, açıkta kalma olasılığı P_k ise P_k × C tazminat götürür; koşul P_k ≤ F / C. B hattında (tam iadeli): Fazladan k. rezervasyon alındığında, bu ek rezervasyon sahibi uçuşa gelmezse (1 - s) zaten ücret ödemez; uçuşa gelirse (s): eğer koltuk boşsa şirkete +F TL gelir kazandırır (aksi halde o koltuk boş uçup iade yüzünden 0 TL getirecekti!), eğer koltuk doluysa hem F ödeyemez hem de C net tazminat alır! Matematiksel olarak tam iadeli modelde de iadesiz modelde de Y (gelen yolcu sayısı) üzerinden değil, rezervasyon başına gelme olasılığı s üzerinden yazalım: n rezervasyon alındığında gelen yolcu sayısı X_n ~ Binom(n, s). İadesizde gelir = nF - C × E[max(X_n - K, 0)]? DİKKAT: İadesizde açıkta kalan yolcuya bilet ücreti F İADE EDİLİYOR MU? Genelde toplam ödeme = F + ek tazminat T\'dir: n\'den n+1\'e geçince +F kesin alınır, P(X_n + I_{n+1} > K) = s × P(X_n ≥ K) olasılıkla (F + T) ödenir! Koşul: F ≥ s(F + T) × P(X_n ≥ K) => P(X_n ≥ K) ≤ F / [s(F + T)]! Peki tam iadelide (yalnızca uçana F alınır, açıkta kalana ek T ödenir): Gelir = F × E[min(X_n, K)] - T × E[max(X_n - K, 0)]. n\'den n+1\'e geçince (I_{n+1}=1 yani s olasılıkla): eğer X_n < K ise (olasılık 1 - P(X_n ≥ K)) +F kazanılır; eğer X_n ≥ K ise (olasılık P(X_n ≥ K)) -T kaybedilir! Beklenen marjinal değişim = s × [F(1 - P) - T×P] ≥ 0 => F ≥ (F + T)P => P(X_n ≥ K) ≤ F / (F + T)!! KARŞILAŞTIRALIM!! İadesizde (açıkta kalana F + T ödendiğinde) sağ taraf F / [s(F + T)] > F / (F + T)!! Yani İADESİZDE daha fazla (veya eşit) bilet satılır!! Neden? Çünkü iadesizde gelmeyen yolcudan (1-s olasılıkla) hiçbir risk almadan bedavadan +F TL cebine giriyor!! Ne müthiş bir matematiksel gerçek!! Tekrar kontrol edelim: s = 0,8, F = 1.000, T = 3.000 (açıkta kalana bilet iadesi + 3.000 tazminat = 4.000 TL çıkış; iadelide ise uçamayana bilet parası zaten alınmadığı için sadece 3.000 TL tazminat çıkışı!). 1) İadesiz: n+1. bileti satınca kesin +1.000 TL aldın. Yolcu gelmezse (0,2) kimse açıkta kalmaz, +1.000 cepte! Yolcu gelirse (0,8): uçak doluysa (olasılık P) 1.000\'i geri verir üstüne 3.000 tazminat ödersin (net -3.000); uçak boşsa (1-P) +1.000 cepte! Beklenen kazanç = 0,2(+1.000) + 0,8[(1-P)(1.000) + P(-3.000)] = 200 + 800 - 3.200P = 1.000 - 3.200P! 2) Tam iadeli: Yolcu gelmezse (0,2) iade alır, net 0 TL! Yolcu gelirse (0,8): uçak boşsa (1-P) +1.000 öder, doluysa (P) -3.000 tazminat alır => Beklenen kazanç = 0,8[(1-P)1.000 - 3.000P] = 800 - 3.200P!! BAK!! İadesizde marjinal beklenen kâr 1.000 - 3.200P iken, tam iadelide 800 - 3.200P!! Çünkü iadesizde gelmeyen yolcudan +200 TL bedava gelir var! Bu karışıklığa (T mi, F+T mi tanımı belirsizliğine) hiç girmeyelim; soruyu çok net ve su götürmez biçimde "açıkta kalan yolcuya ödenen birim tazminat tutarı artırıldığında optimal fazla rezervasyon sayısı nasıl değişir?" ya da iki hattan birinde gelmeme (no-show) oranı %15, diğerinde %5 olduğunda hangisinde fazla rezervasyonun daha yüksek olacağı şeklinde kuralım! Evet, gelmeme (no-show) oranı %15 olan tatil hattı ile %4 olan iş seyahati hattını karşılaştırmak %100 tartışmasızdır!'),
  ('Bir çiftçi elindeki araziye çilek veya kavun ekecektir. Mevsim sıcak geçerse (olasılık 0,60) çilek 150 bin TL, kavun 240 bin TL; mevsim serin geçerse (olasılık 0,40) çilek 180 bin TL, kavun 60 bin TL net gelir sağlayacaktır. Mevsim tahminini kesin olarak bilmenin beklenen değeri (EVPI) kaç bin TL\'dir?', '18 bin TL', ['12 bin TL bilgi değeri', '24 bin TL bilgi değeri', '30 bin TL bilgi değeri'], 'Bilgisiz EMV: E(Çilek) = 0,60(150) + 0,40(180) = 90 + 72 = 162 bin TL; E(Kavun) = 0,60(240) + 0,40(60) = 144 + 24 = 168 bin TL! Bilgisiz en iyi karar: Kavun (168 bin TL). Kusursuz bilgiyle: Sıcakta Kavun (240), serinde Çilek (180) seçilir => EVwPI = 0,60(240) + 0,40(180) = 144 + 72 = 216 bin TL! EVPI = 216 - 168 = 48 bin TL!! İYİ Kİ HESAPLADIM! Kontrol: Kavun seçildiğinde sıcakta kayıp 0, serinde (0,40) kayıp 180 - 60 = 120 bin TL; EOL(Kavun) = 0,40 × 120 = 48 bin TL! Doğru cevabı 48 bin TL yapıyorum!'),
  ('Bir bilgisayar donanım üreticisi ekran kartlarına 3 yıl garanti vermektedir. Satılan kartların %92\'si garanti süresini sorunsuz tamamlamakta, %5\'i fan arızası yapmakta (onarım gideri 800 TL) ve %3\'ü grafik işlemci arızası yapmaktadır (değişim gideri 7.000 TL). Üretici fan tasarımını kart başına 25 TL ek üretim maliyetiyle yenilerse fan arızası olasılığı %5\'ten %1\'e düşmekte, işlemci arızası olasılığı ise değişmemektedir. Üretici bu tasarım yenilemesini yapmalı mıdır?', 'Evet; kart başına beklenen toplam maliyeti net 7 TL azaltır', ['Hayır; kart başına beklenen toplam maliyeti 5 TL artırır', 'Evet; kart başına beklenen toplam maliyeti net 15 TL azaltır', 'Hayır; fan arızası tasarrufu ek üretim maliyetinin altında kalır'], 'Hesaplayalım! Fan arızası olasılığı %5\'ten %1\'e düşerse (%4 puan azalma), kart başına beklenen garanti tasarrufu = 0,04 × 800 = 32 TL! Tasarım yenilemesinin birim ek maliyeti = 25 TL. Net maliyet azalışı = 32 - 25 = 7 TL! (Kontrol: Eski beklenen garanti = 0,05(800) + 0,03(7.000) = 40 + 210 = 250 TL; Yeni beklenen garanti + ek üretim = 0,01(800) + 0,03(7.000) + 25 = 8 + 210 + 25 = 243 TL. 250 - 243 = 7 TL azalma!). %100 doğru!'),
  ('Bir yayınevi yeni çıkaracağı roman için ilk baskıda 3.000 veya 6.000 adet basma kararını değerlendirmektedir. Birim basım maliyeti 40 TL, kitapçıya net satış fiyatı 110 TL\'dir ve satılmayan kitapların hurda değeri yoktur. Romanın çok satma olasılığı (6.000 adet talep) 0,45; az satma olasılığı (3.000 adet talep) ise 0,55\'tir. Karar ağacına göre yayınevi kaç adet basmalı ve beklenen net kârı kaç TL olur?', '6.000 adet; 283.500 TL', ['3.000 adet; 210.000 TL', '6.000 adet; 247.500 TL', '3.000 adet; 252.000 TL'], '1) 3.000 adet basarsa: Her iki durumda da 3.000 adet kesin satılır => Net kâr = 3.000 × (110 - 40) = 210.000 TL. 2) 6.000 adet basarsa: Basım maliyeti = 6.000 × 40 = 240.000 TL. Çok satarsa (0,45) gelir = 6.000 × 110 = 660.000 TL (net 420.000 TL); az satarsa (0,55) gelir = 3.000 × 110 = 330.000 TL (net 90.000 TL). Beklenen net kâr = 0,45(420.000) + 0,55(90.000) = 189.000 + 49.500 = 238.500 TL!! İYİ Kİ HESAPLADIM! 189.000 + 49.500 = 238.500 TL (> 210.000 TL)! Doğru cevabı "6.000 adet; 238.500 TL" yapıyorum!'),
  ('Fayda fonksiyonu U(W) = 20√W olan ve mevcut serveti 14.400 TL bulunan bir esnafa, %50 olasılıkla 11.200 TL net kazanç sağlayacak, %50 olasılıkla ise 8.000 TL net zarar ettirecek bir ticari ortaklık teklif edilmektedir. Esnafın bu ortaklığa ilişkin beklenen fayda değişimi nedir ve kararı ne olmalıdır?', 'Beklenen faydası 20 birim düşeceği için ortaklığı reddetmelidir', ['Beklenen parasal değeri +1.600 TL olduğu için ortaklığı kabul etmelidir', 'Beklenen faydası 40 birim artacağı için ortaklığı kabul etmelidir', 'Beklenen faydası değişmeyeceği için ortaklığa karşı kayıtsız kalmalıdır'], 'Mevcut fayda: U(14.400) = 20 × √14.400 = 20 × 120 = 2.400 birim! Ortaklığa girerse: Kazançta servet = 14.400 + 11.200 = 25.600 TL => √25.600 = 160, U = 20 × 160 = 3.200 birim. Zararda servet = 14.400 - 8.000 = 6.400 TL => √6.400 = 80, U = 20 × 80 = 1.600 birim? DİKKAT: 0,5(3.200) + 0,5(1.600) = 2.400 eşit çıktı!! İyi ki kontrol ettim! Kazancı 11.200 yerine 8.100 TL yapalım: 14.400 + 8.100 = 22.500 TL (√22.500 = 150!!). Kontrol: Ortaklığın beklenen parasal kazancı = 0,5(+8.100) + 0,5(-8.000) = +50 TL (pozitif!) veya daha belirgin pozitif olsun: zararı -6.300 TL yapalım! 14.400 - 6.300 = 8.100 TL (√8.100 = 90!), kazancı +8.100 TL (22.500 TL, √=150) olursa 0,5(150)+0,5(90)=120 yine eşit! Kazancı +5.200 TL yapalım: 14.400 + 5.200 = 19.600 TL (√19.600 = 140!), zararı -4.400 TL yapalım: 14.400 - 4.400 = 10.000 TL (√10.000 = 100!) yine 120! Çünkü (120+d) ve (120-d) simetrik kök verir! Asimetrik kök seçelim: 150 ve 80!! Yani kazançta 22.500 TL (+8.100 TL kazanç), zararda 6.400 TL (-8.000 TL zarar) -> EMV = +50 TL; daha büyük EMV için: 160 ve 70! Kazançta 25.600 TL (+11.200 TL kazanç), zararda 4.900 TL (-9.500 TL zarar)!! Harika! Kontrol edelim: EMV = 0,5(+11.200) + 0,5(-9.500) = +850 TL pozitif beklenen kazanç! Ama beklenen fayda: 0,5 × (20 × 160) + 0,5 × (20 × 70) = 0,5(3.200) + 0,5(1.400) = 1.600 + 700 = 2.300 birim! Mevcut fayda 2.400 birim olduğundan beklenen faydası 100 birim düşer ve ortaklığı REDDEDER! Çok şık!'),
  ('Bir marangoz atölyesi fuar için özel ahşap satranç takımı üretecektir. Takım başına maliyet 300 TL, fuar satış fiyatı 750 TL ve fuar sonrası toptancıya devir fiyatı 150 TL\'dir. Fuar talebi 10 ile 25 takım arasında (uç değerler dahil, toplam 16 tam sayı değer) kesikli tekdüze dağıldığına göre beklenen kârı maksimize eden üretim adedi kaç takımdır?', '21', ['20 adet satranç takımı', '18 adet satranç takımı', '22 adet satranç takımı'], 'Cu = 750 - 300 = 450 TL; Co = 300 - 150 = 150 TL. Kritik oran = 450 / (450 + 150) = 450 / 600 = 0,75! 10\'dan 25\'e kadar 16 tam sayı değerin her birinin olasılığı 1/16\'dır! F(Q) = (Q - 10 + 1) / 16 ≥ 0,75 => Q - 9 ≥ 12 => Q ≥ 21!! DİKKAT: F(21) = 12/16 = 0,75 TAM EŞİT çıktı! Eşitlikte 21 ve 22 aynı beklenen kârı verir!! İkilik olmaması için aralığı 11 ile 25 (toplam 15 tam sayı değer, her biri 1/15 olasılıklı) yapalım!! Kontrol: 11\'den 25\'e 15 değer var. F(Q) = (Q - 10) / 15 ≥ 0,75 => Q - 10 ≥ 11,25 => Q ≥ 21,25 => Q* = 22 takım TEK VE KESİN MAKSİMUMDUR! Doğrulama: F(21) = 11/15 ≈ 0,7333 < 0,75; F(22) = 12/15 = 0,80 > 0,75! İYİ Kİ KONTROL ETTİM! Aralığı 11 ile 25 takım yapıp doğru cevabı 22 yapıyorum!'),
  ('Karar vericinin servetine göre tanımlanan Arrow-Pratt mutlak riskten kaçınma katsayısı r(W) = -U\'\'(W) / U\'(W) biçimindedir. Logaritmik fayda fonksiyonu U(W) = ln(W) kullanan bir yatırımcının serveti arttıkça aynı büyüklükteki sabit parasal (örneğin ±5.000 TL\'lik) bir riske karşı istediği risk primi nasıl değişir?', 'Mutlak riskten kaçınma katsayısı 1/W ile ters orantılı olduğu için servet arttıkça azalır', ['Logaritmik fonksiyon sabit mutlak riskten kaçınma sergilediği için hiç değişmez', 'Servet arttıkça kaybedilecek toplam varlık büyüdüğü için doğrusal olarak artar', 'Servet ilk iki katına çıktığında artar, daha sonraki artışlarda ise sabitlenir'], 'U(W) = ln(W) için U\'(W) = 1/W ve U\'\'(W) = -1/W² olduğundan r(W) = 1/W\'dir (azalan mutlak riskten kaçınma - DARA); servet büyüdükçe sabit tutarlı bir kumar için talep edilen risk primi azalır.'),
  ('Bir beyaz eşya servisi sattığı kombiler için 5 yıllık "Tam Bakım ve Parça" sözleşmesini peşin 4.200 TL\'ye sunmaktadır. 5 yıllık sürede sözleşme kapsamındaki rutin bakım maliyeti kesin olarak toplam 1.800 TL\'dir. Ayrıca 5 yıl içinde eşanjör arızası çıkma olasılığı 0,12 (maliyet 8.000 TL) ve pompa arızası çıkma olasılığı 0,20\'dir (maliyet 3.500 TL). Servisin sözleşme başına beklenen net kârı kaç TL\'dir?', '740 TL', ['900 TL sözleşme kârı', '620 TL sözleşme kârı', '1.140 TL beklenen kazanç'], 'Kesin bakım gideri = 1.800 TL. Beklenen arıza gideri = 0,12(8.000) + 0,20(3.500) = 960 + 700 = 1.660 TL. Toplam beklenen maliyet = 1.800 + 1.660 = 3.460 TL. Beklenen net kâr = 4.200 - 3.460 = 740 TL!'),
  ('Bir balıkçı teknesi sabah mezattan kasası 800 TL\'ye taze lüfer alıp restoranlara kasası 1.300 TL\'ye satmakta, akşam elinde kalan kasaları ise dondurulmuş balık tesisine 550 TL\'ye vermektedir. Günlük restoran talebinin olasılıkları: 12 kasa (0,20), 13 kasa (0,25), 14 kasa (0,30), 15 kasa (0,15) ve 16 kasa (0,10) şeklindedir. Balıkçının beklenen kârını maksimize eden alım miktarı kaç kasadır?', '14', ['13 kasa günlük alım', '15 kasa günlük alım', '12 kasa günlük alım'], 'Cu = 1.300 - 800 = 500 TL; Co = 800 - 550 = 250 TL. Kritik oran = 500 / (500 + 250) = 500 / 750 = 2/3 ≈ 0,6667. Kümülatif olasılıklar: F(12) = 0,20; F(13) = 0,45; F(14) = 0,75 ≥ 0,6667! Optimal alım miktarı 14 kasadır!'),
  ('Bir yazılım şirketi geliştirdiği mobil uygulamayı ya "Ücretsiz + Reklamlı" ya da "Ücretli Abonelik" modeliyle yayımlayacaktır. Kullanıcı ilgisi yüksek olursa (olasılık p) reklamlı model 400 bin TL, abonelik modeli 550 bin TL kazandırır; kullanıcı ilgisi düşük olursa (olasılık 1 - p) reklamlı model 160 bin TL, abonelik modeli 70 bin TL kazandırır. p = 0,30 olduğunda kusursuz pazar bilgisinin beklenen değeri (EVPI) kaç bin TL\'dir?', '45 bin TL', ['63 bin TL bilgi değeri', '36 bin TL bilgi değeri', '54 bin TL bilgi değeri'], 'p = 0,30 için: E(Reklamlı) = 0,30(400) + 0,70(160) = 120 + 112 = 232 bin TL. E(Abonelik) = 0,30(550) + 0,70(70) = 165 + 49 = 214 bin TL. Bilgisiz en iyi karar: Reklamlı (232 bin TL). Kusursuz bilgiyle: Yüksek ilgide Abonelik (550), düşük ilgide Reklamlı (160) seçilir => EVwPI = 0,30(550) + 0,70(160) = 165 + 112 = 277 bin TL. EVPI = 277 - 232 = 45 bin TL! (Kontrol: Reklamlı seçildiğinde sadece yüksek ilgide 550 - 400 = 150 kayıp var; 0,30 × 150 = 45 bin TL!). %100 doğru!'),
  ('Bir nakliyat firması şehirler arası ev taşıma işlemlerinde müşterilerine 900 TL karşılığında "Tam Eşya Sigortası" sunmaktadır. Taşımaların %85\'inde hiçbir hasar oluşmamakta, %12\'sinde ufak çizik ve kırıklar (ortalama 3.500 TL ödeme) ve %3\'ünde ağır eşya hasarı (ortalama 12.000 TL ödeme) meydana gelmektedir. Firmanın sigortalı taşıma başına beklenen net sigorta sonucu nedir?', '+120 TL beklenen kâr', ['-80 TL beklenen zarar', '+180 TL beklenen kâr', '+60 TL sigorta katkısı'], 'Beklenen hasar ödemesi = 0,85(0) + 0,12(3.500) + 0,03(12.000) = 420 + 360 = 780 TL. Beklenen net sigorta sonucu = 900 - 780 = +120 TL beklenen kâr.'),
  ('Bir özel klinik öğleden sonra seansı için 12 doktor randevu kotası olmasına rağmen 14 hastaya randevu vermektedir. Randevu alan 14 hastadan 12 veya daha azının gelme olasılığı 0,65; 13 hastanın gelme olasılığı 0,25 ve 14 hastanın gelme olasılığı 0,10\'dur. Kotayı aşan her hasta için 900 TL ek mesai gideri oluştuğuna göre 14 randevu vermenin beklenen ek mesai gideri kaç TL\'dir?', '405 TL', ['315 TL beklenen mesai', '495 TL beklenen mesai', '540 TL fazla çalışma'], 'Beklenen fazla hasta = 1(0,25) + 2(0,10) = 0,45 kişi. Beklenen ek gider = 0,45 × 900 = 405 TL.'),
  ('Bir çiçekçi özel bir gün için tanesi 25 TL\'den buket hazırlayıp 85 TL\'ye satmaktadır; gün sonunda satılamayan buketlerin hurda değeri sıfırdır. Buket talebinin olasılık dağılımı: 100 adet (0,15), 110 adet (0,25), 120 adet (0,35) ve 130 adet (0,25) şeklindedir. Beklenen kârı maksimize eden hazırlık miktarı kaç bukettir?', '120', ['110 buketlik hazırlık', '130 buketlik hazırlık', '100 buketlik hazırlık'], 'Cu = 60, Co = 25 => Kritik oran = 60 / 85 ≈ 0,7059. Kümülatif olasılıklarda F(110)=0,40 ve F(120)=0,75 ≥ 0,7059 olduğundan optimal miktar 120 adettir.'),
  ('Bir ilaç firması yeni bir molekülün patentini bugün kesin 18 milyon TL\'ye satabilir veya 10 milyon TL harcayarak klinik deneye girebilir. Deney %50 olasılıkla başarılı olur; başarılı olursa firma ürünü ya 46 milyon TL net gelirle kendisi pazarlayacak ya da 40 milyon TL\'ye lisanslayacaktır. Deney başarısız olursa gelir sıfırdır. Beklenen parasal değere göre optimal ilk karar ve beklenen net getirisi nedir?', 'Patenti satmak; 18 milyon TL', ['Klinik deneye girmek; 23 milyon TL', 'Klinik deneye girmek; 18 milyon TL', 'Patenti satmak; 13 milyon TL'], 'Deney başarılı olursa max(46, 40) = 46 milyon TL seçilir. Klinik deneyin beklenen net değeri = -10 + 0,50(46) = 13 milyon TL < 18 milyon TL olduğundan patent satılır.'),
  ('Bir otobüs firması 40 koltuklu aracına 41 bilet satmayı değerlendirmektedir. Bilet ücreti 600 TL olup gelmeyen yolcuya ücret iadesi yapılmamaktadır. 41 bilet satıldığında tüm yolcuların terminale gelme olasılığı 0,28\'dir ve açıkta kalan 1 yolcuya bilet iadesi dahil toplam 2.000 TL ödenmektedir. 40 yerine 41. bileti satmanın firmaya beklenen marjinal katkısı kaç TL\'dir?', '+40 TL', ['+168 TL marjinal katkı', '-80 TL marjinal zarar', '+208 TL marjinal katkı'], 'Kesin tahsilat +600 TL, beklenen tazminat çıkışı 0,28 × 2.000 = 560 TL; net marjinal katkı = 600 - 560 = +40 TL.'),
  ('Bir kargo şirketi taşınan koliler için 55 TL\'ye isteğe bağlı "Kırılma Güvencesi" satmaktadır. Müşterilerin %40\'ı bu güvenceyi satın almaktadır. Koli başına kırılma olasılığı tüm kolilerde 0,015 olup güvenceli bir koli kırıldığında müşteriye 2.400 TL ödenmektedir. Şirketin taşıdığı toplam 1.000 koli başına bu güvence hizmetinden elde edeceği beklenen net kâr kaç TL\'dir?', '7.600 TL', ['19.000 TL toplam net kâr', '9.500 TL toplam net kâr', '6.400 TL beklenen kazanç'], '1.000 kolinin 400\'ü güvencelidir. Güvenceli koli başına beklenen kâr = 55 - 0,015(2.400) = 55 - 36 = 19 TL. Toplam = 400 × 19 = 7.600 TL.'),
  ('Bir sigorta piyasasında kaza olasılığı yüksek sürücülerin düşük riskli sürücülere kıyasla ortalama fiyattan sunulan poliçeyi satın almaya çok daha istekli olması ve sigorta havuzunun beklenen maliyetini yükseltmesi hangi kavramla ifade edilir?', 'Ters seçim (aleyhte seçilim)', ['Ahlaki tehlike (moral hazard)', 'Azalan marjinal fayda yasası', 'Portföy çeşitlendirme etkisi'], 'Sözleşme öncesinde yüksek riskli bireylerin havuza orantısız biçimde katılması ters seçimdir.'),
  ('Bir üniversite yaz okulu dersine en fazla 30 öğrenci kabul edebilmektedir. 32 ön kayıt alındığında derse kesin devam edecek öğrenci sayısının 30 veya daha az olma olasılığı 0,80; 31 olma olasılığı 0,15 ve 32 olma olasılığı 0,05\'tir. Kontenjanı aşan her öğrenci için ek telafi maliyeti 3.000 TL olduğuna göre 32 ön kayıt almanın beklenen aşım maliyeti kaç TL\'dir?', '750 TL', ['600 TL beklenen aşım', '900 TL beklenen aşım', '450 TL telafi gideri'], 'Beklenen aşım = 1(0,15) + 2(0,05) = 0,25 öğrenci; beklenen maliyet = 0,25 × 3.000 = 750 TL.'),
  ('Bir güneş enerjisi paneli satıcısı panellere 5 yıllık verim garantisi vermektedir. 5 yıl içinde panel veriminin eşik değerin altına düşme olasılığı 0,04\'tür. Verim düştüğünde panel %75 olasılıkla 2.000 TL bakım gideriyle kurtarılmakta, %25 olasılıkla 10.000 TL maliyetle değiştirilmektedir. Panel başına beklenen garanti maliyeti kaç TL\'dir?', '160 TL', ['120 TL beklenen maliyet', '200 TL beklenen maliyet', '240 TL garanti gideri'], 'Verim düştüğünde koşullu beklenen maliyet = 0,75(2.000) + 0,25(10.000) = 4.000 TL; genel beklenen maliyet = 0,04 × 4.000 = 160 TL.'),
  ('Bir maden şirketi ruhsat sahibi olduğu sahada 12 milyon TL maliyetle sondaj yapabilir veya sondaj yapmadan ruhsatı bugün 14 milyon TL\'ye devredebilir. Sondaj yapılırsa %25 olasılıkla zengin rezerv (işletme net değeri 80 milyon TL), %35 olasılıkla orta rezerv (işletme net değeri 20 milyon TL) ve %40 olasılıkla boş kuyu (0 TL) çıkacaktır. Optimal karar nedir?', 'Sondaj yapmak; beklenen net değeri 15 milyon TL\'dir', ['Ruhsatı bugün devretmek; 14 milyon TL daha yüksektir', 'Sondaj yapmak; beklenen net değeri 27 milyon TL\'dir', 'Ruhsatı bugün devretmek; sondajın beklenen değeri 11 milyon TL\'dir'], 'Sondajın beklenen net değeri = -12 + 0,25(80) + 0,35(20) = -12 + 20 + 7 = 15 milyon TL (> 14 milyon TL).'),
  ('Fayda fonksiyonu 0 ≤ x ≤ 200 aralığında U(x) = 400x - x² olan bir karar vericiye %50 olasılıkla 180 birim, %50 olasılıkla 60 birim kazandıran bir çekiliş bileti verilmiştir. Bu karar vericinin çekiliş biletini satmak için kabul edeceği en düşük kesin fiyat (kesinlik eşdeğeri) kaç birimdir?', '100 birim', ['120 birim kesin fiyat', '110 birim kesin fiyat', '90 birim kesin fiyat'], 'U(180) = 39.600, U(60) = 20.400 => E[U] = 30.000. 400c - c² = 30.000 => (c - 100)(c - 300) = 0; geçerli aralıkta c = 100 birimdir.'),
  ('Bir fırın Ramazan pidesinin tanesini 12 TL\'ye mal edip iftar öncesinde 27 TL\'ye satmakta, kalanları iftar sonrasında 7 TL\'ye yemekhanelere vermektedir. Günlük talep ortalaması 400 ve standart sapması 100 olan normal dağılıma uymaktadır. Standart normal dağılımda P(Z ≤ 0,67) = 0,75 olduğuna göre beklenen kârı maksimize eden günlük pide üretim adedi kaçtır?', '467', ['450 adet günlük pide', '475 adet günlük pide', '333 adet günlük pide'], 'Cu = 15, Co = 5 => Kritik oran = 15 / 20 = 0,75 => z = 0,67. Q* = 400 + 0,67 × 100 = 467 adet.'),
  ('Bir e-ticaret sitesi kahve makinelerinde 1 yıllık "Anında Yenileme" paketini 180 TL\'ye sunmaktadır. Normalde makinelerin %4\'ü bir yılda bozulurken, paketi alan müşterilerin dikkatsiz kullanımı yüzünden bu grupta bozulma oranı %6,5\'e çıkmaktadır. Yenileme maliyeti 2.400 TL olduğuna göre site bu davranış değişimini göz ardı ederse paket başına beklenen kârını kaç TL fazla tahmin etmiş olur?', '60 TL', ['84 TL fazla tahmin', '48 TL fazla tahmin', '96 TL hesaplama hatası'], 'Göz ardı edilen ek arıza olasılığı %6,5 - %4,0 = %2,5\'tir; 0,025 × 2.400 = 60 TL maliyet eksik (kâr fazla) tahmin edilir.'),
  ('İki aşamalı bir Ar-Ge projesinde 1. aşama 5 milyon TL harcama gerektirir ve %60 olasılıkla teknik onay alır. Onay alınırsa 15 milyon TL ek yatırımla 2. aşamaya geçilebilir (onay sonrası vazgeçilirse ek gelir ve gider sıfırdır). 2. aşama %50 olasılıkla 70 milyon TL, %50 olasılıkla 10 milyon TL brüt gelir sağlar. 1. aşamada onay alınamazsa proje 0 TL gelirle biter. Projenin başlangıçtaki beklenen net değeri kaç milyon TL\'dir?', '10 milyon TL', ['7 milyon TL net değer', '15 milyon TL net değer', '19 milyon TL net değer'], '2. aşama net beklenen değeri = -15 + 0,5(70) + 0,5(10) = 25 milyon TL (> 0, devam edilir). Başlangıç beklenen net değeri = -5 + 0,60(25) = 10 milyon TL.'),
  ('Bir tekstil atölyesi fason dikim için iki makine seçeneğini değerlendirmektedir. M1 makinesinin sabit kirası 35.000 TL, parça başı net katkısı 50 TL\'dir. M2 makinesinin sabit kirası 65.000 TL, parça başı net katkısı 80 TL\'dir. Sipariş miktarının 800 parça olma olasılığı 0,40; 1.300 parça olma olasılığı 0,60\'tır. Beklenen net kârı en yüksek olan makine ve beklenen net kârı nedir?', 'M2 makinesi; 23.000 TL', ['M1 makinesi; 20.000 TL', 'M2 makinesi; 19.000 TL', 'M1 makinesi; 25.000 TL'], 'Beklenen sipariş E(Q) = 0,40(800) + 0,60(1.300) = 1.100 parça. E(M1) = 50(1.100) - 35.000 = 20.000 TL; E(M2) = 80(1.100) - 65.000 = 23.000 TL.'),
  ('Bir sigorta şirketi portföyündeki birbirinden bağımsız 4.900 aracın her biri için yıllık cam kırılma olasılığını 0,02 ve sabit değişim maliyetini 10.000 TL olarak hesaplamıştır. Şirket araç başına 250 TL prim topladığına göre portföyün tamamından elde edilecek yıllık toplam net kazancın beklenen değeri ve standart sapması sırasıyla kaç TL\'dir?', '245.000 TL ve 98.000 TL', ['245.000 TL ve 100.000 TL', '980.000 TL ve 98.000 TL', '225.000 TL ve 49.000 TL'], 'Toplam prim = 1.225.000 TL, beklenen hasar = 4.900×0,02×10.000 = 980.000 TL => E(Net) = 245.000 TL. σ = √(4.900×0,02×0,98) × 10.000 = 9,8 × 10.000 = 98.000 TL.'),
  ('Bir restoran zinciri yeni şube yeri için "AVM İçi" veya "Cadde Üstü" alternatiflerini değerlendirmektedir. AVM içi şube yaya trafiği yüksekse 300 bin TL, düşükse 100 bin TL yıllık kâr bırakmaktadır. Cadde üstü şube ise trafik yüksekse 420 bin TL, düşükse -40 bin TL yıllık kâr getirmektedir. Riske nötr yönetimin Cadde Üstü seçeneğini tercih etmesi için yüksek trafik olasılığı en az kaçtan büyük olmalıdır?', '7/13', ['1/2 eşik olasılığı', '5/11 eşik olasılığı', '8/15 eşik olasılığı'], '420p - 40(1 - p) > 300p + 100(1 - p) => -40 + 460p > 100 + 200p => 260p > 140 => p > 7/13.'),
  ('Bir konser salonu 500 kişilik VIP bölümüne biletlerini 1.000 TL\'den iadesiz olarak peşin satmaktadır. Yönetim 502 bilet sattığında konsere gelen kişi sayısının 500 veya daha az olma olasılığı 0,75; 501 olma olasılığı 0,15 ve 502 olma olasılığı 0,10\'dur. Fazladan gelen her VIP misafir için 3.200 TL ek maliyet oluştuğuna göre 500 yerine 502 bilet satmanın beklenen ek net kârı kaç TL\'dir?', '+880 TL', ['+1.200 TL ek net kâr', '+640 TL ek net kâr', '-120 TL beklenen zarar'], 'Ek bilet geliri = 2 × 1.000 = 2.000 TL. Beklenen aşım maliyeti = [1(0,15) + 2(0,10)] × 3.200 = 0,35 × 3.200 = 1.120 TL. Net ek kâr = 2.000 - 1.120 = +880 TL.'),
  ('Üstel fayda fonksiyonuna U(x) = 1 - e^(-x/1000) sahip olan bir karar vericinin mevcut servetine kesin 5.000 TL eklendiğinde, önündeki (%50 olasılıkla +2.000 TL, %50 olasılıkla 0 TL getiren) bir yatırım kurasının risk primi nasıl değişir?', 'Hiç değişmez; risk primi sabit kalır', ['Risk primi yarı yarıya düşer', 'Risk primi tam 5.000 TL artar', 'Risk primi sıfıra inerek nötrleşir'], 'Üstel fayda fonksiyonu sabit mutlak riskten kaçınma (CARA) özelliğine sahiptir; servet değişimi kuranın risk primini etkilemez.'),
  ('Bir süt ürünleri bayisi günlük organik süt şişelerini 30 TL\'den alıp 50 TL\'ye satmakta, satılmayanları akşam 10 TL\'ye mandıraya iade etmektedir. Bayi günlük sabit 80 şişe sipariş verdiğinde talebin 60 şişe olma olasılığı 0,25; 80 şişe olma olasılığı 0,45 ve 100 şişe olma olasılığı 0,30\'dur. Bu politikayla bayinin günlük beklenen net kârı kaç TL\'dir?', '1.400 TL', ['1.600 TL beklenen kâr', '1.250 TL beklenen kâr', '1.500 TL günlük kazanç'], 'Talep 60 iken kâr = 60(20) - 20(20) = 800 TL; talep 80 veya 100 iken (toplam olasılık 0,75) kâr = 80(20) = 1.600 TL. Beklenen kâr = 0,25(800) + 0,75(1.600) = 1.400 TL.'),
  ('Bir müze geçici sergi için birim basım maliyeti 50 TL, satış fiyatı 130 TL ve sergi sonu geri dönüşüm değeri 10 TL olan katalog bastıracaktır. Toplam talebin 1.000 adet (0,20), 1.500 adet (0,45) veya 2.000 adet (0,35) olacağı tahmin edildiğine göre optimal basım adedinde beklenen net kâr kaç TL\'dir?', '109.000 TL', ['108.000 TL beklenen kâr', '112.000 TL beklenen kâr', '96.000 TL sergi kazancı'], 'Cu=80, Co=40 => Kritik oran = 2/3. F(1.500)=0,65 < 2/3 ve F(2.000)=1,00 ≥ 2/3 olduğundan Q*=2.000. E(Satış)=1.575, E(Kalan)=425 => 1.575(80) - 425(40) = 109.000 TL.'),
  ('Fayda fonksiyonu U(x) = √x olan bir yarışmacı 25.600 TL ödüle ulaşmıştır. Çekilirse bu tutarı kesin alacak; son soruyu yanıtlarsa doğru bildiğinde ödülü 62.500 TL\'ye çıkacak, yanlış bildiğinde ise 6.400 TL\'ye düşecektir. Yarışmacının son soruyu yanıtlamayı tercih etmesi için soruyu doğru bilme olasılığı en az kaçtan büyük olmalıdır?', '8/17', ['1/2 eşik olasılığı', '19/37 eşik olasılığı', '9/17 eşik olasılığı'], '√25.600 = 160, √62.500 = 250, √6.400 = 80. 250p + 80(1 - p) > 160 => 170p > 80 => p > 8/17.'),
  ('Aynı kapasiteli uçakların kullanıldığı, bilet fiyatlarının ve açıkta kalma tazminatlarının eşit olduğu iki uçuş hattından A (tatil) hattında yolcuların uçuşa gelmeme oranı %15 iken, B (iş seyahati) hattında gelmeme oranı %4\'tür. Geliri maksimize eden fazla rezervasyon (overbooking) adedi hakkında hangisi doğrudur?', 'A hattında daha yüksek (veya eşit) sayıda fazla rezervasyon yapılır', ['B hattında iş yolcuları yoğun olduğu için daha fazla rezervasyon yapılır', 'Kapasite ve bilet fiyatları eşit olduğundan her iki hatta da eşit sayıda yapılır', 'Tazminat tutarı bilet fiyatından büyükse her iki hatta da sıfır fazla satış yapılır'], 'Gelmeme (no-show) oranı yükseldikçe koltukların boş kalma olasılığı artar ve taşma riski düşer; bu nedenle A hattında optimal fazla satış daha yüksektir.'),
  ('Bir donanım üreticisi ekran kartlarına 3 yıl garanti vermektedir. Kartların %92\'si sorunsuz çalışmakta, %5\'i fan arızası (onarım 800 TL) ve %3\'ü işlemci arızası (değişim 7.000 TL) yapmaktadır. Üretici kart başına 25 TL ek üretim maliyetiyle fan tasarımını yenilerse fan arızası olasılığı %5\'ten %1\'e düşmektedir. Üretici bu yenilemeyi yapmalı mıdır?', 'Evet; kart başına beklenen toplam maliyeti net 7 TL azaltır', ['Hayır; kart başına beklenen toplam maliyeti 5 TL artırır', 'Evet; kart başına beklenen toplam maliyeti net 15 TL azaltır', 'Hayır; fan arızası tasarrufu ek üretim maliyetinin altında kalır'], 'Fan arızası beklenen tasarrufu = (0,05 - 0,01) × 800 = 32 TL; ek üretim maliyeti 25 TL düşüldüğünde net 7 TL maliyet azalışı sağlanır.'),
  ('Bir yayınevi yeni romanı için ilk baskıda 3.000 veya 6.000 adet basacaktır. Birim maliyet 40 TL, kitapçıya net satış fiyatı 110 TL ve satılmayan kitapların hurda değeri sıfırdır. Romanın 6.000 adet satma olasılığı 0,45 ve 3.000 adet satma olasılığı 0,55 olduğuna göre optimal baskı adedi ve beklenen net kârı nedir?', '6.000 adet; 238.500 TL', ['3.000 adet; 210.000 TL', '6.000 adet; 247.500 TL', '3.000 adet; 252.000 TL'], 'E(3.000) = 3.000 × 70 = 210.000 TL. E(6.000) = 0,45(420.000) + 0,55(90.000) = 189.000 + 49.500 = 238.500 TL.'),
  ('Bir marangoz atölyesi fuar için takım başına 300 TL maliyetle ahşap satranç takımı üretip 750 TL\'ye satacak, kalanları fuar sonunda 150 TL\'ye devredecektir. Fuar talebi 11 ile 25 takım arasında (uçlar dahil 15 tam sayı değer) kesikli tekdüze dağıldığına göre beklenen kârı maksimize eden üretim adedi kaç takımdır?', '22', ['21 adet satranç takımı', '20 adet satranç takımı', '23 adet satranç takımı'], 'Cu=450, Co=150 => Kritik oran = 0,75. F(Q) = (Q - 10) / 15 ≥ 0,75 => Q - 10 ≥ 11,25 => Q* = 22 takım.'),
  ('Logaritmik fayda fonksiyonu U(W) = ln(W) kullanan bir yatırımcının Arrow-Pratt mutlak riskten kaçınma katsayısı r(W) = -U\'\'(W) / U\'(W) dikkate alındığında, serveti arttıkça sabit parasal büyüklükteki (örneğin ±5.000 TL\'lik) bir riske karşı talep ettiği risk primi nasıl değişir?', 'Mutlak riskten kaçınma katsayısı 1/W olduğu için servet arttıkça azalır', ['Logaritmik fonksiyon sabit mutlak riskten kaçınma sergilediği için hiç değişmez', 'Servet arttıkça kaybedilecek toplam varlık büyüdüğü için doğrusal olarak artar', 'Servet ilk iki katına çıktığında artar, daha sonraki artışlarda ise sabitlenir'], 'U\'(W)=1/W ve U\'\'(W)=-1/W² olduğundan r(W)=1/W\'dir; servet büyüdükçe sabit tutarlı kumar için istenen risk primi azalır.'),
  ('Bir balıkçı sabah mezattan kasası 800 TL\'ye lüfer alıp restoranlara 1.300 TL\'ye satmakta, akşam kalan kasaları 550 TL\'ye dondurulmuş gıda tesisine vermektedir. Günlük talep olasılıkları: 12 kasa (0,20), 13 kasa (0,25), 14 kasa (0,30), 15 kasa (0,15) ve 16 kasa (0,10) olduğuna göre beklenen kârı maksimize eden alım miktarı kaç kasadır?', '14', ['13 kasa günlük alım', '15 kasa günlük alım', '12 kasa günlük alım'], 'Cu = 500, Co = 250 => Kritik oran = 500 / 750 = 2/3. Kümülatif dağılımda F(13)=0,45 ve F(14)=0,75 ≥ 2/3 olduğundan optimal alım 14 kasadır.'),
  ('Bir nakliyat firması ev taşıma işlemlerinde 900 TL karşılığında "Tam Eşya Sigortası" sunmaktadır. Taşımaların %85\'inde hasar çıkmamakta, %12\'sinde küçük hasar (ortalama 3.500 TL ödeme) ve %3\'ünde ağır hasar (ortalama 12.000 TL ödeme) oluşmaktadır. Sigortalı taşıma başına firmanın beklenen net sigorta sonucu nedir?', '+120 TL beklenen kâr', ['-80 TL beklenen zarar', '+180 TL beklenen kâr', '+60 TL sigorta katkısı'], 'Beklenen ödeme = 0,12(3.500) + 0,03(12.000) = 420 + 360 = 780 TL; beklenen net sonuç = 900 - 780 = +120 TL kâr.'),
];
